// 由 scripts/build-ui.mjs 生成，**请勿手工编辑**。
// 源在 admin-ui/，改完那边跑 `pnpm ui:build`。产物与源逐字节相同（tests/unit/ui-assets.test.ts 钉死）。
export interface UiAsset {
  readonly body: string;
  readonly type: string;
  readonly etag: string;
}

export const UI_ASSETS: Readonly<Record<string, UiAsset>> = {
  "/admin": { body: "<!doctype html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta name=\"theme-color\" content=\"#f7f8fa\">\n<title>agnes2api 管理后台</title>\n<!-- 唯一的经典脚本，必须同步、必须在 CSS 之前：防闪白 / 闪错语言。 -->\n<script src=\"/admin/js/boot.js\"></script>\n<link rel=\"stylesheet\" href=\"/admin/css/base.css\">\n<link rel=\"stylesheet\" href=\"/admin/css/shell.css\">\n<link rel=\"stylesheet\" href=\"/admin/css/sections.css\">\n</head>\n<body>\n<div class=\"gate\" id=\"gate\">\n  <form class=\"gate-card\" id=\"gate-form\">\n    <h1 data-i18n=\"gate.title\">agnes2api 管理后台</h1>\n    <p class=\"sub\" data-i18n=\"gate.sub\">请输入管理口令（ADMIN_TOKEN）</p>\n    <label for=\"gate-key\" data-i18n=\"gate.label\">管理口令</label>\n    <input id=\"gate-key\" type=\"password\" autocomplete=\"current-password\"\n           data-i18n-ph=\"gate.placeholder\" placeholder=\"ADMIN_TOKEN\">\n    <button type=\"submit\" data-i18n=\"gate.submit\">进入</button>\n    <div class=\"err\" id=\"gate-err\" role=\"alert\"></div>\n  </form>\n</div>\n\n<div class=\"shell\" id=\"shell\">\n  <aside class=\"side\">\n    <div class=\"brand\">agnes2api</div>\n    <nav>\n      <button class=\"nav-item\" data-section=\"overview\" data-i18n=\"nav.overview\">概览</button>\n      <button class=\"nav-item\" data-section=\"keys\" data-i18n=\"nav.keys\">Key 池</button>\n      <button class=\"nav-item\" data-section=\"events\" data-i18n=\"nav.events\">事件</button>\n    </nav>\n    <div class=\"side-foot\">\n      <select id=\"lang-select\" data-i18n-title=\"shell.lang\"></select>\n      <button id=\"theme-btn\" class=\"icon-btn\" data-i18n-title=\"shell.theme\"></button>\n      <button id=\"logout-btn\" class=\"icon-btn\" data-i18n-title=\"shell.logout\"></button>\n    </div>\n  </aside>\n  <main class=\"main\">\n    <section class=\"section\" id=\"sec-overview\"></section>\n    <section class=\"section\" id=\"sec-keys\"></section>\n    <section class=\"section\" id=\"sec-events\"></section>\n  </main>\n</div>\n\n<div id=\"toast-host\" class=\"toast-host\" aria-live=\"polite\"></div>\n<script type=\"module\" src=\"/admin/js/app.js\"></script>\n</body>\n</html>\n", type: "text/html; charset=utf-8", etag: "\"75bafa92c9dfcd8b\"" },
  "/admin/css/base.css": { body: "/* 所有颜色一律引用变量，零硬编码色值。主色用 indigo（不是 kiro2api 的 emerald）：\n   同一个运维会同时开着两个结构一模一样的面板，颜色是最快最可靠的区分信号。\n\n   本文件只放**组件原语 token** + 跨页面共用的基础重置/控件样式。外壳布局\n   （侧栏、登录闸、toast、modal）在 shell.css；业务内容（表格、卡片、徽章）\n   在 sections.css。两份都只覆盖 :root 的 token，不重复定义组件规则\n   （见两个文件各自的文件头）。 */\n:root {\n  --bg: #f7f8fa; --panel: #ffffff; --panel-2: #f0f1f5; --text: #1c1f26; --muted: #6b7280;\n  --border: #e3e6ec; --primary: #4f46e5; --primary-fg: #ffffff;\n  --danger: #dc2626; --danger-fg: #ffffff; --warn: #b45309; --warn-fg: #ffffff;\n  --ok: #15803d; --ok-fg: #ffffff;\n  --radius: 10px; --radius-sm: 6px; --gap: 16px; --gap-sm: 8px;\n  --shadow: rgba(15, 18, 24, 0.12);\n}\n:root[data-theme=\"dark\"] {\n  --bg: #14161a; --panel: #1c1f26; --panel-2: #23262f; --text: #e7e9ee; --muted: #9aa1ad;\n  --border: #2b303a; --primary: #818cf8; --primary-fg: #14161a;\n  --danger: #f87171; --danger-fg: #14161a; --warn: #fbbf24; --warn-fg: #14161a;\n  --ok: #4ade80; --ok-fg: #14161a;\n  --shadow: rgba(0, 0, 0, 0.4);\n}\n* { box-sizing: border-box; }\nbody {\n  margin: 0; background: var(--bg); color: var(--text);\n  font: 14px/1.6 system-ui, -apple-system, \"Segoe UI\", \"PingFang SC\", \"Microsoft YaHei\", sans-serif;\n}\na { color: var(--primary); }\n:focus-visible { outline: 2px solid var(--primary); outline-offset: 2px; }\n\n/* 输入 / 按钮的原语样式：登录闸的表单与 modal 的操作栏共用同一套。 */\nlabel { display: block; margin-bottom: 6px; font-size: 13px; color: var(--muted); }\ninput[type=\"password\"], input[type=\"text\"], select {\n  width: 100%; padding: 10px 12px; color: var(--text); font: inherit;\n  background: var(--bg); border: 1px solid var(--border); border-radius: var(--radius);\n}\nbutton {\n  padding: 10px 12px; font: inherit; cursor: pointer;\n  color: var(--primary-fg); background: var(--primary); border: 0; border-radius: var(--radius);\n}\nbutton[disabled] { opacity: .6; cursor: progress; }\nbutton.danger { background: var(--danger); color: var(--danger-fg); }\n\n/* 图标按钮：侧栏与业务板块共用（svgIcon() 生成的 <svg> 直接放在里面）。 */\n.icon-btn {\n  display: inline-flex; align-items: center; justify-content: center;\n  width: 32px; height: 32px; padding: 0;\n  color: var(--text); background: transparent; border: 1px solid var(--border);\n  border-radius: var(--radius-sm);\n}\n.icon-btn:hover { background: var(--panel-2); }\n", type: "text/css; charset=utf-8", etag: "\"b71053e3c1f4e465\"" },
  "/admin/css/sections.css": { body: "/* 表格、卡片、徽章。业务板块（Task 4 概览 / Task 5 Key 池 / Task 6 事件）的公共\n   内容原语，**只覆盖 base.css 的 token，不重复定义颜色/圆角等原语规则**。\n   Task 3 本身不产出任何业务板块，这份文件先把三类原语定好，供后续任务直接引用。 */\n\n.card {\n  padding: var(--gap); background: var(--panel);\n  border: 1px solid var(--border); border-radius: var(--radius);\n}\n.card + .card { margin-top: var(--gap-sm); }\n.card-row { display: flex; flex-wrap: wrap; gap: var(--gap); }\n.card-row > .card { flex: 1; min-width: 180px; }\n.card .label { color: var(--muted); font-size: 12px; }\n.card .value { margin-top: 4px; font-size: 22px; font-weight: 600; }\n\ntable {\n  width: 100%; border-collapse: collapse; background: var(--panel);\n  border: 1px solid var(--border); border-radius: var(--radius); overflow: hidden;\n}\nth, td {\n  padding: 8px 12px; text-align: left; border-bottom: 1px solid var(--border);\n  font-size: 13px;\n}\nth { color: var(--muted); font-weight: 500; background: var(--panel-2); }\ntr:last-child td { border-bottom: 0; }\n\n.badge {\n  display: inline-block; padding: 2px 8px; font-size: 12px; border-radius: 999px;\n  color: var(--muted); background: var(--panel-2); border: 1px solid var(--border);\n}\n.badge-ok { color: var(--ok-fg); background: var(--ok); border-color: var(--ok); }\n.badge-warn { color: var(--warn-fg); background: var(--warn); border-color: var(--warn); }\n.badge-danger { color: var(--danger-fg); background: var(--danger); border-color: var(--danger); }\n\n/* 工具条 / 分页 / 说明文字：Task 4 的 Key 池板块起用，事件与概览板块同样直接引用，\n   **不许各板块再各写一份**（kiro2api 正是没有这一层，同一个原语出现了三份不同实现）。 */\n.toolbar { display: flex; flex-wrap: wrap; align-items: center; gap: var(--gap-sm); margin: var(--gap-sm) 0; }\n.toolbar input[type=\"search\"] {\n  flex: 1; min-width: 160px; padding: 10px 12px; color: var(--text); font: inherit;\n  background: var(--bg); border: 1px solid var(--border); border-radius: var(--radius);\n}\n.toolbar select { width: auto; }\n.toolbar .auto { display: inline-flex; align-items: center; gap: var(--gap-sm); margin-bottom: 0; }\n.pager { display: flex; align-items: center; gap: var(--gap-sm); margin-top: var(--gap-sm); }\n.muted { color: var(--muted); }\n.note { margin: 4px 0 var(--gap); font-size: 12px; }\n.mono { font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; }\n/* `≈` 标记：它是产品不变式的一部分（近似值必须打标），不是排版装饰。 */\n.approx { color: var(--muted); cursor: help; }\n\n/* 概览板块（Task 5）：常驻红色横幅（config.degraded 时）+ 内容块卡片。 */\n.banner-danger {\n  padding: var(--gap-sm) var(--gap); margin-bottom: var(--gap-sm);\n  color: var(--danger-fg); background: var(--danger); border-radius: var(--radius);\n}\n.banner-danger p { margin: 2px 0; }\n.block { margin-top: var(--gap); }\n.block h3 { margin: 0 0 var(--gap-sm); font-size: 14px; }\n.block p { margin: 4px 0; }\n\n/* 事件板块（Task 6）：级别按钮组 + 轮询状态指示灯 + 滚动容器 + 分组时间线。 */\n.btn-group { display: inline-flex; gap: 2px; flex-wrap: wrap; }\n.btn-toggle {\n  padding: 6px 10px; font: inherit; color: var(--muted);\n  background: var(--panel-2); border: 1px solid var(--border); border-radius: var(--radius);\n}\n.btn-toggle.active { color: var(--text); border-color: var(--primary); }\n/* 轮询状态指示灯：三态用不同颜色，不用文字（title/aria-label 已经带文字说明）。 */\n.poll-dot {\n  display: inline-block; width: 8px; height: 8px; border-radius: 999px;\n  background: var(--muted); margin-left: var(--gap-sm);\n}\n.poll-dot-active { background: var(--ok-fg); }\n.poll-dot-paused { background: var(--muted); }\n.poll-dot-error { background: var(--danger-fg); }\n\n.events-body { max-height: 60vh; overflow-y: auto; }\n.ev-group-header td { padding-top: var(--gap-sm); font-size: 12px; }\n/* 分组内的行左边一条细线，视觉上把同一条时间线的几行连起来。 */\n.ev-row-grouped td:first-child { border-left: 2px solid var(--border); }\n", type: "text/css; charset=utf-8", etag: "\"98d27cebbff79fdf\"" },
  "/admin/css/shell.css": { body: "/* 外壳、侧栏、登录闸、toast、modal。**只覆盖 base.css 里的 token，不重复定义\n   颜色/圆角等原语规则**——[data-theme=\"dark\"] 在 base.css 里已经整体覆盖过一次，\n   这里的组件规则对亮暗两套主题都通用。 */\n\n/* ── 登录闸 ─────────────────────────────────────────────── */\n.gate { display: flex; align-items: center; justify-content: center; min-height: 100vh; padding: var(--gap); }\n.gate-card {\n  width: 100%; max-width: 380px; padding: 28px; background: var(--panel);\n  border: 1px solid var(--border); border-radius: var(--radius);\n}\n.gate-card h1 { margin: 0 0 4px; font-size: 20px; }\n.gate-card p.sub { margin: 0 0 20px; color: var(--muted); font-size: 13px; }\n.gate-card input { margin-bottom: 14px; }\n.gate-card button { width: 100%; }\n.err { min-height: 20px; margin-top: 10px; color: var(--danger); font-size: 13px; }\n/* 登录成功后隐藏登录闸。用类而不是 el.style.display：\n   ⚠️ 理由**不是** CSP——`style-src` 管的是标记里的 `style=\"…\"` 属性与 <style> 元素，\n   **CSSOM 写入（el.style.x = y）不受 CSP 约束**，简报那版其实也跑得通。\n   真正的理由是表现归样式表：`.gate` 的显示方式（现在是 flex）只写在这一个地方，\n   将来改布局不必回头去找 JS 里那句写死的 display 值。 */\n.gate.off { display: none; }\n\n/* ── 外壳（侧栏 + 主内容） ───────────────────────────────── */\n.shell { display: none; }\n.shell.on { display: grid; grid-template-columns: 220px 1fr; min-height: 100vh; }\n.side {\n  display: flex; flex-direction: column; gap: var(--gap);\n  padding: var(--gap); background: var(--panel); border-right: 1px solid var(--border);\n}\n.side .brand { font-weight: 600; font-size: 16px; }\n.side nav { display: flex; flex-direction: column; gap: 4px; }\n.nav-item {\n  text-align: left; padding: 8px 10px; color: var(--text);\n  background: transparent; border: 0; border-radius: var(--radius-sm);\n}\n.nav-item:hover { background: var(--panel-2); }\n.nav-item.active { background: var(--primary); color: var(--primary-fg); }\n.side-foot { margin-top: auto; display: flex; align-items: center; gap: var(--gap-sm); }\n.side-foot select { width: auto; flex: 1; padding: 6px 8px; }\n\n.main { padding: var(--gap); overflow: auto; }\n.section { display: none; }\n.section.active { display: block; }\n\n/* ── toast ──────────────────────────────────────────────── */\n.toast-host {\n  position: fixed; right: var(--gap); bottom: var(--gap); z-index: 100;\n  display: flex; flex-direction: column; gap: var(--gap-sm);\n}\n.toast {\n  padding: 10px 14px; border-radius: var(--radius-sm); font-size: 13px;\n  color: var(--primary-fg); background: var(--primary); box-shadow: 0 4px 12px var(--shadow);\n}\n.toast-warn { background: var(--warn); color: var(--warn-fg); }\n.toast-err { background: var(--danger); color: var(--danger-fg); }\n.toast-ok { background: var(--ok); color: var(--ok-fg); }\n\n/* ── modal ──────────────────────────────────────────────── */\n.modal-back {\n  position: fixed; inset: 0; z-index: 200;\n  display: flex; align-items: center; justify-content: center;\n  background: var(--shadow);\n}\n.modal {\n  width: 100%; max-width: 420px; padding: 20px; background: var(--panel);\n  border: 1px solid var(--border); border-radius: var(--radius);\n}\n.modal h2 { margin: 0 0 12px; font-size: 16px; }\n.modal-actions { display: flex; justify-content: flex-end; gap: var(--gap-sm); margin-top: 16px; }\n", type: "text/css; charset=utf-8", etag: "\"e9cca5ebf43b3bae\"" },
  "/admin/js/api.js": { body: "/**\n * 面板**登录之后**的唯一网络出口。\n *\n * ⚠️ **这句原来写的是「全站唯一网络出口」，那是假的**（全分支评审 C3）：\n * 全站一共**两个** `fetch` 调用点，另一个是 `js/app.js` 的登录探针\n *（`probe()`，`js/app.js:87`）。它**刻意**绕开本模块——那一刻还没有会话可言：\n * 没有 `expired()` 前置（时刻键还没写）、不该走 `onUnauthorized`（401 在那里\n * 的意思是「口令不对」，不是「你掉线了」）、也不必包成 `ApiError`。\n * 说准这件事很要紧：**本模块正是那个把「唯一出口」当成安全论证前提的地方**\n *（下面「口令只走请求头」那段），顺着假的那句走，审计者会漏掉口令实际离开\n * 页面的第二条路径。两个出口这件事由 `tests/ui/api-session.test.ts:286`\n * 那格数着调用点钉住——加第三个出口会让它变红。\n *\n * **两把钥匙严格隔离**（设计文档 §10.5）：\n * 本模块只发 `x-admin-key`、只打 `/admin/api/*`。网关口令与 `/v1` 是 P3d 的\n * Playground 的事，**不许在这里出现**。\n * 两条禁令各有一条行为用例钉着：`tests/ui/api-session.test.ts:227`（凭据头只有\n * `x-admin-key`，没有任何 `authorization` / 网关口令头）与 `:239`（出口 URL\n * 规范化之后落在哪里，含 `..` 那一档的如实登记）。\n * ⚠️ 这两条原来写的是「各有一条单测钉着」，而当时 `/v1` 那条只有一句附带的 URL\n * 断言、网关口令那条**一条都没有**（全分支评审 C3）。\n *\n * **401 = 会话失效；403 明确不当会话失效。**\n * 后者是照抄 kiro2api 用中文注释警告过的那个坑：它老写法把业务 403 当掉线，\n * 管理员拒绝一次授权就被踢出后台并被告知「密钥无效」。\n * 两条对称用例钉着这一对：`tests/ui/api-session.test.ts:187` 与 `:197`。\n * ⚠️ 这句原来也在宣称「两条对称用例进单测」，而当时是**零条**：把下面\n * `res.status === 401` 改成 `|| res.status === 403` 之后 1357 条全绿\n *（全分支评审 C3 实测）。\n */\nimport { sessionExpired } from \"./pure/session.mjs\";\n// 键名的单一真源，见该模块文件头（全分支评审 C4）。**别在这里再声明一遍**：\n// 写入方是 `app.js`，两处分叉会让面板登录成功之后每个请求都送空口令头。\nimport { KEY_STORE, SAVED_AT_STORE } from \"./pure/storage-keys.mjs\";\n\nconst BASE = \"/admin/api\";\n\nexport class ApiError extends Error {\n  constructor(status, message, body) {\n    super(message);\n    this.name = \"ApiError\";\n    this.status = status;\n    this.body = body;\n  }\n}\n\nlet unauthorizedHandler = null;\n/** 会话失效时的回调（清 key + 弹登录浮层）。只由 app.js 注册一次。 */\nexport function onUnauthorized(cb) { unauthorizedHandler = cb; }\n\nfunction readKey() {\n  try { return localStorage.getItem(KEY_STORE) || \"\"; } catch (e) { return \"\"; }\n}\n\n/**\n * 会话是不是已经到达绝对上限。判定在 `js/pure/session.mjs`，这里只喂参数。\n *\n * ⚠️ **为什么这一判必须在每个请求上做，而不是只在 `app.js` 启动那一次做。**\n * 面板是**常驻**的：事件在轮询、Key 池有自动刷新，运维把标签页开一整天是常态。\n * 只在模块加载那一次判的话，12 小时到点后这个标签页照样拿着那把口令继续打接口\n * ——而五语言 DEPLOY.md 逐字承诺「面板会在 12 小时后要求重新输入口令」，\n * 那就成了**一句被测试保护起来、却在最常见的路径上不成立的承诺**。\n * `js/pure/session.mjs` 开头那句「可用期从永远压到最多 12 小时」也要有这一判才成立。\n *\n * 放在**发请求之前**：过期就不发，与前端字符集拦截同一个道理——送出去也没用，\n * 而且会在服务端留下一条无意义的 `admin.login_failed`。\n */\nfunction expired() {\n  try {\n    return sessionExpired(Number(localStorage.getItem(SAVED_AT_STORE)), Date.now());\n  } catch (e) {\n    // 隐私模式下 localStorage 抛错：读不到时刻 ⇒ 与 sessionExpired 同一个方向，fail closed。\n    return true;\n  }\n}\n\nexport async function raw(method, path, body, init) {\n  // **会话绝对上限，每请求复查一次**（见 expired 的说明）。走的是与 401 完全相同的\n  // 那条通路：`unauthorizedHandler()` 清会话 + 回登录闸，再抛同一个 ApiError ——\n  // 调用方（各板块的轮询/刷新）已经会处理 401，不需要为过期再认一种新错误。\n  if (expired()) {\n    if (unauthorizedHandler) unauthorizedHandler();\n    throw new ApiError(401, \"session_expired\", null);\n  }\n  // 口令只走请求头。**禁止 Cookie 会话、禁止 ?key=**：口令进 URL 会落进浏览器历史、\n  // Referer、CF 访问日志、反代日志。这条禁令同时否掉了 EventSource（它设不了请求头）。\n  const headers = { \"x-admin-key\": readKey() };\n  if (body !== undefined) headers[\"content-type\"] = \"application/json\";\n  const res = await fetch(BASE + path, {\n    method,\n    headers: Object.assign(headers, (init && init.headers) || {}),\n    body: body === undefined ? undefined : JSON.stringify(body),\n    // 同源，且刻意不带凭据：本项目没有 Cookie 会话，带上只会扩大攻击面。\n    credentials: \"omit\",\n    signal: init && init.signal,\n  });\n  if (res.status === 401) {\n    // **只有 401 清会话。** 403 是「这个操作被拒绝」，不是「你没登录」。\n    if (unauthorizedHandler) unauthorizedHandler();\n    throw new ApiError(401, \"unauthorized\", null);\n  }\n  return res;\n}\n\nasync function json(method, path, body, init) {\n  const res = await raw(method, path, body, init);\n  let parsed = null;\n  try { parsed = await res.json(); } catch (e) { parsed = null; }\n  if (!res.ok) {\n    const msg = parsed && parsed.error && parsed.error.message ? parsed.error.message : `http_${res.status}`;\n    throw new ApiError(res.status, msg, parsed);\n  }\n  return parsed;\n}\n\nexport const api = {\n  get:  (p, init) => json(\"GET\", p, undefined, init),\n  post: (p, b, init) => json(\"POST\", p, b, init),\n  put:  (p, b, init) => json(\"PUT\", p, b, init),\n  del:  (p, init) => json(\"DELETE\", p, undefined, init),\n  raw,\n};\n", type: "text/javascript; charset=utf-8", etag: "\"9327de3061d864e7\"" },
  "/admin/js/app.js": { body: "/**\n * 面板入口：登录闸 + 板块注册表 + `showSection`。\n *\n * 板块契约（设计文档 §9.3）：`A.sections.<name> = { init?, onShow?, onHide? }`。\n * `showSection` 负责：切 .active、首次 init()、每次 onShow()、\n * 离开时上一个板块 onHide()（**停轮询、作废在飞请求**）、把板块名写 localStorage。\n * **没有 URL 路由、没有 hash**（放弃深链接，换与 kiro2api 一致的刷新复原行为）。\n *\n * ⚠️ **板块内不许各自监听 langchange**：框架层在这里统一 apply(document) +\n * 重跑当前板块的 onShow()。板块自己再监听一次就是 kiro2api 那 4 处冗余监听。\n */\nimport { t, apply, setLang, currentLang, LANGS } from \"./i18n.js\";\nimport { getTheme, toggleTheme, setTheme } from \"./theme.js\";\nimport { onUnauthorized } from \"./api.js\";\nimport { overviewSection } from \"./sec-overview.js\";\nimport { keysSection } from \"./sec-keys.js\";\nimport { eventsSection } from \"./sec-events.js\";\nimport { sessionExpired } from \"./pure/session.mjs\";\nimport { sendable } from \"./pure/sendable.mjs\";\n// **键名不在这里声明**（全分支评审 C4）：写入方在这个文件、读取方在 `api.js`，\n// 各写一份的后果实测过——只改这边一处 ⇒ 登录成功进壳层、随后每请求送空口令头\n// ⇒ 401 ⇒ 登出循环，面板彻底不可用而全套用例照绿。理由全文见那个模块的文件头。\nimport { KEY_STORE, SAVED_AT_STORE, SECTION_STORE } from \"./pure/storage-keys.mjs\";\n\nconst SECTIONS = { overview: overviewSection, keys: keysSection, events: eventsSection };\n\nconst gate = document.getElementById(\"gate\");\nconst shell = document.getElementById(\"shell\");\nconst form = document.getElementById(\"gate-form\");\nconst input = document.getElementById(\"gate-key\");\nconst err = document.getElementById(\"gate-err\");\n\nfunction store(op, value) {\n  try {\n    if (op === \"get\") return localStorage.getItem(KEY_STORE);\n    if (op === \"getAt\") return localStorage.getItem(SAVED_AT_STORE);\n    if (op === \"set\") {\n      localStorage.setItem(KEY_STORE, value);\n      localStorage.setItem(SAVED_AT_STORE, String(Date.now()));\n    }\n    if (op === \"del\") {\n      localStorage.removeItem(KEY_STORE);\n      localStorage.removeItem(SAVED_AT_STORE);\n    }\n  } catch (e) { /* 隐私模式：本次会话照常可用，刷新后要重新输入 */ }\n  return null;\n}\n\nlet current = null;\n\nfunction showSection(name) {\n  if (!SECTIONS[name]) name = \"overview\";\n  if (current === name) { SECTIONS[name].onShow && SECTIONS[name].onShow(); return; }\n  if (current && SECTIONS[current] && SECTIONS[current].onHide) SECTIONS[current].onHide();\n  for (const btn of document.querySelectorAll(\".nav-item\")) {\n    btn.classList.toggle(\"active\", btn.getAttribute(\"data-section\") === name);\n  }\n  for (const sec of document.querySelectorAll(\".section\")) {\n    sec.classList.toggle(\"active\", sec.id === `sec-${name}`);\n  }\n  const s = SECTIONS[name];\n  if (!s.__inited) { s.init && s.init(document.getElementById(`sec-${name}`)); s.__inited = true; }\n  s.onShow && s.onShow();\n  current = name;\n  try { localStorage.setItem(SECTION_STORE, name); } catch (e) { /* ignore */ }\n}\n\nfunction enter() {\n  gate.classList.add(\"off\");\n  shell.classList.add(\"on\");\n  let saved = \"overview\";\n  try { saved = localStorage.getItem(SECTION_STORE) || \"overview\"; } catch (e) { /* ignore */ }\n  showSection(saved);\n}\n\nfunction leave(reason) {\n  if (current && SECTIONS[current] && SECTIONS[current].onHide) SECTIONS[current].onHide();\n  current = null;\n  store(\"del\");\n  shell.classList.remove(\"on\");\n  gate.classList.remove(\"off\");\n  input.value = \"\";\n  err.textContent = reason ? t(reason) : \"\";\n}\n\n/**\n * 登录探针。**这是全站第二个、也是最后一个网络出口**（另一个是 `js/api.js` 的\n * `raw()`）——`api.js` 的文件头一度把「全站唯一网络出口」当成它那段安全论证的前提，\n * 那句是假的（全分支评审 C3），两边现在都说准了。\n *\n * **刻意不走 `api.js`**，三条理由缺一不可：\n * ① 这一刻还没有会话——时刻键要到 `store(\"set\")` 才写下，`api.js` 的 `expired()`\n *    前置会把每一次登录都判成过期（`Number(null) === 0` ⇒ `savedAt <= 0`）；\n * ② 这里的 401 意思是「口令不对」，不是「你掉线了」，走 `onUnauthorized()` 会\n *    在登录闸上再弹一次登录闸；\n * ③ 口令还没进 `localStorage`，`api.js` 的 `readKey()` 读不到它。\n * 出口数量由 `tests/ui/api-session.test.ts:286` 数着钉住，加第三个会变红。\n */\nasync function probe(key) {\n  const res = await fetch(\"/admin/api/session\", { headers: { \"x-admin-key\": key }, credentials: \"omit\" });\n  if (res.status === 401) return { ok: false, reason: \"gate.invalid\" };\n  // 403 **不当会话失效**：将来某个操作被拒绝时把人踢出后台并告知「密钥无效」，\n  // 是 kiro2api 踩过的坑。这里只有 401 才算登录失败。\n  if (!res.ok) return { ok: false, reason: \"gate.httpError\", status: res.status };\n  return { ok: true, body: await res.json() };\n}\n\nform.addEventListener(\"submit\", async (e) => {\n  e.preventDefault();\n  const key = input.value.trim();\n  err.textContent = \"\";\n  if (!key) { err.textContent = t(\"gate.empty\"); return; }\n  // 字符集判定在 `js/pure/sendable.mjs`，**与后端 `SENDABLE` 逐码位等价**\n  //（`tests/ui/sendable-parity.test.ts` 的行为断言钉着，不是源码文本比对）。\n  // 前端这一半必须有：后端只在启动时看得到自己的口令，看不到用户粘了什么。\n  // 判定本身不许在这个文件里再写一遍（admin-ui/README.md 硬规则 1）。\n  if (!sendable(key)) { err.textContent = t(\"gate.badShape\"); return; }\n  const submit = form.querySelector(\"button\");\n  submit.disabled = true;\n  try {\n    const r = await probe(key);\n    if (!r.ok) {\n      // 失败**绝不**写入 localStorage，也不显示「已登录」。\n      err.textContent = r.reason === \"gate.invalid\" ? t(\"gate.invalid\") : t(\"gate.httpError\", { status: r.status });\n      return;\n    }\n    store(\"set\", key);\n    enter();\n  } catch (e2) {\n    err.textContent = t(\"gate.network\");\n  } finally {\n    submit.disabled = false;\n  }\n});\n\n// 会话失效由 api.js 统一上报：任何一个 401 都把人送回登录闸，并说清原因。\nonUnauthorized(() => leave(\"common.sessionExpired\"));\n\ndocument.getElementById(\"logout-btn\").addEventListener(\"click\", () => leave(null));\ndocument.getElementById(\"theme-btn\").addEventListener(\"click\", () => toggleTheme());\n\nconst langSel = document.getElementById(\"lang-select\");\nfor (const l of LANGS) {\n  const o = document.createElement(\"option\");\n  o.value = l; o.textContent = l;\n  langSel.appendChild(o);\n}\nlangSel.value = currentLang();\nlangSel.addEventListener(\"change\", () => setLang(langSel.value));\n\n// **框架层的兜底：切语言时整页重绘。** 板块自己不许再监听这个事件。\ndocument.addEventListener(\"langchange\", () => {\n  apply(document);\n  if (current && SECTIONS[current] && SECTIONS[current].onShow) SECTIONS[current].onShow();\n});\n\nfor (const btn of document.querySelectorAll(\".nav-item\")) {\n  btn.addEventListener(\"click\", () => showSection(btn.getAttribute(\"data-section\")));\n}\n\napply(document);\nsetTheme(getTheme());\n\n// 已经存过口令就直接验一次；**验不过要清掉**，否则用户会卡在一个永远进不去的页面。\n// 只有 401 才清：接口 500 或断网时清掉等于让一次运维事故顺手把人锁在外面。\n//\n// 但在验之前先过一道**会话绝对上限**：存下来超过 12 小时（或者压根没存时刻——\n// 旧版本存的）就当场清掉、回登录闸，连这一次 probe 都不发。判定在\n// `js/pure/session.mjs`，这里只负责把浏览器存储与时钟喂给它。\nconst saved = store(\"get\");\nif (saved) {\n  if (sessionExpired(Number(store(\"getAt\")), Date.now())) {\n    store(\"del\");\n    err.textContent = t(\"common.sessionExpired\");\n  } else {\n    probe(saved).then((r) => {\n      if (r.ok) enter();\n      else if (r.reason === \"gate.invalid\") store(\"del\");\n    }).catch(() => {});\n  }\n}\n", type: "text/javascript; charset=utf-8", etag: "\"25afb581ee022c09\"" },
  "/admin/js/boot.js": { body: "/*\n * 全站唯一的经典脚本：<head> 里同步执行、**不许加 defer / type=\"module\"**。\n *\n * 模块脚本天然 defer，会在 body 绘制之后才跑，于是每次刷新都能看见一次亮色闪白\n *（或一次错误的语言）。这条约束写在这里，改动前先读它。\n *\n * 它也是全站唯一允许在 CSS 之前加载的脚本——主题属性必须在样式表生效前落到\n * <html> 上，否则 :root[data-theme=\"dark\"] 那一整组覆盖会晚一帧。\n */\n(function () {\n  try {\n    var theme = localStorage.getItem(\"agnes2api_theme\");\n    if (theme === \"dark\") document.documentElement.setAttribute(\"data-theme\", \"dark\");\n    // light 时**移除属性**而不是设成 \"light\"：CSS 里 :root 是亮色全量 token，\n    // [data-theme=\"dark\"] 整体覆盖，多一个 light 值只会多一条永远匹配不上的规则。\n    var lang = localStorage.getItem(\"agnes2api_lang\") || \"zh-CN\";\n    document.documentElement.setAttribute(\"data-lang\", lang);\n    document.documentElement.lang = lang;\n  } catch (e) {\n    // localStorage 被禁用（隐私模式 / 三方 cookie 拦截）时什么都不做，走默认外观。\n    // 这里**不能抛**：它是同步脚本，抛出去会让后面的样式表和模块脚本一起停摆。\n  }\n})();\n", type: "text/javascript; charset=utf-8", etag: "\"8a498ad988cce75a\"" },
  "/admin/js/i18n-dict.js": { body: "/**\n * 五语言字典。**唯一真源。**\n *\n * 组织成 key-major（一个键下挂五种语言）而不是 lang-major：\n * 「加了一个键但只填了一种语言」在 key-major 的 diff 里一眼就能看见，\n * 而 lang-major 下它散在五个相距几百行的地方。齐全性有 CI 门禁\n *（scripts/check-i18n.mjs 与 tests/unit/i18n-dict.test.ts 两份独立实现），\n * 这个组织方式只是让人工评审也拦得住。\n *\n * 为什么是 .js 而不是 .json：`scripts/build-ui.mjs` 逐字节复制、**零例外**，\n * 那条性质是本项目守住「不引入需要构建步骤的前端框架」的全部依据。\n * 给它开一个「JSON 包裹成 JS」的例外，代价是逐字节断言要加豁免，\n * 而且生成物不在磁盘上 ⇒ 用浏览器直接打开 index.html 时 `import \"./i18n-dict.js\"`\n * 模块解析失败、**整个面板打不开**（ESM 的失败是整条链断）。\n * 已实测：`.js` 同样能被 vitest 直接 import，`pnpm typecheck` 退出 0。\n *\n * ⚠️ `reg.*` 命名空间有**禁用词门禁**（两条邮箱通道必须完全平级）。\n * 想说「默认值」请把那条文案放进别的命名空间，别去给禁用词表开豁免。\n */\nexport const I18N = {\n  // ── 登录闸 ───────────────────────────────────────────────\n  \"gate.title\":       { \"zh-CN\": \"agnes2api 管理后台\", \"zh-TW\": \"agnes2api 管理後台\", en: \"agnes2api Admin\", ja: \"agnes2api 管理画面\", ko: \"agnes2api 관리 콘솔\" },\n  \"gate.sub\":         { \"zh-CN\": \"请输入管理口令（ADMIN_TOKEN）\", \"zh-TW\": \"請輸入管理口令（ADMIN_TOKEN）\", en: \"Enter the admin token (ADMIN_TOKEN)\", ja: \"管理トークン（ADMIN_TOKEN）を入力してください\", ko: \"관리 토큰(ADMIN_TOKEN)을 입력하세요\" },\n  \"gate.label\":       { \"zh-CN\": \"管理口令\", \"zh-TW\": \"管理口令\", en: \"Admin token\", ja: \"管理トークン\", ko: \"관리 토큰\" },\n  \"gate.placeholder\": { \"zh-CN\": \"ADMIN_TOKEN\", \"zh-TW\": \"ADMIN_TOKEN\", en: \"ADMIN_TOKEN\", ja: \"ADMIN_TOKEN\", ko: \"ADMIN_TOKEN\" },\n  \"gate.submit\":      { \"zh-CN\": \"进入\", \"zh-TW\": \"進入\", en: \"Enter\", ja: \"入る\", ko: \"들어가기\" },\n  \"gate.empty\":       { \"zh-CN\": \"请输入管理口令\", \"zh-TW\": \"請輸入管理口令\", en: \"Please enter the admin token\", ja: \"管理トークンを入力してください\", ko: \"관리 토큰을 입력하세요\" },\n  \"gate.invalid\":     { \"zh-CN\": \"口令无效\", \"zh-TW\": \"口令無效\", en: \"Invalid token\", ja: \"トークンが無効です\", ko: \"토큰이 올바르지 않습니다\" },\n  \"gate.badShape\":    { \"zh-CN\": \"这个口令里有不被接受的字符。只允许可打印 ASCII（0x20–0x7E）：汉字 / emoji / 零宽空格这类字符浏览器根本发不出去；é / £ 这类字符其实发得出去，但本网关出于跨运行时编码的稳健性考虑同样不接受。请检查环境变量里的 ADMIN_TOKEN。\", \"zh-TW\": \"這個口令裡有不被接受的字元。只允許可列印 ASCII（0x20–0x7E）：漢字 / emoji / 零寬空格這類字元瀏覽器根本送不出去；é / £ 這類字元其實送得出去，但本網關基於跨執行時編碼的穩健性考量同樣不接受。請檢查環境變數裡的 ADMIN_TOKEN。\", en: \"This token contains characters that are not accepted. Only printable ASCII (0x20–0x7E) is allowed: CJK characters, emoji and zero-width spaces simply cannot be sent by the browser, while characters like é or £ can be sent but are still rejected here as a cross-runtime encoding robustness choice. Check ADMIN_TOKEN in your environment.\", ja: \"このトークンには受け付けられない文字が含まれています。使用できるのは印字可能な ASCII（0x20–0x7E）のみです: 漢字・emoji・ゼロ幅スペースはブラウザーがそもそも送信できません。é や £ のような文字は送信自体は可能ですが、ランタイム間のエンコーディングに関する堅牢性の判断としてここでは受け付けていません。環境変数の ADMIN_TOKEN を確認してください。\", ko: \"이 토큰에는 허용되지 않는 문자가 있습니다. 출력 가능한 ASCII(0x20–0x7E)만 사용할 수 있습니다: 한자 / 이모지 / 폭 없는 공백은 브라우저가 아예 보낼 수 없고, é 나 £ 같은 문자는 보낼 수는 있지만 런타임 간 인코딩 견고성을 위한 선택으로 여기서는 받지 않습니다. 환경 변수의 ADMIN_TOKEN을 확인하세요.\" },\n  \"gate.network\":     { \"zh-CN\": \"网络错误，请稍后重试\", \"zh-TW\": \"網路錯誤，請稍後重試\", en: \"Network error, please retry\", ja: \"ネットワークエラーです。しばらくしてから再試行してください\", ko: \"네트워크 오류입니다. 잠시 후 다시 시도하세요\" },\n  \"gate.httpError\":   { \"zh-CN\": \"接口异常：{status}\", \"zh-TW\": \"介面異常：{status}\", en: \"Request failed: {status}\", ja: \"リクエスト失敗: {status}\", ko: \"요청 실패: {status}\" },\n\n  // ── 外壳 ─────────────────────────────────────────────────\n  \"nav.overview\":     { \"zh-CN\": \"概览\", \"zh-TW\": \"概覽\", en: \"Overview\", ja: \"概要\", ko: \"개요\" },\n  \"nav.keys\":         { \"zh-CN\": \"Key 池\", \"zh-TW\": \"Key 池\", en: \"Key pool\", ja: \"キープール\", ko: \"키 풀\" },\n  \"nav.events\":       { \"zh-CN\": \"事件\", \"zh-TW\": \"事件\", en: \"Events\", ja: \"イベント\", ko: \"이벤트\" },\n  \"shell.logout\":     { \"zh-CN\": \"退出登录\", \"zh-TW\": \"登出\", en: \"Sign out\", ja: \"ログアウト\", ko: \"로그아웃\" },\n  \"shell.theme\":      { \"zh-CN\": \"切换主题\", \"zh-TW\": \"切換主題\", en: \"Toggle theme\", ja: \"テーマ切り替え\", ko: \"테마 전환\" },\n  \"shell.lang\":       { \"zh-CN\": \"语言\", \"zh-TW\": \"語言\", en: \"Language\", ja: \"言語\", ko: \"언어\" },\n  \"common.dash\":      { \"zh-CN\": \"—\", \"zh-TW\": \"—\", en: \"—\", ja: \"—\", ko: \"—\" },\n  \"common.refresh\":   { \"zh-CN\": \"刷新\", \"zh-TW\": \"重新整理\", en: \"Refresh\", ja: \"更新\", ko: \"새로고침\" },\n  \"common.loadFailed\":{ \"zh-CN\": \"读取失败，显示为 —\", \"zh-TW\": \"讀取失敗，顯示為 —\", en: \"Failed to load; shown as —\", ja: \"取得に失敗しました（— と表示）\", ko: \"불러오기 실패(—로 표시)\" },\n  \"common.approx\":    { \"zh-CN\": \"近似值\", \"zh-TW\": \"近似值\", en: \"Approximate\", ja: \"概算値\", ko: \"근사값\" },\n  \"common.copy\":      { \"zh-CN\": \"复制\", \"zh-TW\": \"複製\", en: \"Copy\", ja: \"コピー\", ko: \"복사\" },\n  \"common.copied\":    { \"zh-CN\": \"已复制\", \"zh-TW\": \"已複製\", en: \"Copied\", ja: \"コピーしました\", ko: \"복사했습니다\" },\n  \"common.copyFailed\":{ \"zh-CN\": \"复制失败\", \"zh-TW\": \"複製失敗\", en: \"Copy failed\", ja: \"コピーに失敗しました\", ko: \"복사에 실패했습니다\" },\n  \"common.cancel\":    { \"zh-CN\": \"取消\", \"zh-TW\": \"取消\", en: \"Cancel\", ja: \"キャンセル\", ko: \"취소\" },\n  \"common.confirm\":   { \"zh-CN\": \"确定\", \"zh-TW\": \"確定\", en: \"Confirm\", ja: \"確認\", ko: \"확인\" },\n  \"common.sessionExpired\": { \"zh-CN\": \"会话已过期，请重新输入管理口令\", \"zh-TW\": \"工作階段已過期，請重新輸入管理口令\", en: \"Session expired, please sign in again\", ja: \"セッションが失効しました。再度サインインしてください\", ko: \"세션이 만료되었습니다. 다시 로그인하세요\" },\n\n  // ── 补池失败归因（P3c 的注册机板块才渲染；本期先把键写齐，好让门禁从第一天就是活的）──\n  \"reg.fail.domain_blocked_all\": { \"zh-CN\": \"所有域名都被上游拦下\", \"zh-TW\": \"所有網域都被上游擋下\", en: \"Every domain was blocked upstream\", ja: \"すべてのドメインが上流でブロックされました\", ko: \"모든 도메인이 업스트림에서 차단되었습니다\" },\n  \"reg.fail.upstream_error\":     { \"zh-CN\": \"上游返回错误\", \"zh-TW\": \"上游回傳錯誤\", en: \"Upstream returned an error\", ja: \"上流がエラーを返しました\", ko: \"업스트림이 오류를 반환했습니다\" },\n  \"reg.fail.code_timeout\":       { \"zh-CN\": \"等验证码超时\", \"zh-TW\": \"等驗證碼逾時\", en: \"Timed out waiting for the verification code\", ja: \"認証コードの待機がタイムアウトしました\", ko: \"인증 코드 대기 시간이 초과되었습니다\" },\n  \"reg.fail.register_failed\":    { \"zh-CN\": \"注册这一步失败\", \"zh-TW\": \"註冊這一步失敗\", en: \"Registration step failed\", ja: \"登録ステップが失敗しました\", ko: \"가입 단계가 실패했습니다\" },\n  \"reg.fail.login_failed\":       { \"zh-CN\": \"登录这一步失败\", \"zh-TW\": \"登入這一步失敗\", en: \"Login step failed\", ja: \"ログインステップが失敗しました\", ko: \"로그인 단계가 실패했습니다\" },\n  \"reg.fail.key_failed\":         { \"zh-CN\": \"取 key 这一步失败\", \"zh-TW\": \"取 key 這一步失敗\", en: \"Key issuance step failed\", ja: \"キー取得ステップが失敗しました\", ko: \"키 발급 단계가 실패했습니다\" },\n  \"reg.fail.provider_error\":     { \"zh-CN\": \"邮箱通道报错\", \"zh-TW\": \"郵箱通道報錯\", en: \"The mailbox channel returned an error\", ja: \"メールボックスチャネルがエラーを返しました\", ko: \"메일박스 채널이 오류를 반환했습니다\" },\n  \"reg.fail.network_error\":      { \"zh-CN\": \"网络错误\", \"zh-TW\": \"網路錯誤\", en: \"Network error\", ja: \"ネットワークエラー\", ko: \"네트워크 오류\" },\n  \"reg.fail.rate_limited\":       { \"zh-CN\": \"被上游限流\", \"zh-TW\": \"被上游限流\", en: \"Rate limited upstream\", ja: \"上流でレート制限されました\", ko: \"업스트림에서 속도 제한되었습니다\" },\n  \"reg.fail.provider_missing\":   { \"zh-CN\": \"这条通道没有配好凭据，未构造出提供方\", \"zh-TW\": \"這條通道沒有配好憑據，未建立提供方\", en: \"This channel has no credentials configured, so no provider was constructed\", ja: \"このチャネルは資格情報が未設定のため、プロバイダーが構築されませんでした\", ko: \"이 채널에 자격 증명이 없어 공급자가 생성되지 않았습니다\" },\n\n  // ── Key 池板块（只读部分，Task 4）─────────────────────────────────────────\n  \"keys.title\":       { \"zh-CN\": \"Key 池\", \"zh-TW\": \"Key 池\", en: \"Key pool\", ja: \"キープール\", ko: \"키 풀\" },\n  \"keys.search\":      { \"zh-CN\": \"搜索 id 或掩码\", \"zh-TW\": \"搜尋 id 或遮罩\", en: \"Search by id or masked key\", ja: \"id またはマスクで検索\", ko: \"id 또는 마스크로 검색\" },\n  \"keys.filter\":      { \"zh-CN\": \"按状态筛选\", \"zh-TW\": \"依狀態篩選\", en: \"Filter by state\", ja: \"状態で絞り込み\", ko: \"상태로 필터\" },\n  \"keys.auto\":        { \"zh-CN\": \"自动刷新\", \"zh-TW\": \"自動重新整理\", en: \"Auto refresh\", ja: \"自動更新\", ko: \"자동 새로고침\" },\n  \"keys.auto.off\":    { \"zh-CN\": \"关\", \"zh-TW\": \"關\", en: \"Off\", ja: \"オフ\", ko: \"끄기\" },\n  \"keys.auto.30\":     { \"zh-CN\": \"30 秒\", \"zh-TW\": \"30 秒\", en: \"30s\", ja: \"30 秒\", ko: \"30초\" },\n  \"keys.auto.60\":     { \"zh-CN\": \"60 秒\", \"zh-TW\": \"60 秒\", en: \"60s\", ja: \"60 秒\", ko: \"60초\" },\n  // 开销说明**如实写**，不抄一个吓人的估算数字：这个板块与转发共用同一份 isolate\n  // 快照，P3b 的形态下自动刷新确实不烧存储配额。\n  //\n  // ⚠️ **carry-forward（Task 4 → Task 5）**：`{ttl}` / `{touch}` / `{poolTtl}` 三个\n  // 占位符在 Task 4 交付时没有数据源（capabilities/overview 是 Task 5 才有的），\n  // 当时暂用「点名旋钮 + 括注默认值」。Task 5 拿到 `GET /admin/api/overview` 之后\n  // 已把它们换成真实生效值——由 `js/pure/overview.mjs` 的 `poolKnobs()` 统一取数\n  // （两个板块共用同一份，不许各写各的），点名旋钮的写法保留（运维要知道该改哪个\n  // 环境变量），括注的默认值换成当前生效值。\n  \"keys.autoNote\":    { \"zh-CN\": \"这个板块与网关转发共用同一份 isolate 内的池子快照，所以自动刷新不额外产生存储读写。你看到的数据最多晚一个 POOL_CACHE_TTL_MS（当前 {ttl}）。\", \"zh-TW\": \"這個板塊與網關轉發共用同一份 isolate 內的池子快照，所以自動重新整理不額外產生儲存讀寫。你看到的資料最多晚一個 POOL_CACHE_TTL_MS（目前 {ttl}）。\", en: \"This section shares the same in-isolate pool snapshot as request forwarding, so auto refresh costs no extra storage reads or writes. What you see can lag by up to one POOL_CACHE_TTL_MS (currently {ttl}).\", ja: \"このセクションはゲートウェイの転送と同じ isolate 内プールスナップショットを共有するため、自動更新でストレージの読み書きが増えることはありません。表示は最大で POOL_CACHE_TTL_MS ぶん（現在の値: {ttl}）遅れることがあります。\", ko: \"이 섹션은 게이트웨이 전달과 동일한 isolate 내 풀 스냅숏을 공유하므로 자동 새로고침이 스토리지 읽기/쓰기를 추가로 발생시키지 않습니다. 보이는 데이터는 최대 POOL_CACHE_TTL_MS(현재 값 {ttl})만큼 늦을 수 있습니다.\" },\n  // 新鲜度提示条：与概览页共用同一份文案（组织方式不同——概览页的 ov.freshness.pool\n  // 还多了 configTtl 那一半，键池板块本来就没有配置卡，只留池子那一半）。\n  \"keys.freshness\":   { \"zh-CN\": \"别的实例判定的冷却 / 剔除，这里最多晚 {poolTtl} + 约 60 秒（KV 边缘缓存）才看到；而且这个窗口里本实例的写会覆盖对方刚写下的调度状态。\", \"zh-TW\": \"別的實例判定的冷卻 / 剔除，這裡最多晚 {poolTtl} + 約 60 秒（KV 邊緣快取）才看得到；而且這個視窗裡本實例的寫入會覆蓋對方剛寫下的排程狀態。\", en: \"Cooldowns and evictions decided by another instance take up to {poolTtl} plus about 60 seconds (KV edge cache) to show up here. Within that window, writes from this instance also overwrite the scheduling state the other one just wrote.\", ja: \"他のインスタンスが判定したクールダウン／除外がここに反映されるまで、最大で {poolTtl} + 約 60 秒（KV のエッジキャッシュ）かかります。しかもその間、このインスタンスの書き込みは相手が書いたばかりのスケジューリング状態を上書きします。\", ko: \"다른 인스턴스가 판정한 쿨다운/제외가 여기에 보이기까지 최대 {poolTtl} + 약 60초(KV 엣지 캐시)가 걸립니다. 게다가 그 구간에서는 이 인스턴스의 쓰기가 상대가 방금 기록한 스케줄링 상태를 덮어씁니다.\" },\n  \"keys.approxTip\":   { \"zh-CN\": \"近似值：并发请求下会少计（KV 没有 CAS）；且计数最多晚一个 POOL_TOUCH_INTERVAL_MS（当前 {touch}）才落盘，isolate 在此之前被回收时这一段会丢。\", \"zh-TW\": \"近似值：並發請求下會少計（KV 沒有 CAS）；且計數最多晚一個 POOL_TOUCH_INTERVAL_MS（目前 {touch}）才寫入，isolate 在此之前被回收時這一段會遺失。\", en: \"Approximate: concurrent requests undercount it (KV has no CAS), and counters are persisted up to one POOL_TOUCH_INTERVAL_MS late (currently {touch}) — whatever has not been persisted is lost if the isolate is recycled first.\", ja: \"概算値: 同時リクエスト下では少なく数えられます（KV に CAS がないため）。またカウンターの永続化は最大で POOL_TOUCH_INTERVAL_MS ぶん（現在の値: {touch}）遅れ、その前に isolate が回収されるとその分は失われます。\", ko: \"근사값: 동시 요청에서는 적게 집계됩니다(KV에 CAS가 없음). 또한 카운터는 최대 POOL_TOUCH_INTERVAL_MS(현재 값 {touch})만큼 늦게 저장되며, 그 전에 isolate가 회수되면 그 구간은 사라집니다.\" },\n  // 「最后使用」与计数是**同一份** staleness（同一次落盘一起带下去），所以它同样打 ≈。\n  // 这条与 keys.approxTip 说的不是一句话：那条讲「少计 + 晚落盘」，这条讲「时刻本身粗」。\n  \"keys.approxLastUsedTip\": { \"zh-CN\": \"近似值：这一列的精度最粗到一个 POOL_TOUCH_INTERVAL_MS（当前 {touch}）——写消除会把「只更新了最后使用时间」的那次写整个丢掉。任何其他状态变更的落盘都会顺带把它刷新，所以真出故障时它反而是新的。\", \"zh-TW\": \"近似值：這一欄的精度最粗到一個 POOL_TOUCH_INTERVAL_MS（目前 {touch}）——寫入消除會把「只更新了最後使用時間」的那次寫入整個丟掉。任何其他狀態變更的寫入都會順帶刷新它，所以真出故障時它反而是新的。\", en: \"Approximate: this column is only as precise as one POOL_TOUCH_INTERVAL_MS (currently {touch}) — a write that only bumps the last-used time is dropped entirely. Any other state change persists it as a side effect, so it is actually fresh whenever something is going wrong.\", ja: \"概算値: この列の精度は最も粗い場合で POOL_TOUCH_INTERVAL_MS ぶん（現在の値: {touch}）です——「最終使用時刻だけが変わった」書き込みは丸ごと破棄されます。他の状態変更の永続化はこの値もついでに更新するため、障害が起きているときはむしろ新しい値になります。\", ko: \"근사값: 이 열의 정밀도는 최대 POOL_TOUCH_INTERVAL_MS(현재 값 {touch})까지 거칠어집니다 — 마지막 사용 시각만 바뀐 쓰기는 통째로 버려지기 때문입니다. 다른 상태 변경이 저장될 때 함께 갱신되므로, 실제로 문제가 생겼을 때는 오히려 최신입니다.\" },\n  \"keys.bucket.all\":     { \"zh-CN\": \"全部\", \"zh-TW\": \"全部\", en: \"All\", ja: \"すべて\", ko: \"전체\" },\n  \"keys.bucket.fresh\":   { \"zh-CN\": \"可用\", \"zh-TW\": \"可用\", en: \"Available\", ja: \"利用可能\", ko: \"사용 가능\" },\n  \"keys.bucket.cooling\": { \"zh-CN\": \"冷却中\", \"zh-TW\": \"冷卻中\", en: \"Cooling down\", ja: \"クールダウン中\", ko: \"쿨다운 중\" },\n  \"keys.bucket.evicted\": { \"zh-CN\": \"已剔除\", \"zh-TW\": \"已剔除\", en: \"Evicted\", ja: \"除外済み\", ko: \"제외됨\" },\n  \"keys.col.seq\":        { \"zh-CN\": \"#\", \"zh-TW\": \"#\", en: \"#\", ja: \"#\", ko: \"#\" },\n  \"keys.col.key\":        { \"zh-CN\": \"Key\", \"zh-TW\": \"Key\", en: \"Key\", ja: \"Key\", ko: \"Key\" },\n  \"keys.col.bucket\":     { \"zh-CN\": \"状态\", \"zh-TW\": \"狀態\", en: \"State\", ja: \"状態\", ko: \"상태\" },\n  \"keys.col.addedAt\":    { \"zh-CN\": \"加入时间\", \"zh-TW\": \"加入時間\", en: \"Added\", ja: \"追加日時\", ko: \"추가 시각\" },\n  \"keys.col.lastUsedAt\": { \"zh-CN\": \"最后使用\", \"zh-TW\": \"最後使用\", en: \"Last used\", ja: \"最終使用\", ko: \"마지막 사용\" },\n  \"keys.col.cooldown\":   { \"zh-CN\": \"冷却剩余\", \"zh-TW\": \"冷卻剩餘\", en: \"Cooldown left\", ja: \"クールダウン残り\", ko: \"쿨다운 잔여\" },\n  \"keys.col.strikes\":    { \"zh-CN\": \"连续失败\", \"zh-TW\": \"連續失敗\", en: \"Strikes\", ja: \"連続失敗\", ko: \"연속 실패\" },\n  \"keys.col.usage\":      { \"zh-CN\": \"请求数 · 成功率\", \"zh-TW\": \"請求數 · 成功率\", en: \"Requests · success rate\", ja: \"リクエスト数 · 成功率\", ko: \"요청 수 · 성공률\" },\n  \"keys.col.lastError\":  { \"zh-CN\": \"最近错误\", \"zh-TW\": \"最近錯誤\", en: \"Last error\", ja: \"直近のエラー\", ko: \"최근 오류\" },\n  \"keys.empty\":       { \"zh-CN\": \"池子里还没有 key\", \"zh-TW\": \"池子裡還沒有 key\", en: \"No keys in the pool yet\", ja: \"プールにまだ key がありません\", ko: \"풀에 아직 key가 없습니다\" },\n  \"keys.noMatch\":     { \"zh-CN\": \"没有符合条件的 key\", \"zh-TW\": \"沒有符合條件的 key\", en: \"No keys match the current filter\", ja: \"条件に一致する key がありません\", ko: \"조건에 맞는 key가 없습니다\" },\n  \"keys.pageInfo\":    { \"zh-CN\": \"第 {page}/{pages} 页 · 共 {total} 条\", \"zh-TW\": \"第 {page}/{pages} 頁 · 共 {total} 筆\", en: \"Page {page} of {pages} · {total} in total\", ja: \"{pages} ページ中 {page} ページ目 · 全 {total} 件\", ko: \"{pages} 페이지 중 {page} 페이지 · 총 {total}개\" },\n  \"keys.prev\":        { \"zh-CN\": \"上一页\", \"zh-TW\": \"上一頁\", en: \"Previous\", ja: \"前へ\", ko: \"이전\" },\n  \"keys.next\":        { \"zh-CN\": \"下一页\", \"zh-TW\": \"下一頁\", en: \"Next\", ja: \"次へ\", ko: \"다음\" },\n\n  // ── 概览板块（Task 5）──────────────────────────────────────────────────────\n  \"ov.title\":            { \"zh-CN\": \"概览\", \"zh-TW\": \"概覽\", en: \"Overview\", ja: \"概要\", ko: \"개요\" },\n  \"ov.pool.total\":       { \"zh-CN\": \"总数\", \"zh-TW\": \"總數\", en: \"Total\", ja: \"総数\", ko: \"총계\" },\n  \"ov.pool.fresh\":       { \"zh-CN\": \"可用\", \"zh-TW\": \"可用\", en: \"Available\", ja: \"利用可能\", ko: \"사용 가능\" },\n  \"ov.pool.cooling\":     { \"zh-CN\": \"冷却中\", \"zh-TW\": \"冷卻中\", en: \"Cooling down\", ja: \"クールダウン中\", ko: \"쿨다운 중\" },\n  \"ov.pool.evicted\":     { \"zh-CN\": \"已剔除\", \"zh-TW\": \"已剔除\", en: \"Evicted\", ja: \"除外済み\", ko: \"제외됨\" },\n\n  \"ov.runtime.title\":       { \"zh-CN\": \"运行时信息\", \"zh-TW\": \"執行時資訊\", en: \"Runtime info\", ja: \"ランタイム情報\", ko: \"런타임 정보\" },\n  \"ov.runtime.version\":     { \"zh-CN\": \"版本号\", \"zh-TW\": \"版本號\", en: \"Version\", ja: \"バージョン\", ko: \"버전\" },\n  \"ov.runtime.runtimeLabel\":{ \"zh-CN\": \"运行时\", \"zh-TW\": \"執行時\", en: \"Runtime\", ja: \"ランタイム\", ko: \"런타임\" },\n  \"ov.runtime.node\":        { \"zh-CN\": \"Node\", \"zh-TW\": \"Node\", en: \"Node\", ja: \"Node\", ko: \"Node\" },\n  \"ov.runtime.worker\":      { \"zh-CN\": \"Cloudflare Workers\", \"zh-TW\": \"Cloudflare Workers\", en: \"Cloudflare Workers\", ja: \"Cloudflare Workers\", ko: \"Cloudflare Workers\" },\n  \"ov.runtime.serverTime\":  { \"zh-CN\": \"服务器时间\", \"zh-TW\": \"伺服器時間\", en: \"Server time\", ja: \"サーバー時刻\", ko: \"서버 시각\" },\n  \"ov.runtime.storageBackend\": { \"zh-CN\": \"存储后端\", \"zh-TW\": \"儲存後端\", en: \"Storage backend\", ja: \"ストレージバックエンド\", ko: \"스토리지 백엔드\" },\n  \"ov.storage.file\":        { \"zh-CN\": \"文件（store.json）\", \"zh-TW\": \"檔案（store.json）\", en: \"File (store.json)\", ja: \"ファイル（store.json）\", ko: \"파일(store.json)\" },\n  \"ov.storage.kv\":          { \"zh-CN\": \"KV\", \"zh-TW\": \"KV\", en: \"KV\", ja: \"KV\", ko: \"KV\" },\n  \"ov.runtime.memory\":      { \"zh-CN\": \"内存\", \"zh-TW\": \"記憶體\", en: \"Memory\", ja: \"メモリ\", ko: \"메모리\" },\n  \"ov.runtime.uptime\":      { \"zh-CN\": \"进程存活\", \"zh-TW\": \"行程存活時間\", en: \"Process uptime\", ja: \"プロセス稼働時間\", ko: \"프로세스 가동 시간\" },\n  \"ov.runtime.pid\":         { \"zh-CN\": \"PID\", \"zh-TW\": \"PID\", en: \"PID\", ja: \"PID\", ko: \"PID\" },\n  // 产品不变式 11 逐字要求的那句话：不是 0、不是空、不隐藏格子。五语言都必须译出\n  // 同一个意思（Serverless、没有常驻进程），不许省略成一个模糊词。\n  \"ov.runtime.serverless\":  { \"zh-CN\": \"Serverless · 无常驻进程\", \"zh-TW\": \"Serverless · 無常駐行程\", en: \"Serverless · no long-lived process\", ja: \"サーバーレス · 常駐プロセスなし\", ko: \"서버리스 · 상주 프로세스 없음\" },\n  \"ov.runtime.writable\":    { \"zh-CN\": \"存储可写\", \"zh-TW\": \"儲存可寫\", en: \"Storage writable\", ja: \"ストレージ書き込み可否\", ko: \"스토리지 쓰기 가능 여부\" },\n  \"ov.runtime.writableYes\": { \"zh-CN\": \"可写\", \"zh-TW\": \"可寫\", en: \"Writable\", ja: \"書き込み可能\", ko: \"쓰기 가능\" },\n  \"ov.runtime.writableNo\":  { \"zh-CN\": \"不可写\", \"zh-TW\": \"不可寫\", en: \"Not writable\", ja: \"書き込み不可\", ko: \"쓰기 불가\" },\n  \"ov.runtime.checkedAt\":   { \"zh-CN\": \"最近一次探测：{at}\", \"zh-TW\": \"最近一次探測：{at}\", en: \"Last checked: {at}\", ja: \"直近の確認: {at}\", ko: \"최근 확인: {at}\" },\n\n  \"ov.freshness.title\": { \"zh-CN\": \"新鲜度\", \"zh-TW\": \"新鮮度\", en: \"Freshness\", ja: \"鮮度\", ko: \"신선도\" },\n  // 两条都要显示（progress.md:232 登记的那条），各自给出真实上界。数字全部由\n  // overview.freshness 的响应值插入，不是硬编码——`{upper}` 已经把 `{ttl}` 与\n  // KV 边缘缓存的量算过一遍，不是要求前端再算一次。\n  \"ov.freshness.pool\":  { \"zh-CN\": \"别的实例判定的冷却 / 剔除：最多晚 {upper}（{ttl} 快照 + 约 {edge} KV 边缘缓存）。这个窗口里本实例的写会覆盖对方刚写下的调度状态。\", \"zh-TW\": \"別的實例判定的冷卻 / 剔除：最多晚 {upper}（{ttl} 快照 + 約 {edge} KV 邊緣快取）。這個視窗裡本實例的寫入會覆蓋對方剛寫下的排程狀態。\", en: \"Cooldowns/evictions decided by another instance: up to {upper} late ({ttl} snapshot + about {edge} KV edge cache). Within that window, writes from this instance also overwrite the scheduling state the other one just wrote.\", ja: \"他のインスタンスが判定したクールダウン／除外：最大 {upper} 遅れます（{ttl} のスナップショット + 約 {edge} の KV エッジキャッシュ）。この間、このインスタンスの書き込みは相手が書いたばかりのスケジューリング状態を上書きします。\", ko: \"다른 인스턴스가 판정한 쿨다운/제외: 최대 {upper} 늦게 반영됩니다({ttl} 스냅숏 + 약 {edge} KV 엣지 캐시). 이 구간에서는 이 인스턴스의 쓰기가 상대가 방금 기록한 스케줄링 상태를 덮어씁니다.\" },\n  \"ov.freshness.config\":{ \"zh-CN\": \"配置保存之后生效：最多 {upper}（{ttl} 配置缓存 + 约 {edge} KV 边缘缓存）。不是「立即生效」。\", \"zh-TW\": \"設定儲存之後生效：最多 {upper}（{ttl} 設定快取 + 約 {edge} KV 邊緣快取）。不是「立即生效」。\", en: \"Config changes take effect after saving: up to {upper} ({ttl} config cache + about {edge} KV edge cache). Not \\\"immediately\\\".\", ja: \"設定は保存後に反映されます：最大 {upper}（{ttl} の設定キャッシュ + 約 {edge} の KV エッジキャッシュ）。「即時反映」ではありません。\", ko: \"설정은 저장 후 반영됩니다: 최대 {upper}({ttl} 설정 캐시 + 약 {edge} KV 엣지 캐시). \\\"즉시 반영\\\"이 아닙니다.\" },\n\n  // F9：设计文档 §10.1「今日用量」的订正。Tier-1 的 stats 是自这把 key 加入以来的\n  // 累计值，没有任何时间维度；把它标成「今日」是撒谎，标题直接写「累计（≈）」。\n  // **不再硬编码 (≈)**：`≈` 现在由 usageStats() 的 approx 字段驱动，逐格渲染\n  // （见 sec-overview.js 的 renderUsage/approxMark），标题只说「累计」这件事本身。\n  \"ov.usage.title\":       { \"zh-CN\": \"累计\", \"zh-TW\": \"累計\", en: \"Cumulative\", ja: \"累計\", ko: \"누적\" },\n  \"ov.usage.requests\":    { \"zh-CN\": \"请求数\", \"zh-TW\": \"請求數\", en: \"Requests\", ja: \"リクエスト数\", ko: \"요청 수\" },\n  \"ov.usage.success\":     { \"zh-CN\": \"成功\", \"zh-TW\": \"成功\", en: \"Success\", ja: \"成功\", ko: \"성공\" },\n  \"ov.usage.failed\":      { \"zh-CN\": \"失败\", \"zh-TW\": \"失敗\", en: \"Failed\", ja: \"失敗\", ko: \"실패\" },\n  \"ov.usage.clientErrors\":{ \"zh-CN\": \"客户端 4xx\", \"zh-TW\": \"用戶端 4xx\", en: \"Client 4xx\", ja: \"クライアント 4xx\", ko: \"클라이언트 4xx\" },\n  \"ov.usage.successRate\": { \"zh-CN\": \"成功率\", \"zh-TW\": \"成功率\", en: \"Success rate\", ja: \"成功率\", ko: \"성공률\" },\n  \"ov.usage.tip\":         { \"zh-CN\": \"这是自这批 key 加入以来的累计值，不是「今日」——按天/按小时的分解要等启用时间序列统计之后才有。\", \"zh-TW\": \"這是自這批 key 加入以來的累計值，不是「今日」——按天/按小時的分解要等啟用時間序列統計之後才有。\", en: \"This is the cumulative value since these keys were added, not \\\"today\\\" — a per-day/per-hour breakdown will only be available once time-series stats are enabled.\", ja: \"これはこの key が追加されて以降の累計値であり、「本日」ではありません——日次／時間次への分解は時系列統計が有効になってからのみ可能です。\", ko: \"이는 이 key가 추가된 이후의 누적값이며 \\\"오늘\\\"이 아닙니다 — 일별/시간별 분해는 시계열 통계가 활성화된 후에만 가능합니다.\" },\n  // `≈` 标记的 tooltip：与 keys.approxTip 同一条道理（并发下少计 + 写消除延迟落盘），\n  // 这里是整池聚合（sumStats），不是单把 key，措辞相应调整。\n  \"ov.usage.approxTip\":   { \"zh-CN\": \"近似值：这是整池所有 key 的累计聚合，单把 key 的计数在并发下会少计（KV 没有 CAS），且最多延迟一个触达间隔才落盘。\", \"zh-TW\": \"近似值：這是整池所有 key 的累計聚合，單把 key 的計數在並發下會少計（KV 沒有 CAS），且最多延遲一個觸達間隔才寫入。\", en: \"Approximate: this is the pool-wide aggregate over every key. Per-key counters undercount under concurrent requests (KV has no CAS) and can lag by up to one touch interval before being persisted.\", ja: \"概算値: これはプール内の全 key を集計した値です。key ごとのカウンターは同時リクエスト下で少なく数えられ（KV に CAS がないため）、永続化は最大でタッチ間隔ぶん遅れることがあります。\", ko: \"근사값: 이는 풀 전체 key의 누적 합계입니다. key별 카운터는 동시 요청에서 적게 집계되며(KV에 CAS 없음), 저장은 최대 하나의 접촉 간격만큼 늦어질 수 있습니다.\" },\n\n  \"ov.config.title\":      { \"zh-CN\": \"配置摘要\", \"zh-TW\": \"設定摘要\", en: \"Config summary\", ja: \"設定サマリー\", ko: \"설정 요약\" },\n  \"ov.config.registrar\":  { \"zh-CN\": \"注册机\", \"zh-TW\": \"註冊機\", en: \"Registrar\", ja: \"レジストラー\", ko: \"등록기\" },\n  \"ov.config.on\":         { \"zh-CN\": \"已启用\", \"zh-TW\": \"已啟用\", en: \"Enabled\", ja: \"有効\", ko: \"활성화됨\" },\n  \"ov.config.off\":        { \"zh-CN\": \"已关闭\", \"zh-TW\": \"已關閉\", en: \"Disabled\", ja: \"無効\", ko: \"비활성화됨\" },\n  \"ov.config.primary\":    { \"zh-CN\": \"主通道\", \"zh-TW\": \"主通道\", en: \"Primary channel\", ja: \"プライマリチャネル\", ko: \"기본 채널\" },\n  \"ov.config.fallback\":   { \"zh-CN\": \"备用通道\", \"zh-TW\": \"備用通道\", en: \"Fallback channel\", ja: \"フォールバックチャネル\", ko: \"대체 채널\" },\n  \"ov.config.none\":       { \"zh-CN\": \"无\", \"zh-TW\": \"無\", en: \"None\", ja: \"なし\", ko: \"없음\" },\n  \"ov.config.targetKeys\": { \"zh-CN\": \"目标 key 数\", \"zh-TW\": \"目標 key 數\", en: \"Target key count\", ja: \"目標 key 数\", ko: \"목표 key 수\" },\n  \"ov.config.envLocked\":  { \"zh-CN\": \"被环境变量锁定的字段数：{count}\", \"zh-TW\": \"被環境變數鎖定的欄位數：{count}\", en: \"Fields locked by environment variables: {count}\", ja: \"環境変数でロックされているフィールド数: {count}\", ko: \"환경 변수로 잠긴 필드 수: {count}\" },\n  \"ov.config.envLockedTip\": { \"zh-CN\": \"这些字段在面板上改了也不会生效，因为环境变量的优先级更高：{fields}\", \"zh-TW\": \"這些欄位在面板上改了也不會生效，因為環境變數的優先權更高：{fields}\", en: \"Changing these fields in the panel has no effect — the environment variable takes priority: {fields}\", ja: \"これらのフィールドはパネルで変更しても反映されません。環境変数が優先されるためです: {fields}\", ko: \"이 필드는 패널에서 변경해도 적용되지 않습니다. 환경 변수가 우선하기 때문입니다: {fields}\" },\n  // 红色横幅：设计 §5.4/config.ts 的 degraded 信号第一次有消费者。\n  \"ov.config.degradedBanner\": { \"zh-CN\": \"本次配置装载发生了降级：部分字段读取失败或已回落到默认值，你在面板上保存过的值可能没有生效。\", \"zh-TW\": \"本次設定載入發生了降級：部分欄位讀取失敗或已回落到預設值，你在面板上儲存過的值可能沒有生效。\", en: \"This config load was degraded: some fields failed to read or fell back to defaults — values you saved in the panel may not be in effect.\", ja: \"今回の設定読み込みは劣化しました：一部のフィールドが読み込みに失敗したか既定値にフォールバックしています。パネルで保存した値が反映されていない可能性があります。\", ko: \"이번 설정 로드는 저하된 상태입니다: 일부 필드를 읽지 못했거나 기본값으로 대체되었습니다. 패널에서 저장한 값이 적용되지 않았을 수 있습니다.\" },\n\n  \"ov.storageCard.title\":    { \"zh-CN\": \"存储\", \"zh-TW\": \"儲存\", en: \"Storage\", ja: \"ストレージ\", ko: \"스토리지\" },\n  \"ov.storageCard.backend\":  { \"zh-CN\": \"后端类型\", \"zh-TW\": \"後端類型\", en: \"Backend type\", ja: \"バックエンド種別\", ko: \"백엔드 유형\" },\n  \"ov.storageCard.writable\": { \"zh-CN\": \"可写性\", \"zh-TW\": \"可寫性\", en: \"Writability\", ja: \"書き込み可否\", ko: \"쓰기 가능 여부\" },\n  \"ov.storageCard.workerNote\": { \"zh-CN\": \"本部署预计每个 isolate 每天约 {estimate} 次 KV 读，只取决于刷新频率与池子规模，与请求数无关；实际总量还要乘以并发的 isolate 数目。详见 DEPLOY.md 的配额账小节。\", \"zh-TW\": \"本部署預計每個 isolate 每天約 {estimate} 次 KV 讀取，只取決於重新整理頻率與池子規模，與請求數無關；實際總量還要乘以並發的 isolate 數目。詳見 DEPLOY.md 的配額帳小節。\", en: \"This deployment is estimated at about {estimate} KV reads per isolate per day, driven only by refresh frequency and pool size — not by request volume. The real total also scales with the number of concurrently active isolates. See the quota section in DEPLOY.md.\", ja: \"このデプロイでは、1 isolate あたり 1 日約 {estimate} 回の KV 読み取りが見込まれます。これはリクエスト数ではなく更新頻度とプール規模だけで決まります。実際の合計は同時に動く isolate 数に比例して増えます。詳しくは DEPLOY.md の割り当てのセクションを参照してください。\", ko: \"이 배포는 isolate당 하루 약 {estimate}회의 KV 읽기가 예상되며, 요청 수가 아니라 새로고침 빈도와 풀 규모에만 좌우됩니다. 실제 총량은 동시에 활성화된 isolate 수만큼 곱해집니다. 자세한 내용은 DEPLOY.md의 할당량 섹션을 참고하세요.\" },\n  \"ov.storageCard.workerNoteUnknown\": { \"zh-CN\": \"本部署的 KV 读写与请求数无关，只取决于刷新频率与池子规模；相关数字暂时读不到，无法给出估算，详见 DEPLOY.md 的配额账小节。\", \"zh-TW\": \"本部署的 KV 讀寫與請求數無關，只取決於重新整理頻率與池子規模；相關數字暫時讀不到，無法給出估算，詳見 DEPLOY.md 的配額帳小節。\", en: \"This deployment's KV reads/writes are independent of request volume — driven only by refresh frequency and pool size. The numbers needed for an estimate are unavailable right now. See the quota section in DEPLOY.md.\", ja: \"このデプロイの KV 読み書きはリクエスト数とは無関係で、更新頻度とプール規模だけで決まります。見積もりに必要な数値が現在取得できません。詳しくは DEPLOY.md の割り当てのセクションを参照してください。\", ko: \"이 배포의 KV 읽기/쓰기는 요청 수와 무관하며 새로고침 빈도와 풀 규모에만 좌우됩니다. 추정에 필요한 수치를 현재 가져올 수 없습니다. 자세한 내용은 DEPLOY.md의 할당량 섹션을 참고하세요.\" },\n  \"ov.storageCard.nodeNote\":  { \"zh-CN\": \"文件存储没有配额限制，但每次写都会重写整个 store.json。\", \"zh-TW\": \"檔案儲存沒有配額限制，但每次寫入都會重寫整個 store.json。\", en: \"File storage has no quota limit, but every write rewrites the entire store.json.\", ja: \"ファイルストレージには割り当て制限はありませんが、書き込みのたびに store.json 全体を書き直します。\", ko: \"파일 스토리지는 할당량 제한이 없지만, 쓸 때마다 store.json 전체를 다시 씁니다.\" },\n\n  // ── 事件板块（Task 6）────────────────────────────────────────────────────\n  \"ev.title\":  { \"zh-CN\": \"事件\", \"zh-TW\": \"事件\", en: \"Events\", ja: \"イベント\", ko: \"이벤트\" },\n  // 顶部常驻说明（两种运行时同一句，见 Task 5 Step 4 的 logs.processLog: false 那条先例）：\n  // Serverless 没有常驻进程，逐请求日志流在这里物理上不可能是完整的。\n  // **评审 I2**：本期只有 config/pool 索引/管理接口/事件落库自身四类运维诊断事件\n  // 会出现在本面板（见 src/core/keypool-repo.ts / config.ts / admin/auth.ts /\n  // adapters/logger-store.ts 的 logger.log() 调用点）。\n  // **评审 I2b（round 3）修正**：round 2 的文案曾错误地说\"注册机（补池）事件还没有\n  // 产出\"——这不属实。`src/core/registrar/{mint,config,tender}.ts` 与\n  // `adapters/mailbox-*.ts` 里有二十多处 `registrar.*` logger.log() 调用点，\n  // 这些事件是真实产出的，只是走的是裸 `ConsoleLogger`（src/http/wire.ts 的\n  // buildTendDeps()，Worker 的 scheduled() 与 fetch() 是两个不同的 isolate\n  // 生命周期，没有请求/响应边界可挂 logFlush，接上去需要 ctx.waitUntil 一类的\n  // 独立落盘机制，留给 P3c 与注册机板块一起做），从未接进 `StoreLogger`，因此\n  // 从不落库、也就从不出现在本面板——\"产出了但没接线\"与\"压根没产出\"是两件不同\n  // 的事，前一版文案把它们混成了一件。key 的冷却/剔除**确实**目前压根不为这两类\n  // 状态变化打事件，这半句评审确认属实，未改动。\n  \"ev.notice\": { \"zh-CN\": \"这里只有低频结构化事件（如配置读取失败、池索引重建、管理接口登录失败等运维诊断事件）。注册机（补池）事件已经产出，但还没有接入本面板（未落库，见 P3c）；key 的冷却/剔除目前还没有产出对应的事件。逐请求日志请看容器 stdout / Cloudflare 控制台的 Workers Logs——Serverless 形态没有常驻进程，逐请求日志流在这里物理上不可能是完整的。\", \"zh-TW\": \"這裡只有低頻結構化事件（如設定讀取失敗、池索引重建、管理接口登入失敗等維運診斷事件）。註冊機（補池）事件已經產出，但還沒有接入本面板（未寫入，見 P3c）；key 的冷卻/剔除目前還沒有產出對應的事件。逐請求日誌請看容器 stdout / Cloudflare 主控台的 Workers Logs——Serverless 形態沒有常駐行程，逐請求日誌流在這裡物理上不可能是完整的。\", en: \"This shows only low-frequency operational diagnostic events (e.g. config read failures, pool index rebuilds, failed admin logins). Registrar (pool-refill) events are already produced, but aren't wired into this board yet (not persisted here — see P3c); key cooldown/eviction don't produce events yet. For per-request logs, check container stdout or Cloudflare's Workers Logs — the serverless shape has no long-lived process, so a complete per-request log stream is physically impossible here.\", ja: \"ここには低頻度の運用診断イベント（例：設定読み込み失敗、プール索引の再構築、管理者ログイン失敗など）のみが表示されます。レジストラー（プール補充）イベントはすでに出力されていますが、まだ本パネルには接続されていません（ここには保存されません。P3c で対応予定）。key のクールダウン/除外はまだイベントを出力していません。リクエストごとのログはコンテナの stdout または Cloudflare コンソールの Workers Logs をご覧ください——サーバーレス形態には常駐プロセスがなく、ここでリクエストごとの完全なログストリームを見ることは物理的に不可能です。\", ko: \"여기에는 저빈도 운영 진단 이벤트(예: 설정 읽기 실패, 풀 인덱스 재구축, 관리자 로그인 실패 등)만 표시됩니다. 레지스트라(풀 보충) 이벤트는 이미 생성되고 있지만 아직 이 패널에 연결되지 않았습니다(여기에 저장되지 않음, P3c에서 처리 예정). key의 쿨다운/제외는 아직 이벤트를 생성하지 않습니다. 요청별 로그는 컨테이너 stdout 또는 Cloudflare 콘솔의 Workers Logs를 확인하세요——서버리스 형태에는 상주 프로세스가 없어 여기서 완전한 요청별 로그 스트림을 보는 것은 물리적으로 불가능합니다.\" },\n  \"ev.search\": { \"zh-CN\": \"搜索事件名 / 说明 / 字段…\", \"zh-TW\": \"搜尋事件名 / 說明 / 欄位…\", en: \"Search event / message / fields…\", ja: \"イベント名／説明／フィールドを検索…\", ko: \"이벤트명/설명/필드 검색…\" },\n\n  \"ev.level.all\":   { \"zh-CN\": \"全部级别\", \"zh-TW\": \"全部級別\", en: \"All levels\", ja: \"すべてのレベル\", ko: \"모든 레벨\" },\n  \"ev.level.debug\": { \"zh-CN\": \"调试\", \"zh-TW\": \"偵錯\", en: \"Debug\", ja: \"デバッグ\", ko: \"디버그\" },\n  \"ev.level.info\":  { \"zh-CN\": \"信息\", \"zh-TW\": \"資訊\", en: \"Info\", ja: \"情報\", ko: \"정보\" },\n  \"ev.level.warn\":  { \"zh-CN\": \"警告\", \"zh-TW\": \"警告\", en: \"Warn\", ja: \"警告\", ko: \"경고\" },\n  \"ev.level.error\": { \"zh-CN\": \"错误\", \"zh-TW\": \"錯誤\", en: \"Error\", ja: \"エラー\", ko: \"오류\" },\n  // 评审 I4：一条事件的 level 字段缺失/畸形时，显式归到这一档，不冒充任何已知级别。\n  \"ev.level.unknown\": { \"zh-CN\": \"未知\", \"zh-TW\": \"未知\", en: \"Unknown\", ja: \"不明\", ko: \"알 수 없음\" },\n\n  \"ev.pause\":   { \"zh-CN\": \"暂停\", \"zh-TW\": \"暫停\", en: \"Pause\", ja: \"一時停止\", ko: \"일시 정지\" },\n  \"ev.resume\":  { \"zh-CN\": \"继续\", \"zh-TW\": \"繼續\", en: \"Resume\", ja: \"再開\", ko: \"재개\" },\n  \"ev.clear\":   { \"zh-CN\": \"清空\", \"zh-TW\": \"清空\", en: \"Clear\", ja: \"クリア\", ko: \"지우기\" },\n  \"ev.clearTip\":{ \"zh-CN\": \"只清前端当前显示的列表，不影响服务端已落盘的事件。被清掉的不会自动回来——要重看请点「下载」或刷新页面\", \"zh-TW\": \"只清前端目前顯示的清單，不影響服務端已寫入的事件。被清掉的不會自動回來——要重看請點「下載」或重新整理頁面\", en: \"Clears only the list shown here; events already persisted server-side are unaffected. Cleared entries do not come back on their own — use Download, or reload the page\", ja: \"ここに表示中のリストのみクリアします。サーバー側に保存済みのイベントには影響しません。クリアした分は自動では戻りません——「ダウンロード」を使うか、ページを再読み込みしてください\", ko: \"여기에 표시된 목록만 지웁니다. 서버에 이미 저장된 이벤트에는 영향을 주지 않습니다. 지운 항목은 저절로 돌아오지 않습니다 — 「다운로드」를 쓰거나 페이지를 새로고침하세요\" },\n  \"ev.download\":{ \"zh-CN\": \"下载\", \"zh-TW\": \"下載\", en: \"Download\", ja: \"ダウンロード\", ko: \"다운로드\" },\n  \"ev.downloadFailed\": { \"zh-CN\": \"下载失败\", \"zh-TW\": \"下載失敗\", en: \"Download failed\", ja: \"ダウンロードに失敗しました\", ko: \"다운로드 실패\" },\n  \"ev.autoScroll\": { \"zh-CN\": \"自动滚动\", \"zh-TW\": \"自動捲動\", en: \"Auto-scroll\", ja: \"自動スクロール\", ko: \"자동 스크롤\" },\n\n  \"ev.pollStatus.active\": { \"zh-CN\": \"轮询中\", \"zh-TW\": \"輪詢中\", en: \"Polling\", ja: \"ポーリング中\", ko: \"폴링 중\" },\n  \"ev.pollStatus.paused\": { \"zh-CN\": \"已暂停\", \"zh-TW\": \"已暫停\", en: \"Paused\", ja: \"一時停止中\", ko: \"일시 정지됨\" },\n  \"ev.pollStatus.error\":  { \"zh-CN\": \"轮询出错，稍后重试\", \"zh-TW\": \"輪詢出錯，稍後重試\", en: \"Polling error, will retry\", ja: \"ポーリングエラー、後で再試行します\", ko: \"폴링 오류, 나중에 재시도합니다\" },\n  // 评审 M2：轮询指示灯的提示语接上\"本 isolate\"到底是哪一个（shardId），\n  // 拼在状态文案后面，不是独立一句——避免多语言各自维护一套\"状态+分片\"的组合句。\n  \"ev.pollStatus.shardSuffix\": { \"zh-CN\": \"（本 isolate：{shardId}）\", \"zh-TW\": \"（本 isolate：{shardId}）\", en: \" (this isolate: {shardId})\", ja: \"（この isolate：{shardId}）\", ko: \"(이 isolate: {shardId})\" },\n  // 评审 N1：`buffered` 单独不占用黄条（见 pure/events.mjs 的 shouldWarn 说明），\n  // 但 isolate 随时可能被回收、缓冲里的事件会随之永久丢失——这里补一句 tooltip\n  // 常驻提示，愿意看的人看得到，不打扰不关心的人。\n  \"ev.pollStatus.bufferedSuffix\": { \"zh-CN\": \"（本 isolate 还有 {count} 条事件未落盘，isolate 被回收会丢失）\", \"zh-TW\": \"（本 isolate 還有 {count} 條事件未寫入，isolate 被回收會遺失）\", en: \" ({count} events in this isolate not yet persisted — lost if the isolate is recycled)\", ja: \"（この isolate にはまだ {count} 件のイベントが未保存です。isolate が回収されると失われます）\", ko: \"(이 isolate에 아직 저장되지 않은 이벤트 {count}건이 있습니다. isolate가 회수되면 손실됩니다)\" },\n  // 评审 N1 [LOW]：`generatedAt` 是响应生成时刻，tooltip 报一句\"数据截至几点\"，\n  // 运维不用另外去猜面板有没有卡住（同 pure/keys.mjs 用它当参照时刻的理由）。\n  \"ev.pollStatus.generatedAtSuffix\": { \"zh-CN\": \"（数据截至 {time}）\", \"zh-TW\": \"（資料截至 {time}）\", en: \" (data as of {time})\", ja: \"（データ基準時刻：{time}）\", ko: \"(데이터 기준 시각: {time})\" },\n\n  // dropped/budgetExhausted/truncated/cursorAhead 四条黄条文案：**各自独立**，\n  // 由响应对应字段各自驱动，不是同一句话的两种措辞（见 pure/events.mjs 的\n  // shouldWarn 说明）。\n  \"ev.warnDropped\": { \"zh-CN\": \"本 isolate 的事件缓冲已丢弃 {count} 条最旧的事件（环形缓冲上限 100 条，落盘前被新事件顶掉）。\", \"zh-TW\": \"本 isolate 的事件緩衝已丟棄 {count} 條最舊的事件（環形緩衝上限 100 條，寫入前被新事件頂掉）。\", en: \"This isolate's event buffer has dropped {count} of the oldest events (ring buffer caps at 100 entries; new events pushed them out before they were persisted).\", ja: \"この isolate のイベントバッファは最も古い {count} 件のイベントを破棄しました（リングバッファの上限は 100 件で、書き込み前に新しいイベントに押し出されました）。\", ko: \"이 isolate의 이벤트 버퍼가 가장 오래된 이벤트 {count}건을 삭제했습니다(링 버퍼 상한 100건, 저장 전에 새 이벤트에 밀려남).\" },\n  \"ev.warnBudget\":  { \"zh-CN\": \"本 isolate 今天的事件写入预算已用完，未落盘的事件仍在容器日志 / Cloudflare 控制台的 Workers Logs 里。\", \"zh-TW\": \"本 isolate 今天的事件寫入預算已用完，未寫入的事件仍在容器日誌 / Cloudflare 主控台的 Workers Logs 裡。\", en: \"This isolate's event-write budget for today is used up. Events that were not persisted are still available in container logs / Cloudflare's Workers Logs.\", ja: \"この isolate の本日のイベント書き込み予算を使い切りました。書き込まれなかったイベントはコンテナログ／Cloudflare コンソールの Workers Logs に残っています。\", ko: \"이 isolate의 오늘 이벤트 쓰기 예산을 모두 사용했습니다. 저장되지 않은 이벤트는 컨테이너 로그/Cloudflare 콘솔의 Workers Logs에 남아 있습니다.\" },\n  // 评审 I3：after+limit 组合截掉了一部分本该出现的旧事件，必须如实说，不能悄悄吞掉。\n  \"ev.warnTruncated\": { \"zh-CN\": \"这一页没有显示全部符合条件的事件（超出了每次拉取的上限），更早的一部分被截掉了。\", \"zh-TW\": \"這一頁沒有顯示全部符合條件的事件（超出了每次拉取的上限），更早的一部分被截掉了。\", en: \"This page doesn't show every matching event (the per-fetch limit was exceeded); some older ones were cut off.\", ja: \"このページには条件に一致するすべてのイベントが表示されていません（取得件数の上限を超えました）。より古い一部が省略されています。\", ko: \"이 페이지에는 조건에 맞는 모든 이벤트가 표시되지 않습니다(가져오기 상한 초과). 더 오래된 일부가 잘렸습니다.\" },\n  // 评审 C6：游标领先于本次请求的时钟（时钟回拨 / isolate 间时钟偏移），空结果\n  // 不代表没有新事件。前端已经自动把冻结的游标丢掉重新冷读（见 sec-events.js 的\n  // poll()），这条只是如实告诉运维\"刚刚发生过一次自动恢复\"，不需要手动操作。\n  \"ev.warnCursorAhead\": { \"zh-CN\": \"检测到游标领先于服务端时钟（可能是时钟回拨或 isolate 间时钟偏移），已自动重新拉取最新数据。\", \"zh-TW\": \"偵測到游標領先於服務端時鐘（可能是時鐘回撥或 isolate 間時鐘偏移），已自動重新擷取最新資料。\", en: \"Detected a cursor ahead of the server clock (possibly a clock rollback or skew between isolates); automatically re-fetched from a fresh cursor.\", ja: \"カーソルがサーバー時刻より先行していることを検出しました（時刻の巻き戻し、または isolate 間の時刻ずれの可能性）。自動的に新しいカーソルから再取得しました。\", ko: \"커서가 서버 시계보다 앞서 있는 것을 감지했습니다(시계 롤백 또는 isolate 간 시계 편차 가능성). 새 커서로 자동으로 다시 가져왔습니다.\" },\n\n  \"ev.empty\":   { \"zh-CN\": \"还没有事件。\", \"zh-TW\": \"還沒有事件。\", en: \"No events yet.\", ja: \"まだイベントはありません。\", ko: \"아직 이벤트가 없습니다.\" },\n  // 全分支评审 I5：点过「清空」之后**不许**再显示 ev.empty ——那是在对运维说\n  // \"这个部署从来没出过事\"，而服务端明明有事件。这一句同时说清恢复路径。\n  \"ev.cleared\": { \"zh-CN\": \"已清空本页显示。服务端已落盘的事件不受影响——点「下载」可取到全部，或刷新页面重新拉取。\", \"zh-TW\": \"已清空本頁顯示。服務端已寫入的事件不受影響——點「下載」可取得全部，或重新整理頁面重新拉取。\", en: \"Cleared the list shown here. Events already persisted server-side are unaffected — use Download to get them all, or reload the page to fetch them again.\", ja: \"このページの表示をクリアしました。サーバー側に保存済みのイベントには影響しません——「ダウンロード」で全件取得できます。ページを再読み込みすれば再取得されます。\", ko: \"이 페이지의 표시를 지웠습니다. 서버에 이미 저장된 이벤트에는 영향이 없습니다 — 「다운로드」로 전부 받을 수 있고, 페이지를 새로고침하면 다시 불러옵니다.\" },\n  \"ev.noMatch\": { \"zh-CN\": \"没有符合筛选条件的事件。\", \"zh-TW\": \"沒有符合篩選條件的事件。\", en: \"No events match the current filters.\", ja: \"現在のフィルター条件に一致するイベントはありません。\", ko: \"현재 필터 조건에 맞는 이벤트가 없습니다.\" },\n\n  \"ev.col.time\":   { \"zh-CN\": \"时间\", \"zh-TW\": \"時間\", en: \"Time\", ja: \"時刻\", ko: \"시각\" },\n  \"ev.col.level\":  { \"zh-CN\": \"级别\", \"zh-TW\": \"級別\", en: \"Level\", ja: \"レベル\", ko: \"레벨\" },\n  \"ev.col.event\":  { \"zh-CN\": \"事件\", \"zh-TW\": \"事件\", en: \"Event\", ja: \"イベント\", ko: \"이벤트\" },\n  \"ev.col.detail\": { \"zh-CN\": \"说明 / 字段\", \"zh-TW\": \"說明 / 欄位\", en: \"Message / fields\", ja: \"説明／フィールド\", ko: \"설명/필드\" },\n\n  // 分组时间线的组头文案（P-1：按 corr 相邻折叠）。\n  \"ev.timeline\": { \"zh-CN\": \"时间线 · {count} 条 · {corr}\", \"zh-TW\": \"時間線 · {count} 條 · {corr}\", en: \"Timeline · {count} events · {corr}\", ja: \"タイムライン · {count} 件 · {corr}\", ko: \"타임라인 · {count}건 · {corr}\" },\n};\n", type: "text/javascript; charset=utf-8", etag: "\"84ac7d387bec0f90\"" },
  "/admin/js/i18n.js": { body: "/**\n * i18n。三个标记钩子 + 一个兜底机制。\n *\n * `t()` 找不到 key 时**返回 key 本身**（生产不该因为缺一句翻译就白屏），\n * 但 `DEBUG_STORE` 这个存储键为真时在控制台告警——开发期看得见，生产期不打扰。\n *\n * **兜底机制（照抄 kiro2api，理由相同）**：切语言时框架层做两件事——\n * `apply(document)` **加上**重新调用当前板块的 `onShow()` 整页重绘。\n * 有些标签是渲染时用 `t()` 拼进 textContent 的、没有 data-i18n 属性，`apply()` 抓不到。\n * 框架层强制重跑保证**不管板块自己写得对不对，切语言都一定生效**。\n * ⇒ **板块内不许再各自监听 langchange**（kiro2api 有 4 处冗余监听，是历史遗留）。\n */\nimport { I18N } from \"./i18n-dict.js\";\n// 键名的单一真源，见该模块文件头（全分支评审 C4）。\nimport { LANG_STORE as STORE, DEBUG_STORE } from \"./pure/storage-keys.mjs\";\n\nexport const LANGS = [\"zh-CN\", \"zh-TW\", \"en\", \"ja\", \"ko\"];\nconst FALLBACK = \"zh-CN\";\n\nfunction readLang() {\n  try {\n    const v = localStorage.getItem(STORE);\n    if (v && LANGS.includes(v)) return v;\n  } catch (e) { /* 隐私模式：走默认 */ }\n  return FALLBACK;\n}\n\nlet lang = readLang();\n\nexport function currentLang() { return lang; }\n\nexport function t(key, params) {\n  const row = I18N[key];\n  let s = row ? (row[lang] ?? row[FALLBACK]) : undefined;\n  if (s === undefined) {\n    try {\n      if (localStorage.getItem(DEBUG_STORE)) console.warn(\"[i18n] 缺 key:\", key);\n    } catch (e) { /* ignore */ }\n    return key;\n  }\n  if (params) for (const [k, v] of Object.entries(params)) s = s.split(`{${k}}`).join(String(v));\n  return s;\n}\n\n/** 三个标记钩子。全部走 textContent / setAttribute，**永不 innerHTML**。 */\nexport function apply(root) {\n  const scope = root || document;\n  for (const el of scope.querySelectorAll(\"[data-i18n]\")) el.textContent = t(el.getAttribute(\"data-i18n\"));\n  for (const el of scope.querySelectorAll(\"[data-i18n-ph]\")) el.setAttribute(\"placeholder\", t(el.getAttribute(\"data-i18n-ph\")));\n  for (const el of scope.querySelectorAll(\"[data-i18n-title]\")) {\n    const s = t(el.getAttribute(\"data-i18n-title\"));\n    el.setAttribute(\"title\", s);\n    // 无 aria-label 时一并写：图标按钮只有 title 的话读屏器读不出来。\n    if (!el.hasAttribute(\"aria-label\")) el.setAttribute(\"aria-label\", s);\n  }\n}\n\nexport function setLang(next) {\n  if (!LANGS.includes(next)) return;\n  lang = next;\n  try { localStorage.setItem(STORE, next); } catch (e) { /* ignore */ }\n  document.documentElement.setAttribute(\"data-lang\", next);\n  document.documentElement.lang = next;\n  apply(document);\n  document.dispatchEvent(new CustomEvent(\"langchange\", { detail: { lang: next } }));\n}\n", type: "text/javascript; charset=utf-8", etag: "\"f6fbcf3e9319f901\"" },
  "/admin/js/pure/bucket.mjs": { body: "/**\n * key 的分档。**顺序即优先级。**\n *\n * 只有三档。设计文档 §10.2 写的是四档（多一个「人工停用」），但那一档要求\n * `KeyRecord.disabled` 与 `isAvailable` / `poolHealth` 一起改，而后两者是热路径\n *（poolHealth 正被 503 的三条 reason 用着），设计文档 §12 已把它排在写操作那一期。\n * **加档必须与调度改动捆绑**：分档与调度分叉的后果是「面板说停用了，网关照样在用」。\n * 这条由 tests/ui/bucket.test.ts 的等价关系用例钉着——只改这里会让它变红。\n *\n * 这个目录下的文件受三条硬规则约束，规则全文见 admin-ui/README.md。\n */\nexport const BUCKETS = [\"evicted\", \"cooling\", \"fresh\"];\n\nexport function keyBucket(rec, now) {\n  if (!rec || typeof rec !== \"object\") return \"evicted\";\n  // 剔除优先于冷却：两者同时成立时（一把先冷却后被判 401 的 key）报「已剔除」，\n  // 因为「到期自动恢复」对它是假的——那正是 503 三条 reason 要区分的东西。\n  if (rec.evicted === true) return \"evicted\";\n  if (typeof rec.cooldownUntil === \"number\" && rec.cooldownUntil > now) return \"cooling\";\n  return \"fresh\";\n}\n", type: "text/javascript; charset=utf-8", etag: "\"3431d4c27d3085c3\"" },
  "/admin/js/pure/events.mjs": { body: "/**\n * 事件板块的**全部取值决策**。板块文件（`js/sec-events.js`）只剩 DOM 拼装、\n * 网络调用与 i18n 查表。理由与 `pure/keys.mjs` / `pure/overview.mjs` 同一条\n * （admin-ui/README.md 硬规则 1）。\n *\n * 这个目录下的文件受三条硬规则约束（禁 import、禁浏览器全局、纯文本校验），\n * 规则全文见 admin-ui/README.md。\n */\n\n/** 轮询最短间隔（页面可见、内容有变化时）。 */\nexport const EVENTS_POLL_MIN_MS = 15_000;\n/** 轮询最长间隔（内容连续无变化时指数退避到这里封顶）。 */\nexport const EVENTS_POLL_MAX_MS = 60_000;\n\n/** 四个日志级别，顺序即级别按钮组的渲染顺序。不含 \"all\"（那是\"不筛\"，另处理）。 */\nexport const LEVELS = [\"debug\", \"info\", \"warn\", \"error\"];\n\n/**\n * 级别按钮组用的 i18n key——**只用于工具栏的筛选按钮**，入参恒是 `LEVELS` 里的\n * 一个（调用方 `for (const lvl of LEVELS)` 保证）。\"全部级别\" 按钮的文案由调用方\n * 直接写字面量 `\"ev.level.all\"`，不经过这个函数。\n */\nexport function levelLabelKey(level) {\n  if (level === \"debug\") return \"ev.level.debug\";\n  if (level === \"info\") return \"ev.level.info\";\n  if (level === \"warn\") return \"ev.level.warn\";\n  return \"ev.level.error\";\n}\n\n/**\n * **评审 I4**：一条事件真实的 `level` 字段来自接口响应，可能缺失/畸形——\n * 原来 `eventRow` 里 `typeof item.level === \"string\" ? item.level : \"info\"` 会把\n * 这类数据**伪装成 info**（绿色徽章），与\"绝不伪造\"的产品不变式矛盾。这里给出\n * 唯一的判据：四个已知级别原样透传，其余（含 `undefined`/数字/畸形字符串）一律\n * 归到显式的 `\"unknown\"` 档，不冒充任何一个已知级别。\n */\nexport function effectiveLevel(item) {\n  const level = item && typeof item === \"object\" ? item.level : undefined;\n  return (LEVELS.includes(level)) ? level : \"unknown\";\n}\n\n/** `effectiveLevel()` 的结果 → i18n key，与 `levelLabelKey` 分开：这个要接受 \"unknown\"。 */\nexport function eventLevelLabelKey(level) {\n  if (level === \"debug\") return \"ev.level.debug\";\n  if (level === \"info\") return \"ev.level.info\";\n  if (level === \"warn\") return \"ev.level.warn\";\n  if (level === \"error\") return \"ev.level.error\";\n  return \"ev.level.unknown\";\n}\n\n/**\n * 级别徽章颜色。与 `pure/keys.mjs` 的 `badgeClass` 同一套配色语义。\n * **`\"unknown\"` 单独一档**（灰色/muted），不落进任何一个\"看起来正常\"的颜色。\n */\nexport function levelBadgeClass(level) {\n  if (level === \"error\") return \"badge badge-danger\";\n  if (level === \"warn\") return \"badge badge-warn\";\n  if (level === \"debug\" || level === \"info\") return \"badge badge-ok\";\n  return \"badge\"; // unknown：不给任何一种\"正常/异常\"的颜色暗示\n}\n\n/**\n * `GET /admin/api/events` 的查询串。\n *\n * `level` 为 `\"all\"`（或任何不认识的值）时**不发这个参数**——与 `keysQuery` 的\n * `bucket` 处理同一条理由：后端把无法识别的值当作不筛，发过去只是噪音。\n */\nexport function eventsQuery(state) {\n  const parts = [];\n  if (typeof state.after === \"number\" && Number.isFinite(state.after)) parts.push(`after=${state.after}`);\n  if (LEVELS.includes(state.level)) parts.push(`level=${encodeURIComponent(state.level)}`);\n  if (typeof state.limit === \"number\" && Number.isFinite(state.limit)) parts.push(`limit=${state.limit}`);\n  return parts.join(\"&\");\n}\n\n/** 「这份响应里有没有可渲染的条目」——同 `pure/keys.mjs` 的 `itemsOf`，全模块唯一判据。 */\nexport function itemsOf(body) {\n  return body && typeof body === \"object\" && Array.isArray(body.items) ? body.items : null;\n}\n\n/**\n * 事件列表区该显示哪条消息（`null` = 显示表格）。与 `pure/keys.mjs` 的\n * `listMessageKey` 同一个模式（判据一律不写在 `sec-events.js` 里，见硬规则 1）。\n *\n * **评审 M5**：原来 `sec-events.js` 用一个模块级的 `everLoaded` 标记（\"这次进入\n * 本板块之后有没有成功过一次\"），`onShow()` 每次都把它重置成 `false`——于是重新\n * 进入本板块时，只要第一轮轮询恰好失败，就会把 `view` 里明明还留着的历史事件\n * 整段换成\"读取失败\"，即使数据一直都在，只是这一轮没刷新成功。\n *\n * 判据改成只看 `viewLength`（视图里有没有数据）而不是\"这一次有没有成功过\"：\n * 只要视图里还有数据，哪怕最新一轮轮询失败了，也继续显示已有数据（轮询指示灯\n * 会转成\"出错\"提示这件事，不需要靠替换整个列表区来提示）；只有视图本身是空的\n * 且这一轮又失败了，才说\"读取失败\"。\n *\n * ⚠️ **`cleared` 这一档是全分支评审 I5，修的是一个已经上线的、面板对运维说假话的\n * 缺陷。** 点\"清空\"之后 `view` 变成 `[]`，而原来这里只看 `viewLength === 0`，\n * 于是列表区显示**「还没有事件。」**——与同一个按钮的 tooltip（\"只清前端当前显示的\n * 列表，不影响服务端已落盘的事件\"）当场自相矛盾，而且它说的那件事是假的：服务端\n * 明明有事件。运维照着这句话会得出\"这个部署从来没出过事\"的结论。\n *\n * **\"清空\"的语义刻意保持不变**（游标不回退，被清掉的不会自动回来）：这个按钮的\n * 用途就是\"把噪音清掉、从此刻起盯着新的\"。把游标一起重置的话，下一轮冷读会立刻\n * 把同一批事件原样拉回来——按钮看上去等于没生效。所以这里修的是**措辞**，\n * 并由 `ev.cleared` 把恢复路径（下载 / 刷新页面）一并说清楚。\n */\nexport function eventsListMessageKey(loadError, viewLength, filteredLength, cleared) {\n  if (loadError && viewLength === 0) return \"common.loadFailed\";\n  if (filteredLength === 0) {\n    if (viewLength > 0) return \"ev.noMatch\";\n    return cleared === true ? \"ev.cleared\" : \"ev.empty\";\n  }\n  return null;\n}\n\n/**\n * 本 isolate 的分片 id（评审 M2）。**没有数据时是 null**，不是空串——\n * 空串会被当成\"有值但恰好是空\"，与\"读不出来\"混在一起。\n */\nexport function shardIdOf(body) {\n  const v = body && typeof body === \"object\" ? body.shardId : null;\n  return typeof v === \"string\" && v !== \"\" ? v : null;\n}\n\n/**\n * 响应生成时刻（后端 `now()`，评审 N1 点名的第二个零消费者字段，[LOW]）。\n *\n * 与 `pure/keys.mjs` 的 `generatedAt` 同一条理由（那边用它当 `cooldownRemaining`\n * 的参照时刻，不用浏览器时钟）：这里没有需要拿它算差值的场景，**最小、低风险的\n * 消费方式**是让轮询指示灯的 tooltip 报一句\"数据截至几点\"——运维只要看这个\n * tooltip 就知道当前显示的是不是刚刚拉到的，不需要另外去猜面板有没有卡住。\n * 缺失/畸形时是 `null`（渲染成不显示这一段，不是显示一个假时间）。\n */\nexport function generatedAtOf(body) {\n  const v = body && typeof body === \"object\" ? body.generatedAt : null;\n  return typeof v === \"number\" && Number.isFinite(v) ? v : null;\n}\n\n/**\n * 响应自述状态。**没有数据时逐项 null**（不是 0/false）——那几个字面上恰好\n * 也是\"一切正常\"的值，混进\"读不出来\"里会把面板变成在撒谎。\n *\n * - `truncated`（评审 I3）：`after`+`limit` 组合截掉了一部分本该出现的旧事件。\n * - `buffered`（评审 N1）：本 isolate 缓冲里还有多少条事件没有落盘。isolate 在\n *   下一次成功 flush 之前被回收（Worker 上是常态）时，这些事件会**永久丢失**，\n *   而 `dropped` 不计它（`dropped` 只统计已经落盘/已经在内存环里明确丢弃的那些，\n *   还\"活在\"缓冲区里、尚未有机会落盘或丢弃的不算）。字段消费者审计发现这是\n *   唯一一个响应里给了但没有任何地方读的字段，这里补上。\n * - `cursorAhead`（评审 C6）：`after` 领先于本次请求的时钟（时钟回拨 / isolate\n *   间时钟偏移），`items` 恒为空但这**不代表没有新事件**，前端必须能区分开。\n */\nexport function bufferStatus(body) {\n  const dropped = body && typeof body === \"object\" ? body.dropped : null;\n  const budgetExhausted = body && typeof body === \"object\" ? body.budgetExhausted : null;\n  const truncated = body && typeof body === \"object\" ? body.truncated : null;\n  const buffered = body && typeof body === \"object\" ? body.buffered : null;\n  const cursorAhead = body && typeof body === \"object\" ? body.cursorAhead : null;\n  return {\n    dropped: typeof dropped === \"number\" && Number.isFinite(dropped) ? dropped : null,\n    budgetExhausted: typeof budgetExhausted === \"boolean\" ? budgetExhausted : null,\n    truncated: typeof truncated === \"boolean\" ? truncated : null,\n    buffered: typeof buffered === \"number\" && Number.isFinite(buffered) ? buffered : null,\n    cursorAhead: typeof cursorAhead === \"boolean\" ? cursorAhead : null,\n  };\n}\n\n/**\n * 顶部黄条要不要出现。**诚实标记必须由后端字段驱动**（Task 4 评审 I4 的裁定，\n * 在 Task 5 隔了一个任务原样复发过一次）：判据只看 `status.dropped` /\n * `status.budgetExhausted` / `status.truncated` / `status.cursorAhead` 这几个\n * 从响应里取出来的值，不许在这里或调用方硬编码一个 true/false。\n * `null`（没有数据）不触发——不知道不等于\"有问题\"。**不含 `buffered`**：单纯\n * \"缓冲区里还有事件没落盘\"是运行中的正常状态（还没到落盘时机而已），只有搭配\n * \"isolate 可能被回收\"这层风险才值得说，这条风险不是靠一个数字大小能判断的，\n * 交给轮询指示灯的 tooltip 常驻显示（见 `sec-events.js`），不占用黄条。\n */\nexport function shouldWarn(status) {\n  return (status.dropped !== null && status.dropped > 0)\n    || status.budgetExhausted === true\n    || status.truncated === true\n    || status.cursorAhead === true;\n}\n\n/**\n * 下一次轮询该带的 `after` 游标。\n *\n * `cursor` 为 `null`（本页没有新事件）时**保留当前值**，不能回退成 null 或某个\n * 旧值——那会让下一次轮询把已经看过的事件重新拉一遍。`cursor` 是数字时才推进。\n */\nexport function nextAfter(current, cursor) {\n  return typeof cursor === \"number\" && Number.isFinite(cursor) ? cursor : current;\n}\n\n/**\n * 轮询的**全部跨轮状态**。三个字段合成一个对象是有意为之，见 `pollOutcome()`\n * 的\"为什么是一个状态对象\"一段。\n *\n * - `after`：下一次请求要带的游标（`null` = 冷读）。\n * - `healing`：正处在一次游标自愈之后、**还没有重新建立起游标**的那一段。\n * - `delayMs`：下一次轮询的退避间隔。\n */\nexport function initialPollState() {\n  return { after: null, healing: false, delayMs: EVENTS_POLL_MIN_MS };\n}\n\n/**\n * 重新进入本板块时的状态。**保留 `after`**（已经看过的事件不该因为切走又切回来\n * 再拉一遍），但把退避与自愈状态归零——这两者描述的是\"最近这一段轮询发生了什么\"，\n * 隔了一段时间之后不再成立。\n *\n * 这条也是决策，不是拼装：写在板块文件里就又是一处没人测的跨轮规则。\n */\nexport function resumePollState(prev) {\n  const state = prev && typeof prev === \"object\" ? prev : {};\n  const after = typeof state.after === \"number\" && Number.isFinite(state.after) ? state.after : null;\n  return { after, healing: false, delayMs: EVENTS_POLL_MIN_MS };\n}\n\n/**\n * 一轮轮询成功之后的**完整状态转换**（评审 C6 二审 / 三审(a) / 四审 B1）。这条\n * 判断原来直接摊在 `sec-events.js` 的 `poll()` 里，是纯状态转换却没有测试覆盖，\n * 两个联带 bug 都是从这个洞里漏出来的——**这不是渲染逻辑，是决策逻辑**，与\n * `admin-ui/README.md` 硬规则 1 管的是同一类东西。\n *\n * **为什么入参/返回值是一个状态对象，而不是把跨轮标记单独传进传出**：三审(a) 的\n * 第一版把 `justHealed` 做成\"第五个入参 + 板块文件在每轮末尾自己用 `resetView`\n * 更新\"，于是\"上一轮的自愈不算这一轮的新内容\"这条**跨轮规则**有一半落在板块文件\n * 里——而板块文件没有任何自动化覆盖。四审实测：把板块文件里那一行改成恒 `false`\n * （并重跑 `scripts/build-ui.mjs`，免得被逐字节漂移门禁冒充抓到），全套 1241 条\n * 用例**一条都不红**，包括当时专门为这条修复新写的那条端到端用例——因为那条用例\n * 用自己的局部变量把这半条规则**又抄了一遍**，测的是抄件不是原件。现在整条规则\n * （置位、清位、保持）都在这个函数里，板块文件只剩一次整体赋值，不再持有判据。\n *\n * 返回：\n * - **`resetView`**：`cursorAhead` 为 `true` 时视图必须跟着游标一起清空，不能只清\n *   游标——`mergeIntoView` 是纯 `[...inc, ...cur]`，不去重；不清视图的话，自愈之后\n *   下一轮冷读回来的是\"最新\"的一批，会跟视图里已经卡在\"未来\"、语义已经不可信的\n *   那一批拼在一起，造成整页重复（无条件，单次自愈就会触发）。\n * - **`hadNewItems`**：退避间隔要不要回到最短，**只能看服务端这次真的返回了几条**\n *   （`items.length > 0`），不能借用\"游标变没变\"当替身——原来的实现正是用\n *   `state.after !== beforeAfter` 当替身，自愈本身也会让游标变化（从非 null 变成\n *   null），于是\"游标被清空\"被误判成\"来了新事件\"，退避永远回不到最长间隔（评审\n *   实测：稳态吞吐从按 C4b 算好的那条包线涨到约两倍）。\n * - **`next`**：下一轮的完整状态，见 `initialPollState()` 的字段说明。\n *   - `after`：`nextAfter()` 叠加\"游标自愈\"——`cursorAhead` 为 `true` 时无条件重置\n *     为 `null`，不管 `cursor`/旧值算出来是什么。冻结在未来的游标不能继续带下去，\n *     下一轮必须变成冷读才能真正恢复。\n *   - `healing`：自愈时置位，**真正重新建立起游标**（`after` 从 `null` 变回一个\n *     数字）时清位，其余保持。见下面一段。\n *   - `delayMs`：`nextPollDelayMs(上一轮的间隔, hadNewItems)`。\n *\n * ⚠️ **`healing` 为什么是\"自愈之后直到重新建立起游标为止\"，不是\"刚好上一轮\"**\n * （评审四审 B2）：三审(a) 那一版写的是\"只遮紧接着的一轮\"，而**冷读状态会持续\n * 很多轮**——落后的那个 isolate 结构上看不见领先 isolate 写进未来窗口的事件，\n * 恒返回 `cursor: null`，`nextAfter()` 就把 `after` 一直留在 `null`。于是此后\n * **每一次**落到领先的 isolate，都会把同一批旧事件当成\"新内容\"，退避塌回 15 秒。\n * 四审逐轮实测（负载均衡每 4 轮才命中一次领先 isolate）：\n *\n *     0 B ahead=0 items=1 jhIn=0 new=1 gets=48 delay=15s   <- 旧事件被当成新内容\n *     1 A ahead=1 items=0 jhIn=0 new=0 gets= 0 delay=30s   <- 自愈\n *     2 A ahead=0 items=0 jhIn=1 new=0 gets=48 delay=60s   <- 旧规则只遮到这一轮\n *     3 A ahead=0 items=0 jhIn=0 new=0 gets=48 delay=60s\n *     4 B ahead=0 items=1 jhIn=0 new=1 gets=48 delay=15s   <- 又塌回去\n *\n * 稳态吞吐随之**只与\"平均多少轮才命中一次领先 isolate\"（记作 k）有关**，与\"修没修\n * 三审(a)\"几乎无关：旧规则下 k=3 / 4 / 6 / 8 实测 78,994 / 75,404 / 72,758 /\n * 71,680 次每天（k=2 的严格交替是唯一的例外，34,560，旧规则恰好也够用），\n * **k≥3 全部超出 C4b 规划、五语言 DEPLOY.md 白纸黑字承诺的包线**。改成\n * \"直到重新建立起游标为止\"之后，退避在整个 k 轮周期里再也不会被塌回最短，稳态\n * 吞吐变成 `69,120 × (k−1) ÷ k + 1,440`：k=2 → 36,000、k=3 → 47,520、\n * k=4 → 53,280、k=6 → 59,040、k=8 → 61,920，**k 再大也只是从下方逼近 70,560，\n * 不会越过**（k→∞ 就是\"没有时钟偏移\"那条基准线本身，恰好等于 70,560）。\n *\n * ⚠️ 上面这一组数与那一行 `+1,440`（全分支评审 C2）：**每一轮轮询自己还会顺带\n * 触发一次配置读**（配置刷新中间件挂在所有路由之前，配置缓存 TTL 30 秒 < 稳态\n * 轮询间隔 60 秒 ⇒ 每轮恰好一次）。上一版的夹具用固定 holder，把这一项整个漏掉，\n * 于是那时写下的 34,560 / 46,080 / 51,840 / 57,600 / 60,480 与包线 69,120\n * **全部偏低 1,440**。\n * 这几个数字由 `tests/contract/events-cursor-heal.test.ts:224` 的\"逐 k 实测稳态\n * 吞吐\"用例逐个钉住（连同 70,560 基准线本身，`:269`），不是只写在这里。\n *\n * **代价，明写，并且是可证的上界**：`healing` 为真的那一段里 `after` 恒是 `null`\n * （自愈把它清成 null，只有拿到非 `null` 的 `cursor` 才会变回数字），而后端契约是\n * `cursor` 非 `null` **当且仅当** `items` 非空（见 `events.ts` 的\n * `cursor: items.length > 0 ? items[0].ts : null`）。所以\"清位\"这件事发生在\n * **自愈之后第一份非空响应**那一轮上——夹在中间被遮住的那些轮次本来就是空的\n * （`hadNewItems` 不遮也是 `false`）。换句话说：**一次自愈只会让恰好一批 `items`\n * 不把退避顶回 15 秒**，与遮了多少轮无关；这批要么本来就是自愈时刚扔掉的那一批\n * （正是要遮的东西），要么是一批真的新事件——那种情况下代价是它晚一个退避周期\n * （≤60 秒）才被\"盯着看\"的人更快刷新到，事件本身该显示的照常显示，不影响正确性。\n * 这条上界由 `tests/ui/events.test.ts` 的\"保持：自愈之后连续多轮冷读……\"那条用例\n * 直接演示（5 轮空冷读全遮住 → 第一批非空也遮住并清位 → 再下一批正常回到 15 秒）。\n */\nexport function pollOutcome(prev, items, cursor, cursorAhead) {\n  const state = prev && typeof prev === \"object\" ? prev : {};\n  const healed = cursorAhead === true;\n  const currentAfter = typeof state.after === \"number\" && Number.isFinite(state.after) ? state.after : null;\n  const wasHealing = state.healing === true;\n  const nextAfterValue = healed ? null : nextAfter(currentAfter, cursor);\n  const hadNewItems = wasHealing ? false : (Array.isArray(items) && items.length > 0);\n  return {\n    resetView: healed,\n    hadNewItems,\n    next: {\n      after: nextAfterValue,\n      healing: healed ? true : (nextAfterValue !== null ? false : wasHealing),\n      delayMs: nextPollDelayMs(\n        typeof state.delayMs === \"number\" && Number.isFinite(state.delayMs) ? state.delayMs : EVENTS_POLL_MIN_MS,\n        hadNewItems,\n      ),\n    },\n  };\n}\n\n/**\n * 指数退避的下一个轮询间隔。**有新内容 ⇒ 立刻回到最短间隔**（运维正在盯着，\n * 让它尽快看见后续变化）；**没有新内容 ⇒ 翻倍，封顶到 `EVENTS_POLL_MAX_MS`**。\n */\nexport function nextPollDelayMs(currentDelayMs, hadNewItems) {\n  if (hadNewItems) return EVENTS_POLL_MIN_MS;\n  const doubled = currentDelayMs * 2;\n  return doubled > EVENTS_POLL_MAX_MS ? EVENTS_POLL_MAX_MS : doubled;\n}\n\n/** 轮询状态指示灯该显示哪个状态。三态：暂停 / 出错 / 正常，暂停优先于出错。 */\nexport function pollIndicatorState(state) {\n  if (state.paused) return \"paused\";\n  if (state.lastError) return \"error\";\n  return \"active\";\n}\n\n/** 轮询状态 → i18n key。三条各写一次字面量，好让 i18n 门禁扫得到（同 levelLabelKey）。 */\nexport function pollIndicatorLabelKey(kind) {\n  if (kind === \"paused\") return \"ev.pollStatus.paused\";\n  if (kind === \"error\") return \"ev.pollStatus.error\";\n  return \"ev.pollStatus.active\";\n}\n\n/**\n * 搜索框的过滤判据。匹配 `event` / `msg` / `corr` / 字段值（不区分大小写的子串匹配）。\n * `q` 为空串时一律匹配（不筛）。\n */\nexport function matchesSearch(item, q) {\n  const needle = typeof q === \"string\" ? q.trim().toLowerCase() : \"\";\n  if (needle === \"\") return true;\n  if (!item || typeof item !== \"object\") return false;\n  const haystack = [\n    typeof item.event === \"string\" ? item.event : \"\",\n    typeof item.msg === \"string\" ? item.msg : \"\",\n    typeof item.corr === \"string\" ? item.corr : \"\",\n    item.fields && typeof item.fields === \"object\" ? JSON.stringify(item.fields) : \"\",\n  ].join(\" \").toLowerCase();\n  return haystack.includes(needle);\n}\n\n/**\n * `fields` 对象格式化成一行文本，供渲染时整体塞进一个 `textContent`。\n * **值一律不可信**（可能是攻击者能控制的内容），但这里只做展示格式化，\n * 不做转义/截断——由调用方统一走 `textContent`，不解析成 HTML。\n */\nexport function formatFields(fields) {\n  if (!fields || typeof fields !== \"object\") return \"\";\n  return Object.entries(fields).map(([k, v]) => `${k}=${v === null ? \"null\" : String(v)}`).join(\" \");\n}\n\n/**\n * 一条事件\"说明 / 字段\"列要显示的文本（评审 I4：原来这是 `sec-events.js` 里的\n * 纯取值函数，零测试覆盖，搬进来）。`msg` 与格式化后的 `fields` 用 `·` 连接，\n * 缺一段就不留多余的分隔符。\n */\nexport function buildDetailText(item) {\n  const msg = item && typeof item === \"object\" && typeof item.msg === \"string\" ? item.msg : \"\";\n  const fields = item && typeof item === \"object\" && item.fields && typeof item.fields === \"object\"\n    ? formatFields(item.fields) : \"\";\n  return [msg, fields].filter((s) => s !== \"\").join(\" · \");\n}\n\n/**\n * 按 `corr` 相邻折叠成时间线。**只折叠相邻的**（不是全局按 corr 分组）——\n * 与设计意图一致：同一次操作打出的几条事件在时间上天然挨在一起，\n * 隔着别的事件的两条同名 corr 更可能是巧合，不该被强行拼进同一条时间线。\n *\n * 本期几乎没有事件带 `corr`（P3c 才串进注册机），**无 corr 的每条都是独立的单条组**\n * ——这条函数在\"一个 corr 都没有\"时必须一样能正确工作（见 `tests/ui/events.test.ts`\n * 的人工冒烟项）。\n */\nexport function groupEvents(items) {\n  if (!Array.isArray(items)) return [];\n  const groups = [];\n  for (const item of items) {\n    const corr = item && typeof item === \"object\" && typeof item.corr === \"string\" && item.corr !== \"\"\n      ? item.corr : null;\n    const last = groups[groups.length - 1];\n    if (corr !== null && last && last.corr === corr) {\n      last.items.push(item);\n    } else {\n      groups.push({ corr, items: [item] });\n    }\n  }\n  return groups;\n}\n\n/** 后端给的是 ts 降序（最新在前）；面板要\"自动滚动\"到最新，按时间正序（旧→新）展示。 */\nexport function orderForDisplay(items) {\n  return Array.isArray(items) ? [...items].reverse() : [];\n}\n\n/**\n * 把新拉到的一批（ts 降序，且全部比 `existing` 里任何一条都新——由 `after` 游标保证）\n * 并入客户端已经攒下的视图。**新的在前**，保持整体仍是 ts 降序，与后端契约一致，\n * 只在渲染前的最后一步（`orderForDisplay`）才反转成正序。\n */\nexport function mergeIntoView(existing, incoming) {\n  const inc = Array.isArray(incoming) ? incoming : [];\n  const cur = Array.isArray(existing) ? existing : [];\n  return [...inc, ...cur];\n}\n", type: "text/javascript; charset=utf-8", etag: "\"80077830abe3fe17\"" },
  "/admin/js/pure/format.mjs": { body: "/**\n * 面板的格式化。**全部纯函数**：无副作用、不读环境、时间与时区都从参数进。\n *\n * 时区必须从参数进，不许读运行环境的本地时区：Worker 上是 UTC、用户浏览器里是本地时区，\n * 同一份数据两种显示就是面板在撒谎。面板统一按「用户浏览器时区」渲染并**标注偏移**，\n * 偏移量由调用方算好传进来。\n *\n * 这个目录下的文件受三条硬规则约束，规则全文见 admin-ui/README.md。\n */\n\n/** 没有值就是没有值。**绝不伪造 0**——接口失败显示 0 会让运维以为「真的是零」。 */\nexport function fmtDash(v) {\n  if (v === null || v === undefined) return \"—\";\n  if (typeof v === \"number\" && !Number.isFinite(v)) return \"—\";\n  return String(v);\n}\n\n/** 千分位。**刻意不做 1.2k 这种有损缩写**：运维要的是准确数字。 */\nexport function fmtCount(v) {\n  if (v === null || v === undefined || typeof v !== \"number\" || !Number.isFinite(v)) return \"—\";\n  const neg = v < 0;\n  const s = String(Math.trunc(Math.abs(v))).replace(/\\B(?=(\\d{3})+(?!\\d))/g, \",\");\n  return neg ? `-${s}` : s;\n}\n\n/**\n * 百分比，一位小数。\n * **分母为 0 时返回 —，不是 0.0%**：「一次都没跑过」与「成功率 0%」是两回事，\n * 后者会让运维去查一把其实从没被用过的 key。\n */\nexport function fmtPercent(num, den) {\n  if (typeof num !== \"number\" || typeof den !== \"number\") return \"—\";\n  if (!Number.isFinite(num) || !Number.isFinite(den) || den <= 0) return \"—\";\n  return `${((num / den) * 100).toFixed(1)}%`;\n}\n\n/**\n * 时长。负数（时钟回拨、冷却已到期）一律按 0 渲染——显示「-3秒」只会让人以为读错了。\n * 只到两档精度：再细的位数在运维场景里没有信息量，只会让列宽跳动。\n */\nexport function fmtDuration(ms) {\n  if (ms === null || ms === undefined || typeof ms !== \"number\" || !Number.isFinite(ms)) return \"—\";\n  const t = Math.max(0, Math.trunc(ms));\n  const s = Math.trunc(t / 1000);\n  if (s < 60) return `${s}秒`;\n  const m = Math.trunc(s / 60);\n  if (m < 60) return `${m}分${s % 60}秒`;\n  const h = Math.trunc(m / 60);\n  if (h < 24) return `${h}小时${m % 60}分`;\n  return `${Math.trunc(h / 24)}天${h % 24}小时`;\n}\n\n/**\n * 字节数 → MB，一位小数。**只用于概览页的 RSS 展示**，`0` 与「没有值」必须分得开：\n * 一个刚起的进程 RSS 确实可能非常小，但绝不会是 0——把「没有值」渲染成 `0 MB`\n * 会让运维误读成「进程占用真的是零」。\n */\nexport function fmtBytesMb(bytes) {\n  if (bytes === null || bytes === undefined || typeof bytes !== \"number\" || !Number.isFinite(bytes)) return \"—\";\n  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;\n}\n\n/**\n * 时刻。`offsetMs` 是要渲染的时区相对 UTC 的偏移（毫秒），由调用方算好传进来。\n * 尾巴上的 `UTC+N` **必须有**：不标时区的时间戳在多 colo 部署里毫无意义。\n */\nexport function fmtInstant(ms, offsetMs) {\n  if (ms === null || ms === undefined || typeof ms !== \"number\" || !Number.isFinite(ms)) return \"—\";\n  const off = typeof offsetMs === \"number\" && Number.isFinite(offsetMs) ? offsetMs : 0;\n  const d = new Date(ms + off);\n  const p = (n, w) => String(n).padStart(w, \"0\");\n  const body = `${d.getUTCFullYear()}-${p(d.getUTCMonth() + 1, 2)}-${p(d.getUTCDate(), 2)} `\n    + `${p(d.getUTCHours(), 2)}:${p(d.getUTCMinutes(), 2)}:${p(d.getUTCSeconds(), 2)}`;\n  const hours = off / 3600_000;\n  const sign = hours < 0 ? \"-\" : \"+\";\n  const abs = Math.abs(hours);\n  const label = Number.isInteger(abs) ? String(abs) : abs.toFixed(2).replace(/0+$/, \"\").replace(/\\.$/, \"\");\n  return `${body} UTC${sign}${label}`;\n}\n", type: "text/javascript; charset=utf-8", etag: "\"80483d284a14e96c\"" },
  "/admin/js/pure/keys.mjs": { body: "/**\n * Key 池板块的**全部取值决策**。板块文件（`js/sec-keys.js`）只剩 DOM 拼装与网络调用。\n *\n * 这不是「顺手拆一下」：admin-ui/README.md 的硬规则 1 就是这么写的\n * （需要测试的逻辑必须放这个目录），而本板块第一版把这些决策留在了板块文件里，\n * 结果 `counts()` 那个「没有数据就当 0」的兜底**直接违反了「绝不伪造 0」**\n * 而没有任何东西能发现——接口一失败，四张汇总卡显示 `0/0/0/0`，\n * 运维看到「可用 0」的第一反应是整池死了。搬到这里之后 `tests/ui/keys.test.ts` 跑得到它。\n *\n * 这个目录下的文件受三条硬规则约束（禁 import、禁浏览器全局、纯文本校验），\n * 规则全文见 admin-ui/README.md。\n */\n\n/** 四个分档。顺序即渲染顺序（汇总卡与筛选下拉共用）。 */\nexport const CARDS = [\"all\", \"fresh\", \"cooling\", \"evicted\"];\n\n/** 自动刷新档位（秒）。**首项是 0 = 关**：面板不替用户决定去轮询。 */\nexport const AUTO_SECONDS = [0, 30, 60];\n\n/**\n * 汇总卡 / 筛选下拉里的条数。\n *\n * **没有数据时逐项返回 `null`，绝不返回 0。** `null` 会被格式化成 `—`。\n * 返回 0 就是伪造一个「我知道，答案是零」的事实——而字典里那句\n * `common.loadFailed` 逐字写着「读取失败，显示为 —」，两边不能各说各的。\n */\nexport function cardCounts(data) {\n  const c = data && typeof data === \"object\" ? data.counts : null;\n  const out = {};\n  for (const k of CARDS) {\n    const v = c && typeof c === \"object\" ? c[k] : null;\n    out[k] = typeof v === \"number\" && Number.isFinite(v) ? v : null;\n  }\n  return out;\n}\n\nexport function badgeClass(bucket) {\n  if (bucket === \"evicted\") return \"badge badge-danger\";\n  if (bucket === \"cooling\") return \"badge badge-warn\";\n  return \"badge badge-ok\";\n}\n\n/** 分档名的 i18n key。**四条各写一次字面量**，好让 i18n 门禁扫得到。 */\nexport function bucketLabelKey(bucket) {\n  if (bucket === \"fresh\") return \"keys.bucket.fresh\";\n  if (bucket === \"cooling\") return \"keys.bucket.cooling\";\n  if (bucket === \"evicted\") return \"keys.bucket.evicted\";\n  return \"keys.bucket.all\";\n}\n\nexport function autoLabelKey(sec) {\n  if (sec === 30) return \"keys.auto.30\";\n  if (sec === 60) return \"keys.auto.60\";\n  return \"keys.auto.off\";\n}\n\n/**\n * 列表请求的查询串。\n *\n * `q` 必须转义：搜索框里的 `&` / `=` / `#` 不转义会把后面的参数整个吃掉\n * （`?q=a&bucket=evicted` 会被解析成两个参数），而 `bucket` 是个安全过滤器\n * ——用户敲一个 `&` 就能看到与筛选器显示不符的列表。\n * `all` 档**不发 bucket 参数**：后端把无法识别的值当作不筛，发过去只是噪音。\n */\nexport function keysQuery(state) {\n  const parts = [`page=${state.page}`, `size=${state.size}`];\n  if (state.bucket && state.bucket !== \"all\") parts.push(`bucket=${encodeURIComponent(state.bucket)}`);\n  if (state.q !== undefined && state.q !== null && state.q !== \"\") parts.push(`q=${encodeURIComponent(state.q)}`);\n  return parts.join(\"&\");\n}\n\n/**\n * 冷却剩余毫秒。**只有 cooling 档才有这个值**，其余一律 `null`（渲染成 `—`）。\n *\n * 参照时刻用服务端的 `generatedAt` 而不是浏览器时钟：两者不同源，拿浏览器的 now\n * 去减服务端的 `cooldownUntil`，时钟有偏差时会算出负数或虚高的剩余时间。\n */\nexport function cooldownRemaining(view, now) {\n  if (!view || view.bucket !== \"cooling\") return null;\n  if (typeof view.cooldownUntil !== \"number\" || !Number.isFinite(view.cooldownUntil)) return null;\n  return view.cooldownUntil - now;\n}\n\n/** 最近一次错误。没有就是 `null`——**不返回空串**，空串会被渲染成一个空格子而不是 `—`。 */\nexport function lastErrorParts(view) {\n  const s = view && view.stats ? view.stats : null;\n  if (!s || typeof s.lastErrorKind !== \"string\" || s.lastErrorKind === \"\") return null;\n  return { kind: s.lastErrorKind, at: typeof s.lastErrorAt === \"number\" ? s.lastErrorAt : null };\n}\n\n/**\n * 用量格。`approx` **由后端的 `approximate` 驱动**，不是无条件打 `≈`。\n *\n * 一个没有消费者的响应字段迟早会漂：后端说「这批数字是准的」而面板照样打 `≈`\n * （或反过来）就是两边各说各的。响应里没带这个字段时按**近似**处理——\n * 保守方向是「宁可多打一个 ≈」，不是「悄悄宣称精确」。\n */\nexport function usageParts(view, approximate) {\n  const s = (view && view.stats) || {};\n  return {\n    approx: approximate !== false,\n    requests: typeof s.requests === \"number\" ? s.requests : null,\n    success: typeof s.success === \"number\" ? s.success : null,\n  };\n}\n\n/**\n * 「最后使用」同样是近似值。\n *\n * 它与计数的 staleness **完全相同**（同一次落盘一起带下去），而 `lastUsedAt` 正是\n * 写消除的头号对象：五语言 DEPLOY.md 的 `POOL_TOUCH_INTERVAL_MS` 那一行逐字写着\n * 「面板『最后使用』的精度最粗到这个间隔」（默认 6 小时）。计数打了 `≈` 而它裸着，\n * 就是同一份不确定性只标了一半——运维恰恰靠这一列判断「这把 key 是不是已经不转了」。\n * **从未使用过（null）时不打 `≈`**：那不是「不准」，那是确定的「没用过」。\n */\nexport function lastUsedParts(view, approximate) {\n  const at = view && typeof view.lastUsedAt === \"number\" ? view.lastUsedAt : null;\n  return { at, approx: at !== null && approximate !== false };\n}\n\n/**\n * 「这份响应里有没有可渲染的条目」——**全模块唯一的判据**。\n *\n * 存在的理由：分页复位、列表消息、要不要建表这三处以前各写各的，\n * 其中「`items` 不是数组」一处当空列表、一处放行去建表，一份畸形响应就会走到\n * `for (const v of data.items)` 抛异常。今天后端恒返回数组、走不到，\n * 但三处判据并存本身就是下一次改动的绊子。\n */\nexport function itemsOf(data) {\n  return data && typeof data === \"object\" && Array.isArray(data.items) ? data.items : null;\n}\n\n/**\n * 分页控件的状态。**两条早退分支（读失败 / 空列表）必须一并复位**，\n * 否则读失败之后下面还挂着上一次的「第 1/2 页 · 共 3 条」，那是在展示一份已经不存在的数据。\n */\nexport function pagerState(data) {\n  const items = itemsOf(data);\n  if (items === null || items.length === 0) {\n    return { prevDisabled: true, nextDisabled: true, info: null };\n  }\n  const page = typeof data.page === \"number\" ? data.page : 1;\n  const pages = typeof data.pages === \"number\" ? data.pages : 1;\n  const total = typeof data.total === \"number\" ? data.total : 0;\n  return {\n    prevDisabled: page <= 1,\n    nextDisabled: page >= pages,\n    info: { page, pages, total },\n  };\n}\n\n/**\n * 列表区该显示哪条消息（`null` = 显示表格）。\n *\n * 「池子里还没有 key」与「没有符合条件的 key」必须分开：前者是「去导入」，\n * 后者是「把筛选条件放宽」，指向完全相反的动作。\n */\nexport function listMessageKey(data, loadError) {\n  if (loadError) return \"common.loadFailed\";\n  const items = itemsOf(data);\n  if (items === null || items.length > 0) return null;\n  const c = cardCounts(data);\n  return c.all === 0 ? \"keys.empty\" : \"keys.noMatch\";\n}\n", type: "text/javascript; charset=utf-8", etag: "\"2402cf65d5ec4f0e\"" },
  "/admin/js/pure/mask.mjs": { body: "/**\n * 上游 key 的掩码。\n *\n * `KeyPoolRepo.all()` 返回的记录含完整明文 key，直接吐给面板等于把整池上游 key\n * 交出去，所以掩码是硬规则，不是显示偏好。\n *\n * **这个目录（js/pure）下的文件受三条硬规则约束**，由 scripts/build-ui.mjs 与\n * tests/unit/ui-assets.test.ts 各守一道，规则全文见 admin-ui/README.md。\n * 其中一条禁止触碰浏览器全局，而校验是**纯文本匹配、不解析注释**——所以那几个\n * 全局的名字连注释里都不许写出来，本文件因此只在 README 里展开说明。\n */\nexport function maskKey(key) {\n  // 阈值 10：再短就不值得掩码了（前 5 + 后 4 会把几乎整串露出来），一律整串隐去。\n  // **绝不返回原值**：返回原值的「掩码」比没有掩码更糟，调用方会以为它安全了。\n  if (typeof key !== \"string\" || key.length <= 10) return \"…\";\n  return `${key.slice(0, 5)}…${key.slice(-4)}`;\n}\n", type: "text/javascript; charset=utf-8", etag: "\"00ab474c062a7ade\"" },
  "/admin/js/pure/overview.mjs": { body: "/**\n * 概览板块的**全部取值决策**。板块文件（`js/sec-overview.js`）只剩 DOM 拼装、\n * 网络调用与 i18n 查表。理由与 `pure/keys.mjs` 同一条（admin-ui/README.md 硬规则 1）：\n * Task 4 的 `cardCounts()` 就是把这类判断留在板块文件里而漏掉「绝不伪造 0」的地方，\n * 这里从第一天就把它们搬过来，好让 `tests/ui/overview.test.ts` 跑得到。\n *\n * 这个目录下的文件受三条硬规则约束（禁 import、禁浏览器全局、纯文本校验），\n * 规则全文见 admin-ui/README.md。\n */\n\n/** 4 张池子卡。顺序即渲染顺序。 */\nexport const POOL_CARDS = [\"total\", \"fresh\", \"cooling\", \"evicted\"];\n\n/** 池子卡的 i18n key。**四条各写一次字面量**，好让 i18n 门禁扫得到（同 keys.mjs 的 bucketLabelKey）。 */\nexport function poolCardLabelKey(card) {\n  if (card === \"fresh\") return \"ov.pool.fresh\";\n  if (card === \"cooling\") return \"ov.pool.cooling\";\n  if (card === \"evicted\") return \"ov.pool.evicted\";\n  return \"ov.pool.total\";\n}\n\n/** 运行时名字 → i18n key。判据只看响应里 `runtime.name` 这一个字符串字段。 */\nexport function runtimeNameLabelKey(name) {\n  return name === \"worker\" ? \"ov.runtime.worker\" : \"ov.runtime.node\";\n}\n\n/** 存储后端 → i18n key。 */\nexport function storageBackendLabelKey(backend) {\n  return backend === \"kv\" ? \"ov.storage.kv\" : \"ov.storage.file\";\n}\n\n/**\n * 4 张池子卡的取数。**没有数据（`pool` 为 null）时逐项返回 `null`，绝不返回 0。**\n * 判据只看 `body.pool` 存不存在、形状对不对，不看别的块——`overview` 是逐块降级的，\n * 池子块坏了不该连累别的卡。\n */\nexport function poolCounts(body) {\n  const p = body && typeof body === \"object\" ? body.pool : null;\n  const keys = [\"total\", \"fresh\", \"cooling\", \"evicted\"];\n  const out = {};\n  for (const k of keys) {\n    const v = p && typeof p === \"object\" ? p[k] : null;\n    out[k] = typeof v === \"number\" && Number.isFinite(v) ? v : null;\n  }\n  return out;\n}\n\n/**\n * 运行时信息面板里「内存 / 进程存活 / PID」三格该怎么渲染。\n *\n * **判据是 `body.process === null`，不是 `runtime.name === \"worker\"`**——设计文档\n * §13.3 第 6 条与硬约束 1 都点名要求形态分支只读接口返回的实际数据，不许自己嗅探\n * 运行时名字。返回 `{ kind: \"serverless\" }` 时面板显示「Serverless · 无常驻进程」，\n * **不是 0、不是空、不隐藏格子**；返回 `{ kind: \"metrics\", ... }` 时才显示真实数字。\n */\nexport function processCells(body) {\n  const p = body && typeof body === \"object\" ? body.process : undefined;\n  if (p === null) return { kind: \"serverless\" };\n  if (!p || typeof p !== \"object\" || Array.isArray(p)) return { kind: \"unknown\" };\n  const pid = typeof p.pid === \"number\" ? p.pid : null;\n  const rssBytes = typeof p.rssBytes === \"number\" ? p.rssBytes : null;\n  const uptimeMs = typeof p.uptimeMs === \"number\" ? p.uptimeMs : null;\n  return { kind: \"metrics\", pid, rssBytes, uptimeMs };\n}\n\n/**\n * 累计用量卡的五个数。**`poolStats` 为 null 时全部 null**（绝不伪造 0），\n * 成功率交给调用方用 `fmtPercent` 现算——这里只投影原始计数，不重复实现百分比逻辑。\n *\n * **`approx` 由响应的 `approximate` 字段驱动**（产品不变式 10：近似值必须带 `≈`）。\n * 这是 Task 4 评审 I4 的原样复发——那一次的裁定是「一个没有消费者的响应字段迟早会\n * 漂」，第一版的 `usageStats()` 就是又一次没有消费者的字段：写了「由 approximate\n * 驱动」的注释，却没有真的读它，`sec-overview.js` 把 `（≈）` 硬编码进了标题。\n * 响应里没带这个字段（block 缺失）时按**近似**处理——保守方向是宁可多打一个 ≈，\n * 不是悄悄宣称精确，与 `pure/keys.mjs` 的 `usageParts()` 同一条哲学。\n */\nexport function usageStats(body) {\n  const s = body && typeof body === \"object\" ? body.poolStats : null;\n  const numOrNull = (v) => (typeof v === \"number\" && Number.isFinite(v) ? v : null);\n  if (!s || typeof s !== \"object\") {\n    return { requests: null, success: null, failed: null, clientErrors: null, approx: true };\n  }\n  return {\n    requests: numOrNull(s.requests), success: numOrNull(s.success),\n    failed: numOrNull(s.failed), clientErrors: numOrNull(s.clientErrors),\n    approx: s.approximate !== false,\n  };\n}\n\n/**\n * 配置摘要卡。**`config` 整块缺失（存储读失败）时返回 `null` 这一个哨兵**，\n * 不是逐字段各自 null——`primary`/`fallback` 在 `config` 块**存在**时本来就可能是\n * 合法的 `null`（注册机未启用，两条通道平级、没有默认值），把「整块读不出来」\n * 与「读出来了、确实没配」用同一个 `null` 表示，调用方就分不清该显示 `—`\n * 还是显示「无」——这正是本任务实现时抓到的一个真实 bug（评审前自查）。\n */\nexport function configSummary(body) {\n  const c = body && typeof body === \"object\" ? body.config : null;\n  if (!c || typeof c !== \"object\") return null;\n  const envLocked = Array.isArray(c.envLocked) ? c.envLocked.filter((x) => typeof x === \"string\") : [];\n  return {\n    registrarEnabled: typeof c.registrarEnabled === \"boolean\" ? c.registrarEnabled : null,\n    primary: typeof c.primary === \"string\" ? c.primary : null,\n    fallback: typeof c.fallback === \"string\" ? c.fallback : null,\n    targetKeys: typeof c.targetKeys === \"number\" ? c.targetKeys : null,\n    envLocked,\n    degraded: typeof c.degraded === \"boolean\" ? c.degraded : null,\n  };\n}\n\n/**\n * 存储卡。`overview.storage` 不经过逐块降级（它是内存态的 getter，读不出「失败」这回事），\n * 但响应仍可能畸形（接口读失败时整段 body 都拿不到），故一样做防御式取值。\n */\nexport function storageInfo(body) {\n  const s = body && typeof body === \"object\" ? body.storage : null;\n  if (!s || typeof s !== \"object\") return { backend: null, writable: null, checkedAt: null };\n  return {\n    backend: s.backend === \"file\" || s.backend === \"kv\" ? s.backend : null,\n    writable: typeof s.writable === \"boolean\" ? s.writable : null,\n    checkedAt: typeof s.checkedAt === \"number\" ? s.checkedAt : null,\n  };\n}\n\n/**\n * 新鲜度卡的六个数，原样投影（`overview.freshness` 本身不参与逐块降级，\n * 除非整段响应都拿不到）。\n */\nexport function freshnessValues(body) {\n  const f = body && typeof body === \"object\" ? body.freshness : null;\n  const numOrNull = (v) => (typeof v === \"number\" && Number.isFinite(v) ? v : null);\n  if (!f || typeof f !== \"object\") {\n    return {\n      poolCacheTtlMs: null, poolVisibilityUpperBoundMs: null, poolTouchIntervalMs: null,\n      configTtlMs: null, configVisibilityUpperBoundMs: null, kvEdgeCacheMs: null,\n    };\n  }\n  return {\n    poolCacheTtlMs: numOrNull(f.poolCacheTtlMs),\n    poolVisibilityUpperBoundMs: numOrNull(f.poolVisibilityUpperBoundMs),\n    poolTouchIntervalMs: numOrNull(f.poolTouchIntervalMs),\n    configTtlMs: numOrNull(f.configTtlMs),\n    configVisibilityUpperBoundMs: numOrNull(f.configVisibilityUpperBoundMs),\n    kvEdgeCacheMs: numOrNull(f.kvEdgeCacheMs),\n  };\n}\n\n/**\n * `POOL_CACHE_TTL_MS` / `POOL_TOUCH_INTERVAL_MS` 这两个旋钮的**当前生效值**。\n *\n * **两个板块共用这一个函数**：Key 池板块（`sec-keys.js`）的文案曾经（Task 4）只能\n * 「点名旋钮 + 括注默认值」，因为那时没有任何接口报告这两个旋钮的实际值——它们是\n * 建 app 时读一次、此后不随 `ConfigHolder` 刷新的部署期常量（见 `wire.ts`），\n * 只有 `overview.freshness` 报告了它们。两个板块各自 fetch 一次 `/overview`\n * 拿到同一份数据，用这个函数取出同一对数字，不许各写各的取值逻辑。\n */\nexport function poolKnobs(body) {\n  const f = freshnessValues(body);\n  return { ttl: f.poolCacheTtlMs, touch: f.poolTouchIntervalMs };\n}\n\n/**\n * Worker 存储卡那一行「本部署的 KV 读写与请求数无关，只取决于刷新频率」的估算。\n *\n * 公式与 `keypool-repo.ts` 的 `KeyPoolRepoOptions.cacheTtlMs` 文档同源（**每个\n * isolate 每天**）：`(86400000 / 池快照TTL) × (1 + 池中key数) + 86400000 / 配置TTL`。\n * **这是单个 isolate 的估算，不是全部署的总量**——总量还要乘以并发的 isolate 数目，\n * 而那个数字面板拿不到，文案必须老实说清楚，不能默认成 1。\n *\n * `poolCacheTtlMs <= 0`（关闭快照缓存，即「每次都真读」）时公式的前提整个不成立\n * ——那种配置下读写次数直接和请求量挂钩，不再是「与请求数无关」，返回 `null`\n * 表示「给不出这个估算」，不是伪造一个基于错误前提的数字。\n */\nexport function kvReadEstimatePerIsolatePerDay(body) {\n  const f = freshnessValues(body);\n  const pool = poolCounts(body);\n  if (f.poolCacheTtlMs === null || f.poolCacheTtlMs <= 0) return null;\n  if (f.configTtlMs === null || f.configTtlMs <= 0) return null;\n  if (pool.total === null) return null;\n  const DAY_MS = 86_400_000;\n  const poolReads = (DAY_MS / f.poolCacheTtlMs) * (1 + pool.total);\n  const configReads = DAY_MS / f.configTtlMs;\n  return Math.round(poolReads + configReads);\n}\n", type: "text/javascript; charset=utf-8", etag: "\"57b284aebd4d8bb4\"" },
  "/admin/js/pure/sendable.mjs": { body: "/**\n * 管理口令的字符集判定。**前后端共用同一份定义**（后端那份是\n * `src/http/admin/auth.ts` 的 `SENDABLE` / `isSendable`），由\n * `tests/ui/sendable-parity.test.ts` 的**逐码位行为等价**断言钉着。\n *\n * ── 字符集是 `0x20–0x7E`，理由分三段，性质不同，别再混着说 ────────────────\n *\n * 上一版把这三段压成一句「浏览器发不出去的字符」，那句话对其中一段是**假的**，\n * 而它在八处以上被复述。危害不是安全洞（方向仍是 fail closed），是**对运维说了\n * 一句他一试就能证伪的话**——他在浏览器里试一下发现送得出去，然后认定网关在骗人。\n *\n * **(a) 码点 > U+00FF，以及 NUL / LF / CR —— 物理，发生在浏览器。**\n *   `new Headers().set()` 直接抛 `TypeError`（Fetch 规范：头值是 ByteString，\n *   码点 > 255 转不过去；NUL/LF/CR 过不了头值校验）。实测（node v24 的 undici，\n *   与浏览器同一套规范实现）：CJK / emoji / 零宽空格 / NUL / LF / CR 全部 **THROWS**。\n *   这种口令会装出一棵 200 但永远进不去的面板：用户看到「网络错误」，\n *   而服务端**连一条 login_failed 都没有**（请求压根没发出来）。\n *\n * **(b) `0x01–0x08`、`0x0B`、`0x0C`、`0x0E–0x1F`、`0x7F`（共 29 个）—— 物理，\n *   但发生在服务端解析器。**\n *   浏览器**送得出去**（`Headers.set` ACCEPTED），HTTP 解析器才拒：实测\n *   （裸 `http.createServer` + 原始 socket 逐字节注入）一律 **400 Bad Request**。\n *\n *   ⚠️⚠️ **TAB `0x09` 是例外，它不在这一段，落在 (c)。** HTAB 是 RFC 9110 里合法的\n *   field-value 字符：实测 `Headers.set` ACCEPTED、解析器 **200 OK**、\n *   handler 收到 U+0009。**这一条订正的是本注释自己**——上一版写「其余 C0 控制字符\n *   与 0x00–0x1F」，而当时只实测过 BEL / ESC / DEL / NEL 四个：**抽样实测，\n *   却写下范围断言**。现在这三段的边界是**全 256 字节穷举**量出来的。\n *   ⚠️ **workerd 侧没验**，如实标注：这是个双运行时项目，别把 Node 的实测当成两边的答案。\n *\n * **(c) TAB `0x09` 与整段 `0x80–0xFF`（`é` `£` 不间断空格 …）—— 送得出去，也真的能用。\n *   排除它们是我们的稳健性取舍，是口味，不是物理。**\n *   （上一版写「`0x80–0xFF` **可打印**字节」不准确：`0x80–0x9F` 是 C1 控制符、并不可打印，\n *   而它们同样落在这一段。）\n *   实测：浏览器侧 ACCEPTED；Node 解析器侧 **200 OK**，handler 收到的码点与发出的\n *   逐一对应（`0xE9` → U+00E9）；而 `process.env` 里 UTF-8 的 `é` 解出来同样是 U+00E9\n *   ⇒ 两者**逐码点相等**，`ADMIN_TOKEN=\"admin-token-café-0123456789\"` 端到端能用。\n *   （实测同时订正了一处分组：**NEL 0x85 不被 Node 解析器拒**，200 OK 且如实交出\n *   U+0085 —— 它是 C1，结构上属于本段而不是 (b)。）\n *\n *\n *   ⚠️ **TAB `0x09` 与 `0x80–0xFF` 虽然同属 (c)，拦它们的理由并不相同，别混着说**\n *   （刚在 (b) 上栽过一次范围断言，这里不再重蹈）：\n *     · **TAB**：它是**不可见字符**。粘进 `.env` 或 secret 里没人看得见，与\n *       whitespace_padded 挡的是同一类可诊断性问题——只不过首尾空白那条是物理\n *       （传输层会去掉），TAB 这条纯粹是取舍。\n *     · **`0x80–0xFF`**：理由是编码口径，见下面两条。\n *\n *   `0x80–0xFF` 那半为什么还是拦？两条，都写清楚：\n *     · **跨运行时编码口径不一致是真的**：环境变量按 UTF-8 解、HTTP 头值按 Latin-1 解，\n *       两边碰巧在 U+0080–U+00FF 这段对上是**实现细节**，不是规范承诺；\n *       **而 workerd 侧我们没验过**，双运行时项目里未验证的行为差异就是风险。\n *     · RFC 9110 已把 obs-text（0x80–0xFF）标为**弃用**，中间件/反代对它的处置各不相同。\n *   而非 ASCII 口令**不是一个有价值的形态**（它不比同长度的 ASCII 更强），是个坑。\n *\n * ── 与「空格」那条的区别（本轮评审刚裁过，写在这里免得下次又摇摆）─────────\n *\n * 空格 0x20 也曾被排除，理由是「怕复制粘贴出错」——那条**已经被裁掉并放行**了，\n * 因为：空格是**纯 ASCII，跨运行时零编码歧义**，而带空格的 passphrase\n * （`correct horse battery staple`）是**有价值的常见形态**，拒它纯属替运维做主。\n * `0x80–0xFF` 两条都不成立：有真实的编码歧义、又不是有价值的形态。\n * **判据不是「是不是口味」，而是「这个限制换来的稳健性值不值它挡掉的形态」。**\n * (c) 仍然是口味，只是这一次口味的收益 > 代价——所以它被**标成口味**保留，\n * 而不是被伪装成物理。\n *\n * 这个目录下的文件受三条硬规则约束，规则全文见 admin-ui/README.md。\n */\n\n/**\n * 量词是 `*`：这条规则说的是「不含送不出去的字符」，**非空不是它的职责**\n *（后端归 `too_short`，前端归 `gate.empty`，两边各自的上游判断都先把空串接走了）。\n *\n * ⚠️ 上一版前端写 `+`、后端写 `*`，是一处刻意但**多余**的不对称：它让「两边一致」\n * 这句话必须带一个空串的例外，护栏也就只能做到「除了空串以外一致」。\n * 统一成 `*` 之后，等价关系对**全部输入**成立，`sendable-parity` 才能做无例外的\n * 逐码位行为断言。行为没有变化：`app.js` 里 `if (!key)` 仍然先接走空输入。\n */\nconst SENDABLE_RE = /^[\\x20-\\x7e]*$/;\n\n/** 这个字符串能不能被客户端送出去、并被服务端解析器收下。 */\nexport function sendable(s) {\n  return SENDABLE_RE.test(s);\n}\n", type: "text/javascript; charset=utf-8", etag: "\"6023be1aacd6f654\"" },
  "/admin/js/pure/session.mjs": { body: "/**\n * 会话绝对上限的**取值决策**。\n *\n * localStorage 里放的是**原始的 `ADMIN_TOKEN`**，无过期、无登出、产品内无撤销路径\n *（撤销的唯一方式是改 secret 重新部署 / 重建容器，见设计文档 §8.1 规则 2）。\n * 上限管不了「口令已经被偷走」，它管的是**这份 localStorage 值还能被继续用多久**：\n * 一台被别人摸过的运维机器，可用期从「永远」压到「最多 12 小时」。\n *\n * ⚠️ **明说做不到的那一半**：CSP 的 `connect-src 'self'` 挡得住把口令 fetch 出去，\n * `form-action 'none'` 挡得住表单外传，**但挡不住 `location.href = \"https://…?k=\" + token`\n * 这种导航式外传**——CSP 已经没有可用的指令拦它（`navigate-to` 被规范移除了）。\n * 真正的解法是服务端签发可撤销的派生令牌，那要动「ADMIN_TOKEN 只从环境变量读」\n * 这条设计约束，登记 P3c。这段话同时写进了五语言 DEPLOY.md，不只留在注释里。\n *\n * ⚠️ **为什么这个决策在 `js/pure/` 而不是 `js/app.js` 里**（这一条是对计划的订正）：\n * 计划写的是「`SESSION_MAX_AGE_MS` 与 `sessionExpired()` 碰 localStorage 与 Date，\n * 在 node 环境里 import 就会炸 ⇒ 只由人工冒烟覆盖」。前半句对**读取**成立，\n * 对**判定**不成立：把「存下的时刻」与「现在」都变成参数之后，判定本身是纯函数\n *（这正是 admin-ui/README.md 硬规则 1 要求的形态）。碰浏览器全局的那一小段留在\n * `app.js` 里，由冒烟清单第 15/16 条覆盖；判定这一半在这里，由\n * `tests/ui/session.test.ts` 覆盖。\n *\n * 这个目录下的文件受三条硬规则约束，规则全文见 admin-ui/README.md。\n */\n\n/** 会话绝对上限：**12 小时**。理由见上。 */\nexport const SESSION_MAX_AGE_MS = 12 * 3600_000;\n\n/**\n * 这份存下来的口令是不是已经到达绝对上限，该要求重新输入了。\n *\n * `savedAt` 是写入口令那一刻的毫秒时间戳，`now` 是当前毫秒时间戳。两个都从参数进，\n * 因此这个判定与浏览器全局无关，可以直接在 node 里跑。\n *\n * **一律 fail closed**：拿不到有效的时刻就当成过期。少数几种情况值得点名——\n *\n * · `savedAt` 不是有限数 / ≤ 0：旧版本存的（那时还没有这个时刻键），或者存储被人\n *   改花了。按过期处理，代价只是多输一次口令。\n * · `now` 不是有限数：不该发生，但如果发生了，`now - savedAt` 会是 NaN，\n *   而 `NaN < 0` 与 `NaN >= 上限` **都是 false** ⇒ 不显式挡住的话结论会变成\n *   「没过期」，方向正好反了。这是一条 fail open 的缝，所以单独挡一次。\n * · `age < 0`（时钟回拨）：**按过期处理**。这条与后端三处「回拨立刻恢复」方向\n *   **相反**是刻意的：那三处回拨的代价是多刷新一次，这里回拨的代价是一份凭据多活一阵子。\n */\nexport function sessionExpired(savedAt, now) {\n  if (!Number.isFinite(savedAt) || savedAt <= 0) return true;\n  if (!Number.isFinite(now)) return true;\n  const age = now - savedAt;\n  return age < 0 || age >= SESSION_MAX_AGE_MS;\n}\n", type: "text/javascript; charset=utf-8", etag: "\"9f9e0f7744b5bcdf\"" },
  "/admin/js/pure/storage-keys.mjs": { body: "/**\n * 面板用到的**全部浏览器存储键名，单一真源**。\n *\n * ⚠️ **这个文件是全分支评审 C4 的直接产物。** 在它出现之前，`agnes2api_admin_key`\n * 与 `agnes2api_admin_key_at` 这两个名字**各自在两个文件里被声明了两遍**\n *（写入方 `js/app.js` 一份、读取方 `js/api.js` 一份），而两份之间没有任何东西\n * 把它们绑在一起。实测：只改写入方那一处 ⇒ 登录成功、进壳层，随后每个请求送出去的\n * `x-admin-key` 是空串 ⇒ 401 ⇒ 登出循环，**面板彻底不可用，而 1357 条用例全绿**。\n *\n * 它同时满足 admin-ui/README.md 硬规则 1：判据（这里是\"名字是什么\"这个取值决策）\n * 不许留在板块/框架文件里各写一份。\n *\n * ⚠️ **`js/boot.js` 抄不了这里，那是结构性的，不是疏漏**：它是全站唯一的经典脚本\n *（`<head>` 里同步、非 module，理由见该文件头），**经典脚本没有 `import`**。\n * 于是主题与语言这两个名字在 `boot.js` 里必然是字面量。这条缺口不靠自觉，靠\n * `tests/ui/storage-keys.test.ts` 里\"boot.js 的字面量必须与本模块逐字相同\"那一格\n * 兜住——那一格也顺带钉住\"除 boot.js 外任何文件都不许再写 `agnes2api_` 字面量\"。\n *\n * 这个目录下的文件受三条硬规则约束（禁 import、禁浏览器全局、纯文本校验），\n * 规则全文见 admin-ui/README.md。\n */\n\n/** 管理口令本身。**与下面那个时刻键必须一起写、一起清**，理由见 SAVED_AT_STORE。 */\nexport const KEY_STORE = \"agnes2api_admin_key\";\n\n/**\n * 「口令是什么时候存下来的」。会话绝对上限靠它算年龄，判定本身在\n * `js/pure/session.mjs`（`sessionExpired`）。\n *\n * **两个键必须一起写、一起清**：只清口令不清时刻，下次登录前那个时刻还是旧的；\n * 只写口令不写时刻，`sessionExpired()` 拿不到时刻会把刚登录的会话判成过期\n *（方向是 fail closed，但用户会永远进不去）。\n */\nexport const SAVED_AT_STORE = \"agnes2api_admin_key_at\";\n\n/** 上次停留在哪个板块（刷新复原用）。 */\nexport const SECTION_STORE = \"agnes2api_section\";\n\n/** 主题。**`js/boot.js` 里有一份必然的字面量副本**，见文件头。 */\nexport const THEME_STORE = \"agnes2api_theme\";\n\n/** 界面语言。同样在 `js/boot.js` 里有一份必然的字面量副本。 */\nexport const LANG_STORE = \"agnes2api_lang\";\n\n/**\n * 开发期开关：为真时 `t()` 会把缺失的 key 打进控制台。\n * **面板自己从不写它**（只读），运维/开发者手工设，所以它没有\"两处分叉\"的风险；\n * 收进来只是为了让「除 boot.js 外不许再出现 `agnes2api_` 字面量」那条判据能收干净。\n */\nexport const DEBUG_STORE = \"agnes2api_debug\";\n", type: "text/javascript; charset=utf-8", etag: "\"e4a07c853fc71a43\"" },
  "/admin/js/sec-events.js": { body: "/**\n * 事件板块（设计文档 §10.7，本期形状见 P3b 计划 Task 6 Step 7）：\n * 搜索框 + 级别按钮组 + 暂停 + 清空（仅清前端视图）+ 下载 + 自动滚动 + 轮询状态指示灯。\n *\n * 板块契约（设计文档 §9.3）：`{ init?, onShow?, onHide? }`，见 admin-ui/js/app.js\n * 的 showSection。**板块内不许监听 langchange**——框架层会 apply(document) 之后\n * 重跑一次 onShow()。\n *\n * 两条纪律：①一切来自接口的内容一律 textContent；②**取值决策一律不写在这里**，\n * 全在 `js/pure/events.mjs` 里由 `tests/ui/events.test.ts` 跑着（admin-ui/README.md\n * 硬规则 1）。这个文件只剩 DOM 拼装、事件绑定与网络调用。\n *\n * **事件字段视为完全不可信**（里面会出现上游返回的内容与未鉴权请求的路径）：\n * 所有字段一律 `textContent`，绝不 `innerHTML`。\n */\nimport { api } from \"./api.js\";\nimport { t } from \"./i18n.js\";\nimport { el, elI18n, toast } from \"./ui.js\";\nimport { fmtInstant } from \"./pure/format.mjs\";\nimport {\n  LEVELS, levelLabelKey, effectiveLevel, eventLevelLabelKey, levelBadgeClass,\n  eventsQuery, itemsOf, eventsListMessageKey, shardIdOf, generatedAtOf, bufferStatus, shouldWarn,\n  initialPollState, resumePollState, pollOutcome, pollIndicatorState, pollIndicatorLabelKey,\n  matchesSearch, buildDetailText, groupEvents, orderForDisplay, mergeIntoView,\n} from \"./pure/events.mjs\";\n\nconst LIMIT = 200;\n\n/** 板块内部状态。`level` 是 \"all\" 或 LEVELS 里的一个。 */\nconst state = { q: \"\", level: \"all\", paused: false, autoScroll: true };\n\nlet nodes = null;\nlet timer = null;\nlet abort = null;\n/** 客户端已攒下的视图（ts 降序，与后端契约一致；渲染前用 orderForDisplay 反转）。 */\nlet view = [];\n/**\n * 「视图是被『清空』按钮清掉的，不是本来就没有事件」（全分支评审 I5）。\n *\n * 只影响列表区那句话该怎么写（判据在 `pure/events.mjs` 的 `eventsListMessageKey`），\n * 不影响游标——被清掉的事件**刻意**不会自动回来，理由见那个函数的说明。\n * 换筛选级别时归零：那时视图是被整段重拉的，不是被清掉的。\n */\nlet cleared = false;\nlet lastStatus = { dropped: null, budgetExhausted: null, truncated: null, buffered: null, cursorAhead: null };\n/** 最近一次成功响应里的本 isolate 分片 id（评审 M2），驱动轮询指示灯的提示文案。 */\nlet lastShardId = null;\n/** 最近一次成功响应的生成时刻（评审 N1 [LOW]），同样只驱动轮询指示灯的提示文案。 */\nlet lastGeneratedAt = null;\n/**\n * 轮询的全部跨轮状态（游标 / 自愈中 / 退避间隔）。**整体来自 `pollOutcome()` 的\n * `next`，这个文件不再自己算它的任何一个字段**——评审四审 B1：上一版把\"上一轮的\n * 自愈不算这一轮的新内容\"这条跨轮规则的一半写在这里（`justHealed = outcome.resetView`），\n * 而这个文件没有任何自动化覆盖，把那一行改成恒 false 全套用例一条都不红。\n * 判据全部搬回 pure/events.mjs（admin-ui/README.md 硬规则 1）。\n */\nlet pollState = initialPollState();\nlet lastError = false;\nlet loadError = false;\n/** 本板块当前是不是\"正在显示\"这一个（`onShow`/`onHide` 之间）。visibilitychange\n * 处理器据此判断\"该不该在页面重新可见时把轮询接回去\"——不加这一层的话，\n * 离开本板块时 `onHide` 已经把 timer 清成了 null，页面从别的 tab 切回来会\n * 误判成\"因为隐藏而停了\"，把本该保持停着的轮询重新点起来。 */\nlet sectionActive = false;\n\nfunction offsetMs() { return -new Date().getTimezoneOffset() * 60000; }\n\nfunction renderWarnings() {\n  const banner = nodes.warnBanner;\n  banner.style.display = shouldWarn(lastStatus) ? \"\" : \"none\";\n\n  nodes.warnDropped.style.display = lastStatus.dropped !== null && lastStatus.dropped > 0 ? \"\" : \"none\";\n  if (lastStatus.dropped !== null && lastStatus.dropped > 0) {\n    nodes.warnDropped.textContent = t(\"ev.warnDropped\", { count: lastStatus.dropped });\n  }\n\n  nodes.warnBudget.style.display = lastStatus.budgetExhausted === true ? \"\" : \"none\";\n  if (lastStatus.budgetExhausted === true) nodes.warnBudget.textContent = t(\"ev.warnBudget\");\n\n  nodes.warnTruncated.style.display = lastStatus.truncated === true ? \"\" : \"none\";\n  if (lastStatus.truncated === true) nodes.warnTruncated.textContent = t(\"ev.warnTruncated\");\n\n  // 评审 C6：`cursorAhead` 为 true 时 `poll()` 已经把 `pollState.after` 自愈成\n  // null（见下方 poll()），下一轮就会带着新游标重新冷读——这条提示只是让运维知道\n  // \"刚刚发生过一次自动恢复\"，不是要人手动做什么。\n  // ⚠️ 评审四审：这条黄条**逐轮覆盖、没有粘性**——`cursorAhead=false` 的那一轮\n  // 它就灭了。持续的跨 isolate 时钟偏移下它会跟着视图一起闪（亮一轮灭一轮），\n  // 不是\"持续亮着的告警\"。**这一行本身没有任何自动化守护**（本仓无 DOM 测试通道，\n  // 实测把它改成粘性全套用例照样全绿）；tests/contract/events-cursor-heal.test.ts\n  // 钉住的是它的**输入**——后端 cursorAhead 字段逐轮交替这个根因。\n  nodes.warnCursorAhead.style.display = lastStatus.cursorAhead === true ? \"\" : \"none\";\n  if (lastStatus.cursorAhead === true) nodes.warnCursorAhead.textContent = t(\"ev.warnCursorAhead\");\n}\n\nfunction renderPollIndicator() {\n  const kind = pollIndicatorState({ paused: state.paused, lastError });\n  nodes.pollDot.className = `poll-dot poll-dot-${kind}`;\n  let label = t(pollIndicatorLabelKey(kind));\n  if (lastShardId !== null) label += t(\"ev.pollStatus.shardSuffix\", { shardId: lastShardId });\n  // 评审 N1：`buffered` 是\"本 isolate 还没落盘的事件数\"——单纯有数字不算异常\n  // （见 pure/events.mjs 的 shouldWarn 注释），但 isolate 随时可能被回收，\n  // 这里没有黄条那么显眼，但至少让愿意看 tooltip 的人看得到这个风险。\n  if (lastStatus.buffered !== null && lastStatus.buffered > 0) {\n    label += t(\"ev.pollStatus.bufferedSuffix\", { count: lastStatus.buffered });\n  }\n  // 评审 N1 [LOW]：`generatedAt` 是响应生成时刻，最小、低风险的消费方式——\n  // 让 tooltip 报一句\"数据截至几点\"，运维不用另外去猜面板有没有卡住。\n  if (lastGeneratedAt !== null) {\n    label += t(\"ev.pollStatus.generatedAtSuffix\", { time: fmtInstant(lastGeneratedAt, offsetMs()) });\n  }\n  nodes.pollDot.title = label;\n  nodes.pollDot.setAttribute(\"aria-label\", label);\n}\n\nfunction eventRow(item, grouped) {\n  const tr = el(\"tr\", { class: grouped ? \"ev-row ev-row-grouped\" : \"ev-row\" });\n  tr.appendChild(el(\"td\", { class: \"mono\" }, fmtInstant(item && item.ts, offsetMs())));\n  const levelCell = el(\"td\");\n  const level = effectiveLevel(item);\n  levelCell.appendChild(el(\"span\", { class: levelBadgeClass(level) }, t(eventLevelLabelKey(level))));\n  tr.appendChild(levelCell);\n  tr.appendChild(el(\"td\", { class: \"mono\" }, item && typeof item.event === \"string\" ? item.event : \"\"));\n  tr.appendChild(el(\"td\", null, buildDetailText(item)));\n  return tr;\n}\n\nfunction groupHeaderRow(group) {\n  const tr = el(\"tr\", { class: \"ev-group-header\" });\n  const td = el(\"td\", { colspan: \"4\", class: \"muted\" },\n    t(\"ev.timeline\", { count: group.items.length, corr: group.corr }));\n  tr.appendChild(td);\n  return tr;\n}\n\nfunction render() {\n  renderWarnings();\n  renderPollIndicator();\n\n  const host = nodes.body;\n  host.textContent = \"\";\n\n  const filtered = view.filter((item) => matchesSearch(item, state.q));\n  const messageKey = eventsListMessageKey(loadError, view.length, filtered.length, cleared);\n  if (messageKey !== null) {\n    host.appendChild(elI18n(\"p\", messageKey, { class: \"muted\" }));\n    return;\n  }\n\n  const table = el(\"table\");\n  const head = el(\"tr\");\n  for (const key of [\"ev.col.time\", \"ev.col.level\", \"ev.col.event\", \"ev.col.detail\"]) {\n    head.appendChild(elI18n(\"th\", key));\n  }\n  table.appendChild(head);\n\n  const groups = groupEvents(orderForDisplay(filtered));\n  for (const group of groups) {\n    if (group.items.length > 1) table.appendChild(groupHeaderRow(group));\n    for (const item of group.items) table.appendChild(eventRow(item, group.items.length > 1));\n  }\n  host.appendChild(table);\n\n  if (state.autoScroll) host.scrollTop = host.scrollHeight;\n}\n\nasync function poll() {\n  if (abort) abort.abort();\n  abort = new AbortController();\n  try {\n    const query = eventsQuery({ ...state, after: pollState.after, limit: LIMIT });\n    const body = await api.get(`/events?${query}`, { signal: abort.signal });\n    const items = itemsOf(body) ?? [];\n    lastStatus = bufferStatus(body);\n    lastShardId = shardIdOf(body);\n    lastGeneratedAt = generatedAtOf(body);\n    loadError = false;\n    lastError = false;\n    // 评审 C6 二审 / 四审 B1：游标自愈、视图要不要跟着清空、退避间隔看不看到\n    // \"新内容\"、自愈状态什么时候清位——同一个纯状态转换的四个面，**全部**在\n    // pollOutcome() 里（admin-ui/README.md 硬规则 1）。这里只剩两件拼装：视图\n    // 要不要清、把返回的下一轮状态整体收下。一个判据都不许再回到这个文件。\n    const outcome = pollOutcome(pollState, items, body && body.cursor, lastStatus.cursorAhead);\n    if (outcome.resetView) view = [];\n    view = mergeIntoView(view, items);\n    // 视图里重新有内容了，「已清空」那句话就不再成立（它只描述\"空是怎么来的\"）。\n    if (view.length > 0) cleared = false;\n    pollState = outcome.next;\n  } catch (e) {\n    if (e && e.name === \"AbortError\") return;\n    lastError = true;\n    loadError = true;\n    // **不清空 view**：一次轮询失败不该把已经看到的历史事件抹掉，那比「暂时看不到\n    // 最新的」更像撒谎——运维正在盯着的是一条正在增长的时间线，不是一个可替换的快照。\n  }\n  render();\n  scheduleNext();\n}\n\nfunction scheduleNext() {\n  if (timer !== null) { clearTimeout(timer); timer = null; }\n  if (state.paused || document.hidden) return;\n  timer = setTimeout(() => { poll(); }, pollState.delayMs);\n}\n\nfunction stopPolling() {\n  if (timer !== null) { clearTimeout(timer); timer = null; }\n  if (abort) { abort.abort(); abort = null; }\n}\n\n/**\n * 页面从隐藏变回可见时，把因为 `document.hidden` 而停掉的轮询接回去。\n *\n * **只在本板块当前处于\"正在显示\"时才生效**（`sectionActive`）：不加这一层，\n * 从别的 tab 切回来时会把任何板块（哪怕当前显示的是概览页、本板块早被\n * `onHide` 正常停掉）误判成\"因为隐藏而停了\"，重新点起一轮不该发生的请求。\n * 只注册一次（模块级监听，不随 init/onShow 重复挂）。\n */\ndocument.addEventListener(\"visibilitychange\", () => {\n  if (!document.hidden && sectionActive && !state.paused && timer === null) poll();\n});\n\nasync function download() {\n  try {\n    const res = await api.raw(\"GET\", \"/events/download\");\n    const text = await res.text();\n    const blob = new Blob([text], { type: \"text/plain;charset=utf-8\" });\n    const url = URL.createObjectURL(blob);\n    const a = el(\"a\", { href: url, download: \"agnes2api-events.txt\" });\n    document.body.appendChild(a);\n    a.click();\n    a.remove();\n    URL.revokeObjectURL(url);\n  } catch (e) {\n    // 下载失败要让用户看得见——按钮点了没反应、又没有任何提示，是本仓已经踩过的\n    // 那类\"看起来什么都没发生\"的坑，本仓已经有 toast 这个组件，直接用。\n    toast(t(\"ev.downloadFailed\"), \"err\");\n  }\n}\n\nfunction buildToolbar() {\n  const bar = el(\"div\", { class: \"toolbar\" });\n\n  const search = el(\"input\", { type: \"search\", \"data-i18n-ph\": \"ev.search\" });\n  search.setAttribute(\"placeholder\", t(\"ev.search\"));\n  search.addEventListener(\"input\", () => { state.q = search.value; render(); });\n  bar.appendChild(search);\n\n  const levelGroup = el(\"div\", { class: \"btn-group\" });\n  const levelButtons = {};\n  const allBtn = elI18n(\"button\", \"ev.level.all\", { type: \"button\", class: \"btn-toggle active\" });\n  allBtn.addEventListener(\"click\", () => { setLevel(\"all\"); });\n  levelGroup.appendChild(allBtn);\n  levelButtons.all = allBtn;\n  for (const lvl of LEVELS) {\n    const b = elI18n(\"button\", levelLabelKey(lvl), { type: \"button\", class: \"btn-toggle\" });\n    b.addEventListener(\"click\", () => { setLevel(lvl); });\n    levelGroup.appendChild(b);\n    levelButtons[lvl] = b;\n  }\n  bar.appendChild(levelGroup);\n\n  const pauseBtn = elI18n(\"button\", \"ev.pause\", { type: \"button\" });\n  pauseBtn.addEventListener(\"click\", () => {\n    state.paused = !state.paused;\n    pauseBtn.textContent = t(state.paused ? \"ev.resume\" : \"ev.pause\");\n    pauseBtn.setAttribute(\"data-i18n\", state.paused ? \"ev.resume\" : \"ev.pause\");\n    renderPollIndicator();\n    if (state.paused) stopPolling(); else scheduleNext();\n  });\n  bar.appendChild(pauseBtn);\n\n  const clearBtn = elI18n(\"button\", \"ev.clear\", { type: \"button\", \"data-i18n-title\": \"ev.clearTip\" });\n  clearBtn.title = t(\"ev.clearTip\");\n  // **清空之后必须置位 `cleared`**（全分支评审 I5）：不置位的话列表区会显示\n  // 「还没有事件。」，与这个按钮自己的 tooltip 当场矛盾，而且那是假话——服务端\n  // 明明有事件。游标刻意不回退（理由见 pure/events.mjs 的 eventsListMessageKey）。\n  clearBtn.addEventListener(\"click\", () => { view = []; cleared = true; render(); });\n  bar.appendChild(clearBtn);\n\n  const downloadBtn = elI18n(\"button\", \"ev.download\", { type: \"button\" });\n  downloadBtn.addEventListener(\"click\", () => { download(); });\n  bar.appendChild(downloadBtn);\n\n  const autoScrollWrap = el(\"label\", { class: \"auto\" });\n  const autoScrollBox = el(\"input\", { type: \"checkbox\" });\n  autoScrollBox.checked = state.autoScroll;\n  autoScrollBox.addEventListener(\"change\", () => { state.autoScroll = autoScrollBox.checked; });\n  autoScrollWrap.appendChild(autoScrollBox);\n  autoScrollWrap.appendChild(elI18n(\"span\", \"ev.autoScroll\"));\n  bar.appendChild(autoScrollWrap);\n\n  const pollDot = el(\"span\", { class: \"poll-dot poll-dot-active\" });\n  bar.appendChild(pollDot);\n\n  function setLevel(lvl) {\n    state.level = lvl;\n    for (const [k, b] of Object.entries(levelButtons)) b.classList.toggle(\"active\", k === lvl);\n    // 切换级别相当于换了一条筛选后的流：已攒的视图是按旧筛选拉来的，继续拼接会让\n    // 「全部/error」两种视图的历史深度不一致。重置视图与整份轮询状态（游标、\n    // 自愈中、退避一起归零），从当前时刻重新拉。\n    view = [];\n    cleared = false;\n    pollState = initialPollState();\n    poll();\n  }\n\n  return { bar, pollDot };\n}\n\nexport const eventsSection = {\n  init(section) {\n    section.textContent = \"\";\n    section.appendChild(elI18n(\"h2\", \"ev.title\"));\n    section.appendChild(elI18n(\"p\", \"ev.notice\", { class: \"muted note\" }));\n\n    const warnBanner = el(\"div\", { class: \"banner-danger\" });\n    warnBanner.style.display = \"none\";\n    const warnDropped = el(\"p\");\n    const warnBudget = el(\"p\");\n    const warnTruncated = el(\"p\");\n    const warnCursorAhead = el(\"p\");\n    warnBanner.appendChild(warnDropped);\n    warnBanner.appendChild(warnBudget);\n    warnBanner.appendChild(warnTruncated);\n    warnBanner.appendChild(warnCursorAhead);\n    section.appendChild(warnBanner);\n\n    const tb = buildToolbar();\n    section.appendChild(tb.bar);\n\n    const body = el(\"div\", { class: \"events-body\" });\n    section.appendChild(body);\n\n    nodes = { body, warnBanner, warnDropped, warnBudget, warnTruncated, warnCursorAhead, pollDot: tb.pollDot };\n  },\n\n  onShow() {\n    sectionActive = true;\n    loadError = false;\n    lastError = false;\n    // 保留游标（已经看过的事件不该因为切走又切回来再拉一遍），退避与自愈状态归零。\n    // 这条同样是判据，写在 pure/events.mjs 里，不在这里手写三行赋值。\n    pollState = resumePollState(pollState);\n    poll();\n  },\n\n  onHide() {\n    sectionActive = false;\n    stopPolling();\n  },\n};\n", type: "text/javascript; charset=utf-8", etag: "\"6bd4bbf10b821ed9\"" },
  "/admin/js/sec-keys.js": { body: "/**\n * Key 池板块。**本期只做只读部分**（设计文档 §10.2 的骨架）：\n * 状态筛选 → 4 张汇总卡 → 分页列表 → 新鲜度提示。\n * 批量条、添加 Key、以及任何动作按钮都是 P3c 的，这里一个都没有。\n *\n * 板块契约（设计文档 §9.3）：`{ init?, onShow?, onHide? }`，见 admin-ui/js/app.js\n * 的 showSection。**板块内不许监听 langchange**——框架层会 apply(document) 之后\n * 重跑一次 onShow()。\n *\n * 两条纪律：①一切来自接口的内容一律 textContent；②**取值决策一律不写在这里**，\n * 全在 `js/pure/keys.mjs` 里由 `tests/ui/keys.test.ts` 跑着（admin-ui/README.md\n * 硬规则 1）。这个文件只剩 DOM 拼装、事件绑定与网络调用。\n */\nimport { api } from \"./api.js\";\nimport { t } from \"./i18n.js\";\nimport { el, elI18n } from \"./ui.js\";\nimport { fmtCount, fmtDash, fmtDuration, fmtInstant, fmtPercent } from \"./pure/format.mjs\";\nimport {\n  CARDS, AUTO_SECONDS, cardCounts, badgeClass, bucketLabelKey, autoLabelKey,\n  keysQuery, cooldownRemaining, lastErrorParts, usageParts, lastUsedParts,\n  pagerState, listMessageKey, itemsOf,\n} from \"./pure/keys.mjs\";\n// **carry-forward（Task 4 → Task 5）**：`{ttl}` / `{touch}` / `{poolTtl}` 三个占位符\n// 在 Task 4 交付时没有数据源，暂用「点名旋钮 + 括注默认值」。`poolKnobs()` 是\n// `GET /admin/api/overview` 的 `freshness` 块（Task 5）投影出来的这两个旋钮当前\n// 生效值，与概览板块共用同一份取值决策（admin-ui/README.md 硬规则 1）。\nimport { poolKnobs } from \"./pure/overview.mjs\";\n\nconst PAGE_SIZE = 20;\n/** 搜索防抖。每敲一个字符打一次接口的话，大池子下每次都要重投影 + 序列化整池。 */\nconst SEARCH_DEBOUNCE_MS = 250;\n\nconst state = { bucket: \"all\", q: \"\", page: 1, size: PAGE_SIZE, autoSec: 0 };\n\nlet nodes = null;\nlet timer = null;\nlet searchTimer = null;\n/** 在飞请求的取消闸。离开板块 / 发起下一次请求时作废上一次，避免旧响应盖掉新数据。 */\nlet abort = null;\nlet data = null;\nlet loadError = false;\n/**\n * `POOL_CACHE_TTL_MS` / `POOL_TOUCH_INTERVAL_MS` 的当前生效值。**只拉一次**——\n * 这两个旋钮是建 app 时读一次的部署期常量，不随 `ConfigHolder` 刷新（见 wire.ts），\n * 没必要跟着每次 `load()` / 自动刷新重新去问。默认 null（渲染成 —），\n * 拿到之前不假装知道旧的硬编码默认值。\n */\nlet knobs = { ttl: null, touch: null };\n\n/** 汇总卡与筛选下拉里的条数。**没有数据时 fmtCount(null) 给出 `—`，不是 0。** */\nfunction syncCounts(shown) {\n  const c = cardCounts(shown);\n  for (const b of CARDS) {\n    nodes.cardValues[b].textContent = fmtCount(c[b]);\n    nodes.cardLabels[b].textContent = t(bucketLabelKey(b));\n    nodes.options[b].textContent = `${t(bucketLabelKey(b))}（${fmtCount(c[b])}）`;\n  }\n  for (const sec of AUTO_SECONDS) nodes.autoOptions[sec].textContent = t(autoLabelKey(sec));\n}\n\n/** `≈` 标记。它是产品不变式的一部分（近似值必须打标），由后端的 `approximate` 驱动。 */\nfunction approxMark() {\n  return el(\"span\", { class: \"approx\", title: t(\"keys.approxTip\", { touch: fmtDuration(knobs.touch) }) }, \"≈\");\n}\n\nfunction usageCell(v, approximate) {\n  const cell = el(\"td\");\n  const u = usageParts(v, approximate);\n  if (u.approx) cell.appendChild(approxMark());\n  cell.appendChild(el(\"span\", null, `${u.approx ? \" \" : \"\"}${fmtCount(u.requests)}`));\n  // 分母为 0 时 fmtPercent 返回 —，不是 0.0%：「一次都没跑过」与「成功率 0%」是两回事。\n  cell.appendChild(el(\"span\", { class: \"muted\" }, ` · ${fmtPercent(u.success, u.requests)}`));\n  return cell;\n}\n\nfunction lastUsedCell(v, approximate, offset) {\n  const cell = el(\"td\");\n  const l = lastUsedParts(v, approximate);\n  if (l.approx) {\n    // 「最后使用」与计数是同一份 staleness（同一次落盘一起带下去），tooltip 单独一条：\n    // 它说的是「时刻粗到一个触达间隔」，与计数那条「少计 + 晚落盘」不是同一句话。\n    cell.appendChild(el(\"span\", {\n      class: \"approx\", title: t(\"keys.approxLastUsedTip\", { touch: fmtDuration(knobs.touch) }),\n    }, \"≈\"));\n    cell.appendChild(el(\"span\", null, ` ${fmtInstant(l.at, offset)}`));\n  } else {\n    cell.appendChild(el(\"span\", null, l.at === null ? fmtDash(null) : fmtInstant(l.at, offset)));\n  }\n  return cell;\n}\n\nfunction row(v, now, offset, approximate) {\n  const tr = el(\"tr\");\n  tr.appendChild(el(\"td\", null, `#${v.seq}`));\n  tr.appendChild(el(\"td\", { class: \"mono\" }, v.masked));\n  const bucketCell = el(\"td\");\n  bucketCell.appendChild(el(\"span\", { class: badgeClass(v.bucket) }, t(bucketLabelKey(v.bucket))));\n  tr.appendChild(bucketCell);\n  tr.appendChild(el(\"td\", null, fmtInstant(v.addedAt, offset)));\n  tr.appendChild(lastUsedCell(v, approximate, offset));\n  const left = cooldownRemaining(v, now);\n  tr.appendChild(el(\"td\", null, left === null ? fmtDash(null) : fmtDuration(left)));\n  tr.appendChild(el(\"td\", null, fmtCount(v.strikes)));\n  tr.appendChild(usageCell(v, approximate));\n  const err = lastErrorParts(v);\n  tr.appendChild(el(\"td\", null, err === null ? fmtDash(null) : `${err.kind}（${fmtInstant(err.at, offset)}）`));\n  return tr;\n}\n\nfunction render() {\n  // **读失败一律当「没有数据」，且只判这一次**：三处各写一份 `loadError ? ... : data`\n  // 的话，下一次改动很容易只改其中两处（评审 N4）。\n  const shown = loadError ? null : data;\n  syncCounts(shown);\n\n  // 两个旋钮的当前生效值可能比首次 render() 晚到（异步拉 /overview），\n  // 每次 render() 都用 `knobs` 现有的值重写这两句——拿到之后立刻生效，没拿到时\n  // fmtDuration(null) 给出 —，不假装知道旧的硬编码默认值。\n  nodes.autoNote.textContent = t(\"keys.autoNote\", { ttl: fmtDuration(knobs.ttl) });\n  nodes.freshnessNote.textContent = t(\"keys.freshness\", { poolTtl: fmtDuration(knobs.ttl) });\n\n  // 分页控件先复位：读失败 / 空列表时留着上一次的「第 1/2 页 · 共 3 条」，\n  // 等于在展示一份已经不存在的数据。\n  const pager = pagerState(shown);\n  nodes.prev.disabled = pager.prevDisabled;\n  nodes.next.disabled = pager.nextDisabled;\n  nodes.pageInfo.textContent = pager.info === null\n    ? \"\"\n    : t(\"keys.pageInfo\", { page: pager.info.page, pages: pager.info.pages, total: pager.info.total });\n\n  const host = nodes.body;\n  host.textContent = \"\";\n  const messageKey = listMessageKey(shown, loadError);\n  if (messageKey !== null) {\n    host.appendChild(elI18n(\"p\", messageKey, { class: \"muted\" }));\n    return;\n  }\n  // 没有可渲染的条目就到此为止——判据与上面两处**共用同一个 itemsOf**，\n  // 畸形响应（items 不是数组）不会走到下面那个 for 里去抛异常。\n  const items = itemsOf(shown);\n  if (items === null) return;\n\n  const table = el(\"table\");\n  const head = el(\"tr\");\n  for (const key of [\n    \"keys.col.seq\", \"keys.col.key\", \"keys.col.bucket\", \"keys.col.addedAt\", \"keys.col.lastUsedAt\",\n    \"keys.col.cooldown\", \"keys.col.strikes\", \"keys.col.usage\", \"keys.col.lastError\",\n  ]) head.appendChild(elI18n(\"th\", key));\n  table.appendChild(head);\n  // 时区必须从参数进 fmtInstant，不许它去读运行环境的本地时区（见 pure/format.mjs）。\n  const offset = -new Date().getTimezoneOffset() * 60000;\n  for (const v of items) table.appendChild(row(v, shown.generatedAt, offset, shown.approximate));\n  host.appendChild(table);\n}\n\n/**\n * 拉一次 `/overview` 取两个旋钮的当前生效值。**只拉一次**（见 `knobs` 的说明），\n * 拿到之后重渲一次让文案立刻换上真实值；拿不到就保持 —，不重试到下一次 onShow。\n */\nasync function loadKnobs() {\n  if (knobs.ttl !== null || knobs.touch !== null) return;\n  try {\n    const body = await api.get(\"/overview\");\n    knobs = poolKnobs(body);\n  } catch (e) {\n    // 读失败：knobs 保持 { ttl: null, touch: null }，文案渲染成 —。\n  }\n  render();\n}\n\nasync function load() {\n  if (abort) abort.abort();\n  abort = new AbortController();\n  try {\n    const body = await api.get(`/keys?${keysQuery(state)}`, { signal: abort.signal });\n    data = body;\n    loadError = false;\n    // 服务端把越界页号回落到第 1 页，本地状态跟上，否则翻页按钮会与实际显示的页对不上。\n    state.page = body.page;\n  } catch (e) {\n    if (e && e.name === \"AbortError\") return;\n    // **不伪造 0，也不留着上一次的数据**：读失败就说读失败，\n    // 显示上一次的数字会让运维以为它是新的。\n    loadError = true;\n    data = null;\n  }\n  render();\n}\n\nfunction stopTimers() {\n  if (timer !== null) { clearInterval(timer); timer = null; }\n  if (searchTimer !== null) { clearTimeout(searchTimer); searchTimer = null; }\n}\n\nfunction restartTimer() {\n  if (timer !== null) { clearInterval(timer); timer = null; }\n  if (state.autoSec > 0) timer = setInterval(() => { load(); }, state.autoSec * 1000);\n}\n\nfunction buildToolbar() {\n  const bar = el(\"div\", { class: \"toolbar\" });\n\n  const search = el(\"input\", { type: \"search\", \"data-i18n-ph\": \"keys.search\" });\n  search.setAttribute(\"placeholder\", t(\"keys.search\"));\n  search.addEventListener(\"input\", () => {\n    state.q = search.value;\n    state.page = 1;\n    if (searchTimer !== null) clearTimeout(searchTimer);\n    searchTimer = setTimeout(() => { searchTimer = null; load(); }, SEARCH_DEBOUNCE_MS);\n  });\n  bar.appendChild(search);\n\n  const select = el(\"select\", { \"data-i18n-title\": \"keys.filter\" });\n  // 初始 title / aria-label 必须在这里写死一次：`apply(document)` 在 boot 时就跑完了，\n  // 而这棵子树是之后才建的，只挂 data-i18n-title 的话要等一次切语言才有无障碍标签。\n  select.setAttribute(\"title\", t(\"keys.filter\"));\n  select.setAttribute(\"aria-label\", t(\"keys.filter\"));\n  const options = {};\n  for (const b of CARDS) {\n    const o = el(\"option\", { value: b });\n    select.appendChild(o);\n    options[b] = o;\n  }\n  select.value = state.bucket;\n  select.addEventListener(\"change\", () => { state.bucket = select.value; state.page = 1; load(); });\n  bar.appendChild(select);\n\n  const refresh = elI18n(\"button\", \"common.refresh\", { type: \"button\" });\n  refresh.addEventListener(\"click\", () => { load(); });\n  bar.appendChild(refresh);\n\n  const autoWrap = el(\"label\", { class: \"auto\" });\n  autoWrap.appendChild(elI18n(\"span\", \"keys.auto\"));\n  const auto = el(\"select\");\n  const autoOptions = {};\n  for (const sec of AUTO_SECONDS) {\n    const o = el(\"option\", { value: String(sec) });\n    auto.appendChild(o);\n    autoOptions[sec] = o;\n  }\n  auto.value = String(state.autoSec);\n  auto.addEventListener(\"change\", () => { state.autoSec = Number(auto.value); restartTimer(); });\n  autoWrap.appendChild(auto);\n  bar.appendChild(autoWrap);\n\n  return { bar, options, autoOptions };\n}\n\nexport const keysSection = {\n  init(section) {\n    section.textContent = \"\";\n    section.appendChild(elI18n(\"h2\", \"keys.title\"));\n\n    const tb = buildToolbar();\n    section.appendChild(tb.bar);\n    // 自动刷新的开销**如实写**：这个板块与转发共用同一份 isolate 快照，确实不额外\n    // 烧存储配额。这里不抄一个吓人的估算数字——那同样是撒谎。\n    // 文案含 `{ttl}` 占位符，不用 elI18n（那是给静态、无插值文案用的）——\n    // 由 render() 每次用当前的 `knobs.ttl` 重写 textContent。\n    const autoNote = el(\"p\", { class: \"muted note\" });\n    section.appendChild(autoNote);\n\n    const cardRow = el(\"div\", { class: \"card-row\" });\n    const cardValues = {};\n    const cardLabels = {};\n    for (const b of CARDS) {\n      const card = el(\"div\", { class: \"card\" });\n      cardLabels[b] = el(\"div\", { class: \"label\" });\n      cardValues[b] = el(\"div\", { class: \"value\" });\n      card.appendChild(cardLabels[b]);\n      card.appendChild(cardValues[b]);\n      cardRow.appendChild(card);\n    }\n    section.appendChild(cardRow);\n\n    const body = el(\"div\", { class: \"keys-body\" });\n    section.appendChild(body);\n\n    const pager = el(\"div\", { class: \"pager\" });\n    const prev = elI18n(\"button\", \"keys.prev\", { type: \"button\" });\n    const next = elI18n(\"button\", \"keys.next\", { type: \"button\" });\n    const pageInfo = el(\"span\", { class: \"muted\" });\n    prev.addEventListener(\"click\", () => { if (state.page > 1) { state.page--; load(); } });\n    next.addEventListener(\"click\", () => { state.page++; load(); });\n    pager.appendChild(prev);\n    pager.appendChild(pageInfo);\n    pager.appendChild(next);\n    section.appendChild(pager);\n\n    // 新鲜度提示：与概览页共用同一份文案（设计文档 §10.1 / §10.2 的「新鲜度提示条」）。\n    // 同样含插值占位符，理由同上面的 autoNote。\n    const freshnessNote = el(\"p\", { class: \"muted note\" });\n    section.appendChild(freshnessNote);\n\n    nodes = {\n      body, pageInfo, prev, next,\n      options: tb.options, autoOptions: tb.autoOptions,\n      cardValues, cardLabels, autoNote, freshnessNote,\n    };\n  },\n\n  onShow() {\n    load();\n    loadKnobs();\n    restartTimer();\n  },\n\n  onHide() {\n    stopTimers();\n    // **作废在飞请求**：不作废的话切回来时旧响应可能盖掉新数据（板块契约 §9.3）。\n    if (abort) { abort.abort(); abort = null; }\n  },\n};\n", type: "text/javascript; charset=utf-8", etag: "\"a1ab9843efce08fb\"" },
  "/admin/js/sec-overview.js": { body: "/**\n * 概览板块（设计文档 §10.1，本期形状见 P3b 计划 Task 5 Step 7）：\n * 4 张池子卡 → 运行时信息面板 → 新鲜度卡 → 累计用量卡 → 配置摘要 → 存储卡。\n *\n * 板块契约（设计文档 §9.3）：`{ init?, onShow?, onHide? }`，见 admin-ui/js/app.js\n * 的 showSection。**板块内不许监听 langchange**——框架层会 apply(document) 之后\n * 重跑一次 onShow()。\n *\n * 两条纪律：①一切来自接口的内容一律 textContent；②**取值决策一律不写在这里**，\n * 全在 `js/pure/overview.mjs` 里由 `tests/ui/overview.test.ts` 跑着（admin-ui/README.md\n * 硬规则 1）。这个文件只剩 DOM 拼装、事件绑定与网络调用。\n *\n * **一切形态分支只读接口返回的数据**（`process === null` / `storage.backend` /\n * `runtime.name` 这些来自响应体的字段），不许自己嗅探运行时（硬约束 1）。\n */\nimport { api } from \"./api.js\";\nimport { t } from \"./i18n.js\";\nimport { el, elI18n } from \"./ui.js\";\nimport { fmtCount, fmtDash, fmtDuration, fmtInstant, fmtPercent, fmtBytesMb } from \"./pure/format.mjs\";\nimport {\n  POOL_CARDS, poolCardLabelKey, runtimeNameLabelKey, storageBackendLabelKey,\n  poolCounts, processCells, usageStats, configSummary, storageInfo,\n  freshnessValues, kvReadEstimatePerIsolatePerDay,\n} from \"./pure/overview.mjs\";\n\nlet nodes = null;\nlet abort = null;\n/**\n * 最近一次成功的 `/overview` 响应；`null` 表示「还没有过一次成功」——\n * 唯一状态源，不另设 `loadError` 标记：本板块所有渲染函数只按 `data === null`\n * 分支（不像 Key 池板块要区分「空列表」与「读失败」两种不同文案），\n * 两份状态各写各的只会漂移。\n */\nlet data = null;\n/**\n * `/capabilities` 只拉一次（静态数据：版本号、colo、quota model 这些在一个\n * isolate/进程的生命周期里不会变），不跟着每次刷新重新拉——它的**零存储读**特性\n * 值得在前端也体现成「零额外网络往返」，而不是每次点刷新都再打一次。\n */\nlet caps = null;\n\nfunction offsetMs() { return -new Date().getTimezoneOffset() * 60000; }\n\n/** 建一张 `.card`（4 张池子卡 / 运行时信息面板复用同一个原语）。 */\nfunction tile(labelKey) {\n  const card = el(\"div\", { class: \"card\" });\n  card.appendChild(elI18n(\"div\", labelKey, { class: \"label\" }));\n  const value = el(\"div\", { class: \"value\" });\n  card.appendChild(value);\n  return { card, value };\n}\n\n/** 建一个内容块：标题 + 空的 body 容器，供各卡片各自往里塞段落。 */\nfunction block(titleKey) {\n  const wrap = el(\"div\", { class: \"card block\" });\n  wrap.appendChild(elI18n(\"h3\", titleKey));\n  const body = el(\"div\");\n  wrap.appendChild(body);\n  return { wrap, body };\n}\n\n/** 「标签: 值」一行。`labelKey` 走 i18n，值由调用方之后自己 textContent。 */\nfunction row(labelKey) {\n  const p = el(\"p\");\n  p.appendChild(el(\"span\", { class: \"muted\" }, `${t(labelKey)}: `));\n  const value = el(\"span\");\n  p.appendChild(value);\n  return { p, value };\n}\n\nfunction renderPoolCards() {\n  const c = poolCounts(data);\n  for (const card of POOL_CARDS) nodes.pool[card].textContent = fmtCount(c[card]);\n}\n\n/**\n * 运行时信息面板的 8 格。**判据一律来自 `processCells()` 的 `kind`**\n * （产品不变式 11：不是 0、不是空、不隐藏格子）。`colo` 只在 `/capabilities`\n * 加载成功后才有；没拿到时格子仍在，显示 `—`。\n */\nfunction renderRuntimeTiles() {\n  const n = nodes.runtime;\n  n.version.textContent = data && typeof data.version === \"string\" ? data.version : fmtDash(null);\n\n  const runtimeName = data && data.runtime && typeof data.runtime.name === \"string\" ? data.runtime.name : null;\n  if (runtimeName === null) {\n    n.runtimeLabel.textContent = fmtDash(null);\n  } else {\n    const runtimeLabel = t(runtimeNameLabelKey(runtimeName));\n    const colo = caps && caps.runtime && typeof caps.runtime.colo === \"string\" ? caps.runtime.colo : null;\n    n.runtimeLabel.textContent = colo === null ? runtimeLabel : `${runtimeLabel} (${colo})`;\n  }\n\n  n.serverTime.textContent = data && typeof data.serverTime === \"number\"\n    ? fmtInstant(data.serverTime, offsetMs()) : fmtDash(null);\n\n  const si = storageInfo(data);\n  n.storageBackend.textContent = si.backend === null ? fmtDash(null) : t(storageBackendLabelKey(si.backend));\n\n  const p = processCells(data);\n  const serverless = t(\"ov.runtime.serverless\");\n  n.memory.textContent = p.kind === \"serverless\" ? serverless : fmtBytesMb(p.kind === \"metrics\" ? p.rssBytes : null);\n  n.uptime.textContent = p.kind === \"serverless\" ? serverless : fmtDuration(p.kind === \"metrics\" ? p.uptimeMs : null);\n  n.pid.textContent = p.kind === \"serverless\" ? serverless : fmtCount(p.kind === \"metrics\" ? p.pid : null);\n\n  n.writable.textContent = si.writable === null\n    ? fmtDash(null)\n    : t(si.writable ? \"ov.runtime.writableYes\" : \"ov.runtime.writableNo\")\n      + (si.checkedAt === null ? \"\" : ` (${t(\"ov.runtime.checkedAt\", { at: fmtInstant(si.checkedAt, offsetMs()) })})`);\n}\n\nfunction renderFreshness() {\n  const f = freshnessValues(data);\n  nodes.freshness.pool.textContent = f.poolCacheTtlMs === null\n    ? fmtDash(null)\n    : t(\"ov.freshness.pool\", {\n      upper: fmtDuration(f.poolVisibilityUpperBoundMs),\n      ttl: fmtDuration(f.poolCacheTtlMs),\n      edge: fmtDuration(f.kvEdgeCacheMs),\n    });\n  nodes.freshness.config.textContent = f.configTtlMs === null\n    ? fmtDash(null)\n    : t(\"ov.freshness.config\", {\n      upper: fmtDuration(f.configVisibilityUpperBoundMs),\n      ttl: fmtDuration(f.configTtlMs),\n      edge: fmtDuration(f.kvEdgeCacheMs),\n    });\n}\n\n/** `≈` 标记。它是产品不变式的一部分（近似值必须打标），由后端的 `approximate` 驱动。 */\nfunction approxMark() {\n  return el(\"span\", { class: \"approx\", title: t(\"ov.usage.approxTip\") }, \"≈ \");\n}\n\nfunction renderUsage() {\n  const u = usageStats(data);\n  const fillTile = (node, text) => {\n    node.textContent = \"\";\n    if (u.approx) node.appendChild(approxMark());\n    node.appendChild(el(\"span\", null, text));\n  };\n  fillTile(nodes.usage.requests, fmtCount(u.requests));\n  fillTile(nodes.usage.success, fmtCount(u.success));\n  fillTile(nodes.usage.failed, fmtCount(u.failed));\n  fillTile(nodes.usage.clientErrors, fmtCount(u.clientErrors));\n  fillTile(nodes.usage.successRate, fmtPercent(u.success, u.requests));\n}\n\nfunction renderConfig() {\n  const c = configSummary(data);\n  // **`c === null` = 整块读失败，逐格显示 —**；`c` 存在时 `primary`/`fallback`\n  // 仍可能合法为 null（注册机未启用），那种情形显示「无」而不是 ———两种 null\n  // 的来源不同，见 configSummary 的说明，调用方必须先判这一层再往下取字段。\n  nodes.config.banner.style.display = c !== null && c.degraded === true ? \"\" : \"none\";\n  nodes.config.registrar.textContent = c === null || c.registrarEnabled === null\n    ? fmtDash(null) : t(c.registrarEnabled ? \"ov.config.on\" : \"ov.config.off\");\n  nodes.config.primary.textContent = c === null ? fmtDash(null) : (c.primary === null ? t(\"ov.config.none\") : c.primary);\n  nodes.config.fallback.textContent = c === null ? fmtDash(null) : (c.fallback === null ? t(\"ov.config.none\") : c.fallback);\n  nodes.config.targetKeys.textContent = c === null ? fmtDash(null) : fmtCount(c.targetKeys);\n  if (c === null) {\n    // ⚠️ **降级态也要带标签。** 这一行不再走 `row()` 之后（见 buildConfigCard），\n    // 直接写 `fmtDash(null)` 会让整段读失败时前四行是「注册机：—」「主通道：—」…、\n    // 第五行变成孤零零一个 `—`：修掉一个 `{count}` 泄漏，换来一处标签丢失。\n    // 整句仍由这一个节点承载，只是把 `{count}` 换成破折号。\n    nodes.config.envLocked.textContent = t(\"ov.config.envLocked\", { count: fmtDash(null) });\n    nodes.config.envLocked.removeAttribute(\"title\");\n  } else {\n    nodes.config.envLocked.textContent = t(\"ov.config.envLocked\", { count: fmtCount(c.envLocked.length) });\n    nodes.config.envLocked.title = c.envLocked.length === 0\n      ? \"\" : t(\"ov.config.envLockedTip\", { fields: c.envLocked.join(\", \") });\n  }\n}\n\nfunction renderStorageCard() {\n  const si = storageInfo(data);\n  nodes.storageCard.backend.textContent = si.backend === null\n    ? fmtDash(null) : t(storageBackendLabelKey(si.backend));\n  nodes.storageCard.writable.textContent = si.writable === null\n    ? fmtDash(null) : t(si.writable ? \"ov.runtime.writableYes\" : \"ov.runtime.writableNo\");\n\n  if (si.backend === null) {\n    nodes.storageCard.note.textContent = fmtDash(null);\n  } else if (si.backend === \"kv\") {\n    const estimate = kvReadEstimatePerIsolatePerDay(data);\n    nodes.storageCard.note.textContent = estimate === null\n      ? t(\"ov.storageCard.workerNoteUnknown\")\n      : t(\"ov.storageCard.workerNote\", { estimate: fmtCount(estimate) });\n  } else {\n    nodes.storageCard.note.textContent = t(\"ov.storageCard.nodeNote\");\n  }\n}\n\nfunction render() {\n  // **只读，不改状态**：`data` 由 `load()` 的 try/catch 单独维护，\n  // `render()` 从两条路进来（`load()` 与 `loadCapabilities()` 之后的重渲），\n  // 把「读失败 ⇒ data 置空」这种状态修改留在这里会让 render() 变成一个\n  // 「谁调用它、状态就跟着变」的函数，两条调用路径互相踩脚。所有子渲染函数\n  // 都要能安全处理 data === null（逐块降级来自后端，这里再叠一层\n  // 「整段响应都没读到」的兜底）。\n  renderPoolCards();\n  renderRuntimeTiles();\n  renderFreshness();\n  renderUsage();\n  renderConfig();\n  renderStorageCard();\n}\n\nasync function loadCapabilities() {\n  if (caps !== null) return;\n  try {\n    caps = await api.get(\"/capabilities\");\n  } catch (e) {\n    // 拿不到就是拿不到，colo 那一格保持 —；不重试到下一次 onShow。\n  }\n}\n\nasync function load() {\n  if (abort) abort.abort();\n  abort = new AbortController();\n  try {\n    const body = await api.get(\"/overview\", { signal: abort.signal });\n    data = body;\n  } catch (e) {\n    if (e && e.name === \"AbortError\") return;\n    // **不伪造上一次的数据**：读失败就把 data 清空，不留着旧值以为它是新的。\n    data = null;\n  }\n  render();\n}\n\nfunction buildPoolCards(section) {\n  const cardRow = el(\"div\", { class: \"card-row\" });\n  const values = {};\n  for (const card of POOL_CARDS) {\n    const { card: node, value } = tile(poolCardLabelKey(card));\n    values[card] = value;\n    cardRow.appendChild(node);\n  }\n  section.appendChild(cardRow);\n  return values;\n}\n\nfunction buildRuntimeTiles(section) {\n  section.appendChild(elI18n(\"h3\", \"ov.runtime.title\"));\n  const row1 = el(\"div\", { class: \"card-row\" });\n  const row2 = el(\"div\", { class: \"card-row\" });\n  const specs = [\n    [\"ov.runtime.version\", row1], [\"ov.runtime.runtimeLabel\", row1],\n    [\"ov.runtime.serverTime\", row1], [\"ov.runtime.storageBackend\", row1],\n    [\"ov.runtime.memory\", row2], [\"ov.runtime.uptime\", row2],\n    [\"ov.runtime.pid\", row2], [\"ov.runtime.writable\", row2],\n  ];\n  const values = {};\n  const keyOf = {\n    \"ov.runtime.version\": \"version\", \"ov.runtime.runtimeLabel\": \"runtimeLabel\",\n    \"ov.runtime.serverTime\": \"serverTime\", \"ov.runtime.storageBackend\": \"storageBackend\",\n    \"ov.runtime.memory\": \"memory\", \"ov.runtime.uptime\": \"uptime\",\n    \"ov.runtime.pid\": \"pid\", \"ov.runtime.writable\": \"writable\",\n  };\n  for (const [labelKey, host] of specs) {\n    const { card, value } = tile(labelKey);\n    values[keyOf[labelKey]] = value;\n    host.appendChild(card);\n  }\n  section.appendChild(row1);\n  section.appendChild(row2);\n  return values;\n}\n\nfunction buildFreshnessCard(section) {\n  const { wrap, body } = block(\"ov.freshness.title\");\n  const pool = el(\"p\");\n  const config = el(\"p\");\n  body.appendChild(pool);\n  body.appendChild(config);\n  section.appendChild(wrap);\n  return { pool, config };\n}\n\nfunction buildUsageCard(section) {\n  const { wrap, body } = block(\"ov.usage.title\");\n  const cardRow = el(\"div\", { class: \"card-row\" });\n  const specs = [\n    [\"ov.usage.requests\", \"requests\"], [\"ov.usage.success\", \"success\"],\n    [\"ov.usage.failed\", \"failed\"], [\"ov.usage.clientErrors\", \"clientErrors\"],\n    [\"ov.usage.successRate\", \"successRate\"],\n  ];\n  const values = {};\n  for (const [labelKey, k] of specs) {\n    const { card, value } = tile(labelKey);\n    values[k] = value;\n    cardRow.appendChild(card);\n  }\n  body.appendChild(cardRow);\n  body.appendChild(elI18n(\"p\", \"ov.usage.tip\", { class: \"muted note\" }));\n  section.appendChild(wrap);\n  return values;\n}\n\nfunction buildConfigCard(section) {\n  const banner = elI18n(\"div\", \"ov.config.degradedBanner\", { class: \"banner-danger\" });\n  banner.style.display = \"none\";\n  section.appendChild(banner);\n\n  const { wrap, body } = block(\"ov.config.title\");\n  const registrar = row(\"ov.config.registrar\");\n  const primary = row(\"ov.config.primary\");\n  const fallback = row(\"ov.config.fallback\");\n  const targetKeys = row(\"ov.config.targetKeys\");\n  // ⚠️ **`ov.config.envLocked` 不是标签，是一句自带 `{count}` 的完整句子**\n  //（「被环境变量锁定的字段数：{count}」）。用 `row()` 渲染它，标签那半会调\n  // `t(key)` 且**不带参数** ⇒ 面板上出现裸的 `{count}`，紧接着值那半又把整句\n  // 重复一遍。Task 7 的阶段验收人工冒烟在 Node 形态上实测到了这个形态：\n  //   「被环境变量锁定的字段数：{count}: 被环境变量锁定的字段数：1」\n  // 所以它单独占一行，整句由 renderConfigCard 一次性写进这个 <p>。\n  // 这一类回归现在由 `scripts/check-i18n.mjs` 的第 ⑧ 条挡着（带占位符的 key\n  // 不许被当成不带参数的裸标签用）。\n  const envLocked = el(\"p\");\n  for (const r of [registrar, primary, fallback, targetKeys]) body.appendChild(r.p);\n  body.appendChild(envLocked);\n  section.appendChild(wrap);\n  return {\n    banner,\n    registrar: registrar.value, primary: primary.value, fallback: fallback.value,\n    targetKeys: targetKeys.value, envLocked,\n  };\n}\n\nfunction buildStorageCard(section) {\n  const { wrap, body } = block(\"ov.storageCard.title\");\n  const backend = row(\"ov.storageCard.backend\");\n  const writable = row(\"ov.storageCard.writable\");\n  body.appendChild(backend.p);\n  body.appendChild(writable.p);\n  const note = el(\"p\", { class: \"muted note\" });\n  body.appendChild(note);\n  section.appendChild(wrap);\n  return { backend: backend.value, writable: writable.value, note };\n}\n\nexport const overviewSection = {\n  init(section) {\n    section.textContent = \"\";\n    section.appendChild(elI18n(\"h2\", \"ov.title\"));\n    const refresh = elI18n(\"button\", \"common.refresh\", { type: \"button\" });\n    refresh.addEventListener(\"click\", () => { load(); });\n    section.appendChild(refresh);\n\n    const pool = buildPoolCards(section);\n    const runtime = buildRuntimeTiles(section);\n    const freshness = buildFreshnessCard(section);\n    const usage = buildUsageCard(section);\n    const config = buildConfigCard(section);\n    const storageCard = buildStorageCard(section);\n\n    nodes = { pool, runtime, freshness, usage, config, storageCard };\n  },\n\n  onShow() {\n    loadCapabilities().then(() => render());\n    load();\n  },\n\n  onHide() {\n    if (abort) { abort.abort(); abort = null; }\n  },\n};\n", type: "text/javascript; charset=utf-8", etag: "\"5f4a3a2c0066100a\"" },
  "/admin/js/theme.js": { body: "/**\n * 主题。`boot.js` 已经在 body 绘制之前把 data-theme 落到 html 上了（防闪白），\n * 这里只负责运行期的读写与广播。\n *\n * light 时**移除属性**而不是设成 \"light\"：CSS 里 :root 是亮色全量 token，\n * [data-theme=\"dark\"] 整体覆盖，多一个 light 值只会多一条永远匹配不上的规则。\n */\nimport { THEME_STORE as STORE } from \"./pure/storage-keys.mjs\";\n\nexport function getTheme() {\n  return document.documentElement.getAttribute(\"data-theme\") === \"dark\" ? \"dark\" : \"light\";\n}\n\nexport function setTheme(next) {\n  const dark = next === \"dark\";\n  if (dark) document.documentElement.setAttribute(\"data-theme\", \"dark\");\n  else document.documentElement.removeAttribute(\"data-theme\");\n  try { localStorage.setItem(STORE, dark ? \"dark\" : \"light\"); } catch (e) { /* 隐私模式 */ }\n  const meta = document.querySelector('meta[name=\"theme-color\"]');\n  if (meta) meta.setAttribute(\"content\", dark ? \"#14161a\" : \"#f7f8fa\");\n  document.dispatchEvent(new CustomEvent(\"themechange\", { detail: { theme: dark ? \"dark\" : \"light\" } }));\n}\n\nexport function toggleTheme() { setTheme(getTheme() === \"dark\" ? \"light\" : \"dark\"); }\n", type: "text/javascript; charset=utf-8", etag: "\"8c0fb5c57b565798\"" },
  "/admin/js/ui.js": { body: "/**\n * 公共 UI 原语。kiro2api 没有这一层，后果是 openModal 有 3 份、confirmModal 3 份、\n * svgIcon 3 份**不同的**实现——那是全局命名空间下没有强制约束的必然结果。\n *\n * 两条纪律贯穿本文件：\n * ① **一切来自接口的内容一律 textContent，永不 innerHTML。** 事件字段里会出现上游返回的内容。\n * ② **SVG 用 createElementNS 构造，不用 innerHTML**（CSP 的 script-src 'self' 要求零内联脚本，\n *    而 innerHTML 拼 SVG 是这条约束最容易被顺手破坏的地方）。\n */\nimport { t } from \"./i18n.js\";\n\nconst SVG_NS = \"http://www.w3.org/2000/svg\";\n\n/** 建元素。`text` 走 textContent；`attrs` 里 `class`/`data-*` 直接 setAttribute。 */\nexport function el(tag, attrs, text) {\n  const node = document.createElement(tag);\n  if (attrs) for (const [k, v] of Object.entries(attrs)) {\n    if (v === null || v === undefined || v === false) continue;\n    node.setAttribute(k, v === true ? \"\" : String(v));\n  }\n  if (text !== undefined && text !== null) node.textContent = String(text);\n  return node;\n}\n\n/** 建一个带 data-i18n 的元素：文案由 apply() 统一刷，切语言时不必板块自己管。 */\nexport function elI18n(tag, key, attrs) {\n  const node = el(tag, { ...(attrs || {}), \"data-i18n\": key });\n  node.textContent = t(key);\n  return node;\n}\n\n/** 内联 SVG 图标。`d` 是 path 的 d 属性。**零二进制资源**是硬规则（build-ui.mjs 会拦）。 */\nexport function svgIcon(d, size) {\n  const svg = document.createElementNS(SVG_NS, \"svg\");\n  svg.setAttribute(\"viewBox\", \"0 0 24 24\");\n  svg.setAttribute(\"width\", String(size || 16));\n  svg.setAttribute(\"height\", String(size || 16));\n  svg.setAttribute(\"fill\", \"none\");\n  svg.setAttribute(\"stroke\", \"currentColor\");\n  svg.setAttribute(\"stroke-width\", \"2\");\n  svg.setAttribute(\"aria-hidden\", \"true\");\n  const path = document.createElementNS(SVG_NS, \"path\");\n  path.setAttribute(\"d\", d);\n  svg.appendChild(path);\n  return svg;\n}\n\nexport function iconBtn(d, i18nTitleKey, onClick) {\n  const b = el(\"button\", { class: \"icon-btn\", type: \"button\", \"data-i18n-title\": i18nTitleKey });\n  b.setAttribute(\"title\", t(i18nTitleKey));\n  b.setAttribute(\"aria-label\", t(i18nTitleKey));\n  b.appendChild(svgIcon(d));\n  b.addEventListener(\"click\", onClick);\n  return b;\n}\n\n/** toast。`kind` ∈ {\"ok\",\"warn\",\"err\"}。**文案一律 textContent**。 */\nexport function toast(message, kind) {\n  const host = document.getElementById(\"toast-host\");\n  if (!host) return;\n  const node = el(\"div\", { class: `toast toast-${kind || \"ok\"}`, role: \"status\" }, message);\n  host.appendChild(node);\n  setTimeout(() => node.remove(), 4000);\n}\n\nexport function openModal(titleKey, bodyNode, actions) {\n  const back = el(\"div\", { class: \"modal-back\" });\n  const box = el(\"div\", { class: \"modal\", role: \"dialog\", \"aria-modal\": \"true\" });\n  box.appendChild(elI18n(\"h2\", titleKey));\n  box.appendChild(bodyNode);\n  const bar = el(\"div\", { class: \"modal-actions\" });\n  for (const a of actions) {\n    const b = elI18n(\"button\", a.labelKey, { class: a.danger ? \"danger\" : \"\" });\n    b.addEventListener(\"click\", () => { back.remove(); a.onClick && a.onClick(); });\n    bar.appendChild(b);\n  }\n  box.appendChild(bar);\n  back.appendChild(box);\n  document.body.appendChild(back);\n  return () => back.remove();\n}\n\nexport function confirmModal(titleKey, messageKey, onConfirm) {\n  return openModal(titleKey, elI18n(\"p\", messageKey), [\n    { labelKey: \"common.cancel\" },\n    { labelKey: \"common.confirm\", danger: true, onClick: onConfirm },\n  ]);\n}\n\nexport async function copy(text) {\n  try {\n    await navigator.clipboard.writeText(text);\n    toast(t(\"common.copied\"), \"ok\");\n  } catch (e) {\n    // 剪贴板在非 TLS 下不可用是常态，**不要**假装成功。\n    toast(t(\"common.copyFailed\"), \"warn\");\n  }\n}\n", type: "text/javascript; charset=utf-8", etag: "\"92b0445ff51bb0d1\"" },
};

export const UI_BUILD_HASH = "8a28d853979e5d2a";
